(window.MUSEUM_READ_T = window.MUSEUM_READ_T || {})["id"] = {"ui":{"lead":"Bagaimana permainan ditemukan, dilupakan, dipecahkan, dan berubah? Baca {n} kisah dan jawab benar semua soal kuis di akhir untuk mendapat stempel.","card":"Kartu stempel","cardN":"{n} dari {of} terkumpul","cardAll":"Semua terkumpul!","no":"Kisah {n}","mins":"{n} mnt","stamped":"Sudah distempel","back":"Semua kisah","quiz":"Kuis singkat","links":"Lihat dan mainkan","game":"Permainan","exhibit":"Koleksi","art":"Lukisan","room":"Ruang","room_chance":"Peluang","qn":"Soal {n} dari {of}","right":"Benar!","wrong":"Belum tepat — jawaban yang benar sudah ditandai.","got":"Stempel didapat!","again":"Semua benar!","gotSub":"Sudah tercatat di kartu stempel.","missed":"{n} salah","retrySub":"Jawab semua soal dengan benar untuk mendapat stempel. Baca lagi kisahnya lalu coba lagi.","retry":"Coba lagi","room_paint":"Dalam seni","room_map":"Peta","kfH":"Poin utama","tlH":"Lini masa","refH":"Sumber dan bacaan","picLink":"membuka halaman museum"},"ex":{"ur":"Papan Permainan Kerajaan Ur","liubo":"Papan dan bidak liubo","pyrgus":"Menara dadu Romawi","sugoroku":"Papan sugoroku Shōsōin","nishapur":"Set catur Nishapur","lewis":"Bidak catur Lewis","senet":"Kotak senet Tutankhamun","ballinderry":"Papan permainan Ballinderry","goose":"Papan catur dan permainan angsa","kofukuji":"Bidak shogi dari Kōfuku-ji","shosoin":"Papan go Shōsōin"},"paint":{"liubo":"Dua sosok bermain liubo","sugoroku":"Dua gadis bermain sugoroku","shahnama":"Buzurgmihr memecahkan catur","nefertari":"Ratu Nefertari bermain senet","chaupar":"Siwa dan Parwati bermain chaupar","shogi":"Pasangan muda bermain shogi","hydria":"Akhilleus dan Aias Bermain Permainan Papan (guci air)","eakins":"Para Pemain Catur","weiqi":"Piring dengan dewa abadi bermain weiqi","webb":"Pemain backgammon (lemari)","liberale":"Para Pemain Catur","mirror":"Wadah cermin dengan pasangan bermain catur","morris":"Sebuah papan permainan (Nine Men’s Morris)","leifeng":"Papan permainan Pagoda Leifeng","teniers":"Permainan backgammon","imari":"Piring dengan dua pria bermain go","shoei":"Empat Keterampilan","tutinama":"Monyet menggigit pangeran, kawan caturnya (Mughal, sekitar 1560)","ingram":"Permainan Catur Tiongkok","umaya":"Sekat Lipat Istal Kuda (go dan shogi di beranda)","kiyohiro":"Para Pemain Sugoroku","vuillard":"Permainan Dam (dari Pemandangan dan Interior)","kangra":"Pasangan bermain chaupar di teras","posada":"Permainan Angsa","jintile":"Ubin dengan wanita bermain permainan papan","pvl":"Pria Bermain Dadu"},"ur":{"title":"Bagaimana permainan berusia 4.500 tahun mendapatkan kembali aturannya","lead":"Papan dari makam kerajaan Ur ditemukan tanpa petunjuk. Kuncinya ada pada lempeng tanah liat yang ditulis dua ribu tahun kemudian.","s":["Pada 1920-an, Leonard Woolley menggali makam kerajaan di Ur, Irak selatan, dan menemukan papan dua puluh petak bertatahkan cangkang dan lapis lazuli dari sekitar 2600–2400 SM. Papan serupa ditemukan di seluruh Timur Tengah, jadi permainan ini jelas dimainkan luas dan lama.","Namun tak ada keterangan cara bermain yang ikut ditemukan. Ada papan, bidak, dan dadu — tetapi tanpa aturan: masalah yang lazim pada permainan kuno.","Kuncinya tersimpan di gudang British Museum: lempeng berhuruf paku yang disalin pada 177/176 SM oleh juru tulis Babilonia Itti-Marduk-balāṭu dari lempeng milik seseorang bernama Iddin-Bēl. Lempeng ini ditulis lebih dari dua ribu tahun setelah papannya dibuat.","Pada awal 1980-an, Irving Finkel dari British Museum menyadari bahwa lempeng itu menjelaskan permainan dua puluh petak yang sama. Sisi belakangnya menggambarkan papan, dengan pertanda untuk petak tempat bidak berhenti. Dari lempeng dan papan itu sendiri, Finkel merekonstruksi permainan balapan untuk dua orang.","Rekonstruksinya kini dimainkan di seluruh dunia. Apakah orang Ur bermain persis seperti itu, tak ada yang tahu. Namun, permainan serupa masih dimainkan di Kochi, India selatan, hingga 1950-an — tanda betapa panjang umur permainan ini."],"quiz":[["Kapan lempeng yang memberi aturan itu ditulis?","Abad ke-2 SM, lebih dari 2.000 tahun setelah papannya","Sekitar 2600 SM, sezaman dengan papannya","Abad Pertengahan (abad ke-12)","Abad ke-19"],["Siapa yang memecahkan lempeng dan merekonstruksi aturannya?","Irving Finkel","Howard Carter","Jean-François Champollion","Arthur Evans"],["Apa yang ditulis lempeng tentang berhenti di petak?","Pertanda nasib baik atau buruk","Nama-nama raja","Besaran pajak","Hanya nama bintang"]],"kf":["Papan berasal dari sekitar 2600–2400 SM, dari makam kerajaan Ur di Irak selatan","Aturannya disusun ulang dari lempeng tanah liat yang ditulis lebih dari 2.000 tahun kemudian","20 petak, tujuh bidak per pihak, dadu empat sisi"],"more":[{"h":"Makam kerajaan dan “permainan kerajaan”","p":["Woolley menemukan bukan satu, melainkan beberapa papan dua puluh petak di Pemakaman Kerajaan Ur. Yang paling terkenal, kini di British Museum, terbuat dari kayu bertatahkan kerang, batu kapur merah, dan lapis lazuli — dari sinilah nama “Permainan Kerajaan Ur”.","Namun ini bukan permainan untuk raja saja. Papan yang sama ditemukan dari Mesopotamia hingga Mesir dan Mediterania timur, dan di sebuah istana Asyur bahkan ada papan yang digores di alas patung banteng bersayap berkepala manusia penjaga gerbang — tampaknya oleh para penjaga."],"cap":["Permainan Kerajaan Ur di British Museum — putar dalam 3D di ruang Koleksi"]},{"h":"Cara kerja papan","p":["Dua puluh petak terdiri dari blok dua belas (3×4) dan blok enam (3×2) yang dihubungkan “jembatan” sempit dua petak. Lima petak berhias roset; dalam aturan rekonstruksi, mendarat di sana memberi lemparan tambahan dan bidak tak bisa dimakan.","Dadunya tetrahedron dengan dua dari empat ujungnya bertanda. Empat dadu dilempar dan bidak maju sebanyak ujung bertanda yang menghadap ke atas: 0 sampai 4. Yang paling sering 2 (6 dari 16); 0 dan 4 hanya 1 dari 16. Kamu bisa melemparnya di ruang “Peluang” museum."],"cap":["Dua puluh petak dan lima roset. Angka hijau adalah jalur satu pemain, petak demi petak (aturan rekonstruksi)","Cara jatuhnya empat dadu tetrahedron (dari 16 kemungkinan yang sama besar)"]},{"h":"Isi lempeng tanah liat","p":["Sisi depan menjelaskan permainan; sisi belakang menggambar papan dengan tanda zodiak di petak-petaknya. Kalimat untuk tiap petak terdengar seperti ramalan — “kau akan bertemu teman”, “kau akan minum bir yang enak” — jadi permainan ini terkait dengan peruntungan.","Tetapi sebagian lempeng pecah, sehingga tak semua aturan terbaca. Rekonstruksi Finkel menyusun permainan paling masuk akal dari baris yang terbaca dan bentuk papan; peneliti lain mengajukan versi berbeda."]},{"h":"Pemain terakhir di India","p":["Kemudian Finkel mengetahui bahwa komunitas Yahudi di Kochi (Cochin), India selatan, memainkan permainan dua puluh petak hingga belum lama ini, dengan papan yang bentuknya sangat mirip.","Permainan itu diwariskan di rumah-rumah sampai mereka pindah ke Israel pada 1950-an. Mungkin ia tiba di India lewat jalur dagang kuno dan bertahan lebih dari empat ribu tahun."]}],"tl":[["sekitar 2600–2400 SM","Papan dua puluh petak diletakkan di makam kerajaan Ur"],["Abad ke-8 SM","Papan digores di alas patung penjaga gerbang istana Asyur"],["177/176 SM","Juru tulis Babilonia menyalin lempeng aturan"],["1922–1934","Woolley menggali Ur dan menemukan papan-papan itu"],["Awal 1980-an","Finkel membaca lempeng dan menyusun ulang aturannya"],["Hingga 1950-an","Permainan yang sangat mirip dimainkan di Kochi, India selatan"]]},"liubo":{"title":"Mengapa liubo menghilang?","lead":"Pada masa Han, semua orang dari kaisar hingga rakyat memainkannya. Dalam beberapa abad, aturannya pun terlupakan.","s":["Liubo adalah kegemaran besar Tiongkok masa Han (206 SM – 220 M). Ia muncul pada patung makam, relief batu, bahkan hiasan cermin, dan para dewa abadi sering digambarkan sedang memainkannya.","Setelah Han runtuh, liubo cepat merosot, dan tampaknya pada masa Tang aturannya sudah hilang. Penyebabnya belum jelas; salah satu pendapat menyebut para pemain beralih ke permainan lain seperti weiqi (go).","Yang tersisa adalah papan dan perlengkapannya. Papan liubo memiliki pola khas berbentuk T, L, dan V, dan langkah kemungkinan ditentukan dengan melempar batang tipis. Pola yang sama menghiasi cermin yang disebut cermin TLV.","Petunjuk tertulis juga perlahan terkumpul. Pada 1993, sebuah makam Han di Yinwan, Jiangsu, menghasilkan teks ramalan yang memakai diagram papan. Makam Liu He, Marquis Haihun, yang digali pada 2010-an, menghasilkan lebih dari seribu bilah bambu tentang liubo yang masih diteliti.","Liubo di Atlas adalah rekonstruksi berdasarkan petunjuk-petunjuk itu. Para ahli merekonstruksinya dengan cara yang agak berbeda, dan aturan sebenarnya belum sepenuhnya diketahui — temuan baru bisa saja mengubah cara memainkannya."],"quiz":[["Pada dinasti apa liubo sangat populer?","Han","Ming","Qing","Song"],["Di mana lebih dari seribu bilah bambu tentang liubo ditemukan?","Di makam Liu He, Marquis Haihun","Di mausoleum Kaisar Pertama","Di gua-gua Dunhuang","Di Kota Terlarang"],["Apa yang kemungkinan dilempar untuk menentukan langkah dalam liubo?","Batang tipis","Dadu dua puluh sisi","Gasing","Kartu bergambar"]],"kf":["Sangat populer di Tiongkok dari Zaman Negara Berperang hingga Han (abad ke-5 SM – abad ke-3 M)","Papan bergaris berbentuk T, L, dan V; batang tipis dilempar untuk melangkah","Cepat memudar setelah Han runtuh, dan aturannya masih belum sepenuhnya diketahui"],"more":[{"h":"Papan TLV","p":["Papan liubo berbentuk persegi, dengan persegi di tengah, T di tengah tiap sisi, bentuk L di sekitarnya, dan V di sudut-sudut. Bidak diduga bergerak di atas dan di antara garis-garis ini.","Garis yang sama muncul di balik cermin (“cermin TLV”) dan pada jam matahari. Sebagian peneliti membaca papan ini sebagai peta kosmos — langit, bumi, dan empat arah — tanda bahwa liubo lebih dari sekadar hiburan."],"cap":["Garis-garis papan liubo (pola TLV): persegi di tengah, T di tiap sisi, bentuk L dan V ke arah sudut"]},{"h":"Cara memainkannya","p":["Kebanyakan peneliti menduga tiap pemain punya enam bidak dan melempar batang bambu tipis untuk menentukan langkah. “Enam” (liu) dalam namanya konon berasal dari enam batang atau enam bidak itu.","Bidak yang maju tampaknya menjadi “burung hantu” (xiao) yang kuat. Puisi sekitar abad ke-3 SM, “Memanggil Jiwa” dalam Nyanyian Chu, berbunyi: “menjadi burung hantu, mendesak dan berseru ‘lima putih!’”. Teks juga menyebut cara bermain dengan menangkap “ikan” di “air” di tengah papan."],"cap":["Dua figur pemain liubo yang dibuat untuk makam Han (Metropolitan Museum of Art)"]},{"h":"Perangkat dari makam","p":["Makam 3 Mawangdui di Changsha, Hunan (sekitar 168 SM), berisi satu set lengkap — papan, bidak, dan batang — dalam kotak berpernis, agar yang meninggal bisa bermain di alam baka.","Relief dinding makam sering menggambarkan para dewa abadi bermain liubo di puncak gunung. Permainan ini terkait dengan dunia keabadian dan umur panjang."],"cap":["Papan liubo milik museum — lihat dalam 3D di ruang Koleksi"]}],"tl":[["Abad ke-5–3 SM (Negara Berperang)","Papan liubo mulai diletakkan di makam"],["sekitar abad ke-3 SM","“Memanggil Jiwa” menggambarkan permainan liubo"],["sekitar 168 SM","Satu set lengkap masuk ke makam 3 Mawangdui"],["206 SM – 220 M (Han)","Dimainkan dari kaisar hingga rakyat; muncul di relief dan cermin"],["Tang (abad ke-7–10)","Aturannya diduga sudah terlupakan"],["1993","Teks ramalan dengan papan muncul dari makam Han Yinwan"],["2010-an","Bilah bambu tentang liubo ditemukan di makam Marquis Haihun, Liu He"]]},"zeno":{"title":"Lemparan sial Kaisar Zeno","lead":"Seribu lima ratus tahun lalu seorang kaisar melempar dadu — dan hasilnya bertahan dalam sebuah puisi.","s":["Orang Romawi menyukai tabula, permainan balapan dengan dadu di papan 24 titik — leluhur backgammon. Untuk mencegah lemparan curang, mereka bahkan memakai menara dadu, tempat dadu bergulir jatuh di dalamnya.","Sekitar tahun 480, Kaisar Romawi Timur Zeno sedang bermain tabula. Ketiga dadunya menunjukkan 2, 5, dan 6. Ia terpaksa melangkah sesuai aturan, dan di papannya tersisa delapan bidak yang berdiri sendiri tanpa perlindungan.","Permainan itu dicatat oleh Agathias, sejarawan dan penyair abad ke-6 yang hidup beberapa dekade setelah Zeno. Puisi pendeknya (sebuah epigram) bahkan menyebut posisi bidak-bidak — catatan langka tentang sebuah permainan kuno.","Pada abad ke-19, sarjana Prancis Becq de Fouquières menguraikan posisi dan aturannya dari puisi itu: lima belas bidak per pemain dan tiga dadu. Semua bidak mulai dari luar papan, dan kedua pemain bergerak ke arah yang sama.","Dibanding backgammon sekarang, tabula memakai tiga dadu, dimulai tanpa bidak di papan, dan tidak punya kubus penggandaan. Berkat kesialan seorang kaisar, kita tahu seperti apa tabula."],"quiz":[["Berapa angka dadu Zeno?","2, 5, dan 6","6, 6, dan 6","1, 1, dan 1","3, 4, dan 5"],["Siapa yang mencatat permainan itu dalam puisi?","Agathias","Homeros","Plinius","Cicero"],["Mana perbedaan tabula dengan backgammon sekarang?","Tabula memakai tiga dadu","Tiga puluh bidak per pemain","Papan 12 titik","Bidak bergerak mundur"]],"kf":["Tabula dimainkan dengan 24 titik dan tiga dadu — leluhur backgammon","Permainan Kaisar Zeno sekitar tahun 480 bertahan, lengkap dengan posisinya, dalam sebuah puisi","Orang Romawi bahkan membuat “menara dadu” untuk mencegah kecurangan"],"more":[{"h":"Papan tabula","p":["Papan tabula, seperti papan backgammon kini, punya 24 titik dalam dua baris berisi 12. Tiap pemain punya lima belas bidak yang semuanya di luar papan pada awalnya; menurut tiga dadu, bidak dimasukkan, berkeliling, lalu dikeluarkan.","Perbedaan besar dengan backgammon: kedua pemain bergerak ke arah yang sama. Bidak yang berdiri sendiri bisa dipukul bila lawan mendarat di titiknya, dan harus masuk lagi. Delapan bidak Zeno adalah bidak rawan semacam itu."],"cap":["Papan tabula: 24 titik dalam dua baris berisi 12; bidak kedua pemain bergerak ke arah yang sama (panah)"]},{"h":"Alat anti-kecurangan","p":["Orang Romawi tergila-gila pada dadu. Judi dilarang hukum dan konon hanya dibolehkan selama festival musim dingin Saturnalia — tetapi taruhan tak pernah berhenti, begitu pula kecurangan dengan tangan.","Maka dibuatlah menara dadu: dadu yang dimasukkan dari atas memantul pada papan-papan di dalam dan keluar menggelinding di bawah. Menara abad ke-4 dari sebuah vila di Jerman berukiran tembus: “Bangsa Pikt kalah, musuh hancur — bermainlah dengan tenang”."],"cap":["Menara dadu Vettweiß-Froitzheim (abad ke-4) — lihat dalam 3D di ruang Koleksi"]},{"h":"Kaisar dan dadu","p":["Bukan hanya Zeno. Menurut sejarawan Suetonius, Kaisar Claudius pada abad ke-1 begitu menyukai dadu sampai menulis buku tentang seninya dan mengatur keretanya agar papan tidak bergeser saat ia bermain.","Situs-situs Romawi juga menghasilkan banyak papan berisi 36 huruf dalam kata-kata enam huruf; tiap huruf berfungsi sebagai petak, dan sebagian memuat ejekan seperti “Bangun, kau tak bisa main; beri tempat untuk pemain”."],"cap":["Tables dan dadu disukai dari kaisar hingga prajurit (lempar dadu kubus di ruang Peluang)"]}],"tl":[["Abad ke-1","Kaisar Claudius menulis buku tentang permainan dadu"],["Abad ke-4","Menara dadu dipakai di sebuah vila di Jerman"],["sekitar 480","Permainan sial Kaisar Zeno"],["Abad ke-6","Agathias menuangkan permainan itu ke dalam puisi"],["sekitar abad ke-10","Puisi itu masuk ke Antologi Yunani"],["1869","Becq de Fouquières menguraikan posisi dan aturannya"],["1934","R. G. Austin menelaah ulang permainan Zeno secara rinci"]]},"sugoroku":{"title":"Sugoroku yang dilarang","lead":"Penguasa melarangnya, rakyat tetap bermain. Kisah sugoroku papan di Jepang, dari zaman kuno hingga periode Edo.","s":["Gudang harta Shōsōin menyimpan papan sugoroku yang menurut tradisi adalah kesayangan Kaisar Shōmu. Ini bukan sugoroku kertas bergambar, melainkan ban-sugoroku, yang dimainkan dengan menggerakkan bidak putih dan hitam di papan — kerabat backgammon.","Sugoroku sejak awal berkaitan dengan judi. Menurut Nihon Shoki, Maharani Jitō melarangnya pada 689.","Kode Yōrō, yang berlaku sejak 757, juga melarang biksu dan biksuni bermain sugoroku. Larangan dikeluarkan berulang kali — tanda bahwa larangan itu tidak dipatuhi.","Pada periode Heian, sugoroku tetap populer dan muncul dalam Buku Bantal serta Hikayat Genji. Hikayat Heike menceritakan bahwa Kaisar purnatahta Shirakawa menyebut tiga hal yang tak dapat ia kendalikan: air Sungai Kamo, dadu sugoroku, dan biksu-prajurit Gunung Hiei.","Cetakan kayu periode Edo masih memperlihatkan gadis-gadis bermain ban-sugoroku di dalam rumah. Namun menjelang era Meiji, permainan papan itu hampir lenyap, dan \"sugoroku\" kemudian berarti permainan kertas bergambar."],"quiz":[["Ban-sugoroku, seperti papan Shōsōin, berkerabat dengan permainan apa?","Backgammon","Shogi","Go","Kartu remi"],["Menurut Nihon Shoki, siapa yang melarang sugoroku pada 689?","Maharani Jitō","Kaisar Shōmu","Kaisar Kanmu","Kaisar Meiji"],["Shirakawa tak dapat mengendalikan Sungai Kamo, para biksu-prajurit, dan… apa lagi?","Dadu sugoroku","Bidak shogi","Batu go","Bola kemari"]],"kf":["Ban-sugoroku kerabat backgammon dan sudah dimainkan di Jepang pada abad ke-7","Berulang kali dilarang karena judi, pertama oleh Maharani Jitō tahun 689","Pada era Meiji hampir terlupakan, dan “sugoroku” beralih menjadi nama permainan gambar di kertas"],"more":[{"h":"Papan Shōsōin","p":["Papan di Shōsōin terbuat dari kayu sonokeling dengan tatahan halus gading dan kayu berwarna. Ada 24 petak, dua belas di tiap sisi, dengan hiasan bunga di sekat tengah.","Shōsōin juga menyimpan banyak bidak sugoroku dari kaca dan batu. Ban-sugoroku memakai lima belas bidak putih dan lima belas hitam serta dua dadu — hampir sama dengan backgammon. Diduga berasal dari nard Persia lewat Tiongkok."],"cap":["Papan sugoroku Shōsōin dari kayu sonokeling bertatah — mainkan di ruang Koleksi"]},{"h":"Cara bermain","p":["Tiap pemain menata lima belas bidak menurut pola tetap dan maju sesuai dua dadu. Putih dan hitam berputar berlawanan arah; yang lebih dulu mengumpulkan semua bidak di enam petak terakhir menang.","Bidak yang sendirian bisa dipukul dan dikembalikan ke awal. Petak berisi dua bidak atau lebih tak bisa dimasuki lawan, jadi seninya adalah membangun blokade. Di ruang Koleksi kamu bisa bermain begini di papan Shōsōin."],"cap":["Papan ban-sugoroku (bagan): 24 petak, putih dan hitam bergerak berlawanan arah"]},{"h":"Larangan dan tren","p":["Setelah Jitō, sugoroku dilarang lagi berkali-kali, karena selalu ada orang yang kehilangan harta akibat judi. Keshogunan Kamakura juga mengeluarkan aturan melarang taruhan sugoroku.","Namun sugoroku juga keterampilan kaum bangsawan. Papan indah menjadi bagian barang bawaan pengantin, dan pada zaman Edo dibuat papan bernis mewah. Dibenci sebagai alat judi, dicintai sebagai harta — ban-sugoroku punya dua wajah."],"cap":["Ban-sugoroku dalam lukisan zaman Edo (ruang Permainan dalam Lukisan)"]}],"tl":[["Abad ke-7","Ban-sugoroku datang dari Tiongkok"],["689","Maharani Jitō melarang sugoroku (Nihon shoki)"],["Abad ke-8","Papan bertatah masuk ke Shōsōin"],["757","Kitab hukum Yōrō melarangnya bagi biksu dan biksuni"],["Zaman Heian","Muncul dalam Buku Bantal dan Hikayat Genji"],["Abad ke-12","Keluhan Shirakawa soal “dadu sugoroku” (Hikayat Heike)"],["Zaman Edo","Papan mewah dibuat untuk barang bawaan pengantin"],["Era Meiji","Ban-sugoroku hampir tak dimainkan lagi"]]},"queen":{"title":"Bagaimana menteri catur menjadi bidak terkuat","lead":"Bidak terkuat masa kini dulunya seorang penasihat yang hanya bisa melangkah satu petak diagonal.","s":["Catur menyebar dari India ke Persia dan dunia Arab. Dalam epos Persia Shahnameh, sang bijak Buzurgmihr memecahkan teka-teki catur yang dikirim dari India. Di papan masa itu, bidak di samping raja adalah fers, sang penasihat.","Fers hanya bisa melangkah satu petak diagonal — bidak yang sangat lemah. Dalam set catur abad ke-12 dari Nishapur, Iran, bentuknya singgasana kecil, lebih kecil dari milik raja.","Saat catur sampai di Eropa, penasihat berubah menjadi ratu; bidak catur Lewis abad ke-12 pun memiliki ratu. Tetapi nama baru tidak mengubah langkahnya: ia tetap lemah.","Perubahan besar terjadi di Spanyol pada akhir abad ke-15. Scachs d’amor (\"Catur cinta\"), puisi yang ditulis di Valencia sekitar 1475, dianggap catatan tertua tentang menteri modern yang bergerak sejauh apa pun di baris, kolom, dan diagonal. Buku Lucena (1497) dan Damiano (1512) lalu menyebarkan aturan baru itu ke seluruh Eropa.","Mengapa menteri menjadi begitu kuat belum pasti. Ada yang menyebut orang ingin permainan lebih cepat; ada pula yang menunjuk pengaruh ratu-ratu berkuasa seperti Isabella I. Bagaimanapun, perubahan ini membawa catur sangat dekat dengan permainan masa kini."],"quiz":[["Dalam catur Persia dan Arab, bidak apa yang menempati posisi menteri sekarang?","Fers (penasihat)","Gajah","Kereta perang","Kuda"],["Bagaimana langkah fers yang asli?","Satu petak diagonal","Sejauh apa pun lurus","Melompat dua petak","Tidak bisa bergerak"],["Di mana puisi dengan catatan tertua tentang menteri modern ditulis?","Valencia, abad ke-15","India, abad ke-6","Lewis, abad ke-12","London, abad ke-19"]],"kf":["Ratu bermula dari “fers” Persia dan Arab (penasihat), yang hanya bisa melangkah satu petak diagonal","Ratu kuat modern pertama kali tercatat di Spanyol sekitar 1475","Buku cetak menyebarkan aturan baru ke seluruh Eropa dalam beberapa dasawarsa"],"more":[{"h":"Penasihat yang lemah","p":["Fers hanya bisa melangkah satu petak diagonal — jauh berbeda dari ratu masa kini yang melesat dari ujung ke ujung papan. Catur saat itu lambat, dan satu permainan bisa berlangsung berjam-jam.","Gajah (benteng miring masa kini) hanya melompat dua petak diagonal. Pion yang mencapai baris terakhir memang dipromosikan — tetapi hanya menjadi fers yang lemah ini."],"cap":["Jangkauan fers (kiri) dan ratu modern (kanan)"]},{"h":"“Catur ratu” dan “catur gila”","p":["Setelah ratu baru muncul, orang Spanyol menyebut permainan ini “catur ratu”, dan orang Italia, karena keganasannya, “catur gila” (scacchi alla rabbiosa). Sekitar waktu yang sama, gajah juga boleh meluncur diagonal sejauh apa pun.","Dengan bidak yang lebih kuat, permainan menjadi cepat dan sengit. Muncul buku tentang jebakan yang menang dalam beberapa langkah dan urutan pembukaan yang baku; catur menjadi permainan yang dipelajari."],"cap":["Liberale da Verona, Para Pemain Catur (sekitar 1475) — dilukis tepat saat ratu baru lahir"]},{"h":"Mengapa ratu?","p":["Mengapa penasihat berubah menjadi ratu tidak pasti. Melihat bidak di samping raja sebagai permaisurinya mungkin terasa wajar. Dalam bahasa Latin, “fers” menjadi “fercia”, lalu bidak itu disebut “regina”, ratu.","Alasan ia menjadi kuat juga diperdebatkan: untuk mempercepat permainan, atau karena saat itu zaman ratu-ratu berkuasa seperti Isabel I dari Kastilia. Sejarawan Marilyn Yalom mengaitkan perubahan ini dengan kedudukan perempuan di Abad Pertengahan."],"cap":["Ratu dari bidak catur Lewis (abad ke-12) — masih dengan langkah lama yang lemah"]}],"tl":[["sekitar abad ke-6","Chaturanga, leluhur catur, lahir di India"],["abad ke-7–9","Dimainkan di Persia dan dunia Arab, dengan fers di samping raja"],["sekitar abad ke-10","Catur sampai di Eropa"],["abad ke-12","Bidak catur Lewis memuat ratu (masih lemah)"],["sekitar 1475","Puisi Valencia Scachs d’amor mencatat langkah baru"],["1497","Buku catur Lucena dicetak di Spanyol"],["1512","Buku Damiano terbit di Italia dan aturan baru menyebar"]]},"senet":{"title":"Bagaimana senet menjadi perjalanan ke alam baka","lead":"Permainan yang dimainkan di Mesir hampir tiga ribu tahun akhirnya melambangkan perjalanan jiwa setelah kematian.","s":["Senet adalah permainan Mesir kuno: bidak bergerak di papan tiga baris berisi sepuluh petak. Di makam Dinasti I sekitar 3100 SM ditemukan pecahan yang mungkin papan senet. Para raja bermain di kotak yang mewah, rakyat biasa di papan yang digores pada batu.","Namanya berarti “melintas”. Sejak masa Kerajaan Baru (sekitar 1550 SM), senet dikaitkan dengan perjalanan jiwa orang yang meninggal melintasi alam baka.","Bab 17 Kitab Orang Mati menggambarkan orang yang meninggal bermain senet melawan lawan yang tak terlihat. Di dinding makam Nefertari, permaisuri Ramses II, sang ratu duduk menghadap papan senet.","Makam Tutankhamun berisi sedikitnya lima kotak permainan. Salah satunya, kotak besar dari eboni dan gading, memuat senet di bagian atas dan permainan dua puluh petak di sisi lain.","Namun belum ditemukan teks yang menjelaskan aturannya secara lengkap. Pada abad ke-20, Jéquier, Bell, dan Kendall (1978), antara lain, masing-masing merekonstruksi cara bermain dari papan, gambar, dan potongan teks. Senet di Atlas adalah salah satu cara bermain berbasis penelitian itu."],"quiz":[["Apa arti nama “senet”?","Melintas","Permainan raja","Tiga puluh rumah","Menyeberangi sungai"],["Pada masa Kerajaan Baru, senet dikaitkan dengan apa?","Perjalanan jiwa melintasi alam baka","Ritual meminta hujan","Rencana perang","Ramalan panen"],["Berapa sedikitnya kotak permainan di makam Tutankhamun?","Lima","Satu","Dua","Seratus"]],"kf":["Salah satu permainan papan tertua: bidak berpacu di papan 3 × 10 petak","Namanya berarti “melintas”; di Kerajaan Baru ia menjadi perjalanan jiwa melewati alam baka","Aturannya tak tersisa; cara main kini adalah rekonstruksi abad ke-20"],"more":[{"h":"Tiga puluh petak dan petak khusus","p":["Papan senet punya tiga baris berisi sepuluh, tiga puluh petak. Bidak diduga bergerak dari kiri ke kanan di baris pertama, kanan ke kiri di baris kedua, lalu kiri ke kanan lagi di baris ketiga, membentuk huruf S.","Lima petak terakhir sering diberi tanda khusus. Petak 26 adalah “rumah indah”, 27 “air”, dan dalam kebanyakan rekonstruksi bidak yang jatuh ke air harus mundur. Petak 28–30 memuat angka atau dewa-dewa alam baka."],"cap":["Papan senet. Bidak bergerak membentuk S; lima petak terakhir (26–30) bertanda khusus"]},{"h":"Melangkah dengan tongkat lempar","p":["Sebagai ganti dadu, dilempar empat tongkat yang datar di satu sisi dan bulat di sisi lain, atau tulang tumit hewan. Banyak peneliti menduga langkahnya sesuai jumlah sisi datar yang menghadap ke atas, dan nol dihitung lima.","Hitungan ini persis sama dengan tongkat yut dari Korea yang jauh. Lempar tongkatnya di ruang Peluang museum dan lihat betapa angka tertentu lebih sering muncul."],"cap":["Tongkat lempar Mesir (lempar di ruang Peluang)"]},{"h":"Kotak permainan Tutankhamun","p":["Makam Tutankhamun yang dibuka Howard Carter pada 1922 berisi sedikitnya lima kotak permainan. Yang terbesar dari kayu eboni dan gading, dengan laci untuk bidak dan tongkat.","Kotak dengan papan di kedua sisi lazim saat itu: senet di satu sisi, dan di sisi lain permainan dua puluh petak yang sama dengan Permainan Kerajaan Ur. Sang raja diharapkan bisa memainkan keduanya di alam baka."],"cap":["Kotak senet Tutankhamun — lihat dalam 3D dan mainkan di ruang Koleksi"]}],"tl":[["sekitar 3100 SM","Pecahan papan mirip senet di makam Dinasti I"],["sekitar 2600 SM","Lukisan makam Kerajaan Lama menampilkan para pemain"],["sejak sekitar 1550 SM","Kerajaan Baru: senet dikaitkan dengan perjalanan ke alam baka"],["sekitar 1323 SM","Lima kotak permainan masuk makam Tutankhamun"],["sekitar 1250 SM","Nefertari dilukis di depan papan senet"],["1922","Carter membuka makam Tutankhamun"],["1978","Kendall menerbitkan rekonstruksi aturan"]]},"lewis":{"title":"Bidak catur yang muncul dari pasir","lead":"Bidak abad pertengahan yang ditemukan di sebuah pulau Skotlandia pada 1831 — dan satu lagi dari bengkel yang sama, yang muncul di laci 188 tahun kemudian.","s":["Pada 1831, di Pulau Lewis di barat laut Skotlandia, ditemukan sekumpulan bidak yang sebagian besar diukir dari gading walrus: 78 bidak catur, 14 keping permainan papan, dan sebuah gesper — 93 benda semuanya.","Tempat dan cara penemuannya tidak jelas. Teluk Uig di pantai barat paling sering disebut, tetapi ada dugaan lain. Siapa yang menguburnya di sana, dan mengapa, tidak diketahui.","Bidak-bidak ini diduga dibuat pada akhir abad ke-12 di sekitar Trondheim, Norwegia: raja, ratu yang termenung, uskup, ksatria di atas kuda kecil yang gempal, dan penjaga yang menggigit tepi perisainya — mungkin para berserker dalam saga Nordik.","Kini 82 bidak ada di British Museum dan 11 di Museum Nasional Skotlandia. Sejak lama dikatakan bahwa beberapa bidak kurang untuk melengkapi set-setnya.","Pada 2019, seorang penjaga yang dibeli seorang pedagang barang antik Edinburgh hanya seharga 5 pound pada 1964, dan disimpan keluarganya di laci, dikenali sebagai buatan bengkel bidak Lewis. Bidak itu terjual di Sotheby’s seharga 735.000 pound."],"quiz":[["Pada tahun berapa bidak-bidak ditemukan di Lewis?","1831","1066","1931","1700"],["Terutama dari apa bidak-bidak itu dibuat?","Gading walrus","Marmer","Emas","Kaca"],["Tahun berapa penjaga yang terjual pada 2019 dibeli seharga 5 pound?","1964","1831","1990","2018"]],"kf":["93 bidak dan cakram yang ditemukan di Pulau Lewis, Skotlandia, pada 1831","Diukir sebagian besar dari gading walrus di Norwegia akhir abad ke-12","Kini terbagi antara British Museum dan National Museums Scotland"],"more":[{"h":"78 bidak catur","p":["78 bidak itu terdiri dari 8 raja, 8 ratu, 16 uskup, 15 kesatria, 12 penjaga, dan 19 pion — bagian dari sedikitnya empat set.","Para uskup memakai mitra. Perubahan “gajah” catur menjadi uskup terjadi di Eropa, dan bidak Lewis termasuk contoh paling awal. Beberapa penjaga menggigit perisainya; mereka diduga menggambarkan berserker, prajurit yang bertarung dalam amukan."],"cap":["Bidak catur Lewis (lihat dalam 3D di ruang Koleksi)","78 bidak catur menurut jenisnya"]},{"h":"Gading walrus dan laut utara","p":["Sebagian besar dari gading walrus, beberapa dari gigi paus. Gading walrus adalah harta laut utara yang didatangkan dari Greenland dan Norwegia utara.","Saat itu Lewis termasuk pulau-pulau milik raja Norwegia; lewat Perjanjian Perth tahun 1266 pulau itu berpindah ke Skotlandia. Di dekat Katedral Trondheim ditemukan pecahan berukiran serupa — petunjuk tempat pembuatannya."],"cap":[]},{"h":"Legenda penemuan dan ketenaran kini","p":["Ada banyak cerita: seekor sapi yang menggalinya dari pasir, atau warga setempat bernama Malcolm MacLeod. Penemunya segera menjualnya, dan lewat Edinburgh sebagian besar dibeli British Museum.","Dengan wajah cemberut nan lucu, bidak ini sangat populer dan replikanya dijual di seluruh dunia. Catur sihir dalam film Harry Potter dan Batu Bertuah (2001) memakai bidak yang meniru bidak Lewis."],"cap":[]}],"tl":[["akhir abad ke-12","Bidak dibuat di Norwegia (sekitar Trondheim)"],["1266","Perjanjian Perth menyerahkan pulau-pulau, termasuk Lewis, kepada Skotlandia"],["1831","93 benda ditemukan bersama di Lewis"],["1831–32","British Museum membeli 82"],["1888","Museum nasional Skotlandia memperoleh 11"],["2001","Muncul dalam catur sihir Harry Potter"],["2019","Penjaga yang dibeli seharga £5 terjual £735.000"]]},"tafl":{"title":"Pelarian sang raja dan terjemahan yang keliru","lead":"Aturan permainan papan bangsa Viking diuraikan dari catatan perjalanan di Lapland pada abad ke-18.","s":["Di Eropa utara pada zaman Viking dimainkan permainan papan yang disebut tafl. Seorang raja di tengah dan sedikit pembelanya melawan pasukan lebih besar yang mengepung mereka — permainan dua pihak yang tidak seimbang.","Papan kayu abad ke-10 yang ditemukan di Ballinderry, Irlandia, pada 1932 memiliki 7×7 lubang; bagian tengah dan keempat sudutnya ditandai — mungkin tempat raja dan tempat ia berlindung.","Namun hampir tak ada catatan abad pertengahan tentang aturannya. Petunjuk penting adalah buku harian naturalis Linnaeus, yang berusia 25 tahun, dari perjalanannya di Lapland (Swedia utara) pada 1732. Di sana ia mencatat cara orang Sami memainkan permainan bernama tablut.","Buku harian itu terbit dalam terjemahan Inggris pada 1811, tetapi terjemahannya mengandung kesalahan. Rekonstruksi Murray (1913) yang berdasarkan terjemahan itu menjadi aturan baku tafl selama bertahun-tahun.","Para pemain dan peneliti kemudian membetulkan kesalahan itu, dan kini dimainkan banyak versi aturan. Tafl di Atlas adalah salah satunya."],"quiz":[["Permainan apa yang dicatat Linnaeus di Lapland?","Tablut","Senet","Congklak","Catur"],["Bidak apa yang ingin dibawa para pembela ke sudut?","Raja","Ratu","Bendera","Kapal"],["Kapan terjemahan Inggris yang keliru itu terbit?","1811","1732","1932","1066"]],"kf":["Seorang raja dan sedikit pembela di tengah, dikepung pasukan yang lebih besar — permainan dua pihak yang tidak seimbang","Dimainkan di Eropa Utara pada zaman Viking, di papan berukuran 7×7 hingga 19×19","Aturannya sampai kepada kita lewat catatan perjalanan Linnaeus tahun 1732 — dan terjemahan Inggrisnya yang keliru"],"more":[{"h":"Papan Ballinderry","p":["Ditemukan di permukiman danau (crannog) di Irlandia tengah, papan Ballinderry terbuat dari kayu yew. Ke-49 lubangnya, dalam kisi 7×7, mungkin dipakai untuk menancapkan bidak berpasak di bagian bawahnya.","Dari bingkainya menonjol pegangan berukir kepala manusia: papan ini bisa dibawa ke mana-mana. Sumber Irlandia menyebut tafl 7×7 bernama brandubh (“gagak hitam”), yang mungkin dimainkan di papan ini."],"cap":["Papan Ballinderry (7×7) dengan susunan awal brandubh dari Irlandia. Cincin emas menandai bagian tengah dan keempat sudut"]},{"h":"Tablut catatan Linnaeus","p":["Tablut yang dicatat Linnaeus memakai papan 9×9. Raja berdiri di takhta tengah; 8 “orang Swedia”-nya melawan 16 “orang Moskow”.","Semua bidak bergerak lurus sejauh berapa petak pun, seperti benteng, dan ditangkap bila terjepit di antara dua musuh. Pembela menang bila raja mencapai tepi papan; penyerang menang bila mengepungnya dari empat sisi. Linnaeus menulis dengan campuran bahasa Latin dan Swedia, dan beberapa hal berubah dalam terjemahan Inggris."],"cap":["Tablut seperti dicatat Linnaeus (9×9): raja di takhta tengah, 8 pembela, 16 penyerang. Pembela menang bila raja mencapai petak hijau di tepi"]},{"h":"Papan yang membesar, permainan yang memudar","p":["Selain 7×7, ada papan 9×9, 11×11 dari Wales, bahkan 19×19. Yang terbesar, Alea Evangelii, digambar dalam naskah abad ke-12 yang menyebut permainan itu berasal dari istana Raja Æthelstan dari Inggris pada abad ke-10.","Ketika catur menyebar di Eropa Utara pada abad ke-12 dan ke-13, tafl perlahan ditinggalkan. Hanya di Lapland yang jauh tablut bertahan — dan Linnaeus kebetulan mencatatnya. Kini ada turnamen internasional di papan 11×11, dan permainan ini mendapat pemain baru."],"cap":["Temuan Lewis (abad ke-12): bersama bidak catur ditemukan 14 cakram untuk permainan papan"]}],"tl":[["Abad ke-10","Papan Ballinderry dibuat di Irlandia"],["924–939","Alea Evangelii konon dimainkan di istana Æthelstan"],["Abad ke-12","Alea Evangelii digambar dalam naskah"],["Abad ke-12–13","Catur menyebar di Eropa Utara, tafl menghilang"],["1732","Linnaeus mencatat tablut di Lapland"],["1811","Terbit Lachesis Lapponica, terjemahan Inggris catatannya"],["1913","Murray merekonstruksi tafl dalam A History of Chess"],["1932","Papan Ballinderry ditemukan"]]},"goose":{"title":"Permainan angsa, hadiah untuk seorang raja","lead":"Balapan dadu di spiral 63 petak dihadiahkan kepada seorang raja — lalu dimainkan di seluruh Eropa.","s":["Permainan angsa adalah permainan balapan: lempar dadu dan maju di spiral 63 petak menuju tujuan di tengah. Jika berhenti di petak angsa, kamu maju lagi sebanyak angka yang sama. Sumur, penjara, dan maut menahanmu atau mengirimmu kembali ke awal.","Permainan ini diduga lahir di Italia abad ke-16. Konon Francesco I de’ Medici, Adipati Agung Toscana, menghadiahkannya kepada Raja Felipe II dari Spanyol antara 1574 dan 1587.","Di Inggris, pencetak London John Wolfe mendaftarkan “permainan angsa yang baru dan sangat menyenangkan” pada 1597. Pada abad ke-17 dan ke-18 permainan ini sangat populer di seluruh Eropa.","Dicetak di kertas, permainan ini menyebar dalam versi yang tak terhitung dengan gambar baru: papan untuk belajar geografi, papan cerita dan fabel, bahkan papan iklan. Permainan ini diduga menjadi model bagi banyak permainan balapan sesudahnya.","Sebuah papan dua sisi di Metropolitan Museum of Art memuat permainan angsa di satu sisi dan catur di sisi lain. Diduga dibuat pada akhir abad ke-16 oleh perajin Gujarat, India, papan ini mungkin papan permainan angsa tertua yang masih ada."],"quiz":[["Berapa petak dalam permainan angsa?","63","64","100","30"],["Siapa yang konon menghadiahkan permainan ini kepada Raja Spanyol?","Francesco I de’ Medici","Napoleon","Elizabeth I","Louis XIV"],["Apa yang terjadi jika berhenti di petak angsa?","Maju lagi sebanyak angka yang sama","Kembali ke awal","Tidak jalan satu giliran","Bertukar tempat dengan lawan"]],"kf":["Lomba menyusuri spiral 63 petak menuju garis akhir di tengah, menurut lemparan dadu","Lahir di Italia abad ke-16 dan, konon, dihadiahkan keluarga Medici kepada Raja Spanyol","Menyebar lewat lembaran cetak, dalam versi tak terhitung dengan gambar dan tema baru"],"more":[{"h":"Spiral 63 petak","p":["Dalam versi paling terkenal, selain angsa ada beberapa petak khusus. Jembatan di 6 membawa ke 12; di penginapan 19 kamu kehilangan satu giliran; di sumur 31 dan penjara 52 kamu terjebak sampai pemain lain datang membebaskan.","Labirin di 42 mengembalikan ke 30, dan maut di 58 mengembalikan ke awal. Petak 63 harus dicapai dengan lemparan pas; kelebihannya dihitung mundur. Langkah terakhir adalah yang tersulit."],"cap":["Ke-63 petak disusun spiral dari luar ke dalam. Hijau: angsa; biru: jembatan; kuning: tertahan (penginapan, sumur, penjara); merah: mundur (labirin, maut); emas: garis akhir"]},{"h":"Teka-teki angka sembilan","p":["Angsa berada di 5, 9, 14, 18…, dengan jarak 4 dan 5 bergantian. Setiap kelipatan 9 berisi angsa, sehingga angka 9 yang mendarat di 9 akan membawamu ke 18, 27… dan langsung ke 63.","Karena itu versi dengan dua dadu punya aturan khusus: lemparan pertama 6 dan 3 menuju 26, sedangkan 5 dan 4 menuju 53. Angka 63 adalah 7×9 dan dikaitkan dengan usia 63 tahun, yang waktu itu dianggap tahun paling berbahaya dalam hidup."],"cap":["Angsa berselang 4 dan 5 petak bergantian, jadi selalu ada angsa di kelipatan 9. Angka 9 di lemparan pertama akan melompat dari angsa ke angsa langsung ke 63"]},{"h":"Menyebar lewat percetakan","p":["Papan dicetak dari pelat tembaga dan balok kayu sehingga menjadi murah. Di Prancis namanya jeu de l’oie, di Spanyol juego de la oca, dan di sana sajak tentang melompat “dari angsa ke angsa” masih jadi ungkapan sehari-hari.","Versi bergambar baru terus bermunculan: papan untuk belajar geografi dan sejarah, tentang Revolusi Prancis atau Napoleon, bahkan iklan barang. Di atas lintasan 63 petak yang sama, setiap zaman menggambar perhatiannya sendiri."],"cap":[]}],"tl":[["Abad ke-16","Diperkirakan lahir di Italia"],["1574–87","Francesco I de’ Medici konon menghadiahkannya kepada Felipe II dari Spanyol"],["Akhir abad ke-16","Di Gujarat (India) dibuat papan dua sisi: angsa di satu sisi, catur di sisi lain"],["1597","John Wolfe mendaftarkannya untuk dicetak di London"],["Abad ke-17–18","Digemari di seluruh Eropa, versi bertema makin banyak"],["1790-an","Dibuat papan bertema Revolusi Prancis"],["Abad ke-19","Dicetak massal di banyak negara sebagai permainan anak"]]},"shogi":{"title":"Kapan aturan menurunkan bidak tawanan di shogi lahir?","lead":"Dari seluruh keluarga catur, hanya shogi yang membolehkan bidak tawanan dipasang lagi sebagai milik sendiri. Kapan — dan mengapa — aturan ini muncul?","s":["Leluhur catur dari India menyebar ke timur dan barat; di Jepang ia menjadi shogi. Bidak shogi tertua di Jepang adalah 16 bidak yang digali pada awal 1990-an di bekas lahan Kōfuku-ji, Nara. Bersama bidak itu ditemukan label bertanggal 1058 (Tenki 6), sehingga bidaknya diduga berasal dari masa yang sama.","Tulisan zaman itu juga menyebut shogi. Shin Sarugaku-ki dari pertengahan abad ke-11 menyebut namanya, dan Nichūreki, yang menghimpun catatan akhir zaman Heian, menggambarkan “shogi Heian” dengan raja, jenderal emas dan perak, kuda, tombak, dan pion.","Pada zaman Kamakura dan Muromachi muncul banyak bentuk besar dengan bidak lebih banyak. “Shogi kecil”, cikal bakal permainan sekarang, menambahkan benteng dan gajah menteri — juga bidak yang kini tak ada lagi: gajah mabuk.","Aturan memasang kembali bidak tawanan diduga muncul sekitar abad ke-16. Menurut tradisi, Kaisar Go-Nara menyuruh gajah mabuk dibuang dari shogi kecil, dan aturan ini diduga mulai pada masa yang sama.","Alasannya belum jelas. Satu penjelasan: bidak kedua pihak berwarna sama dan hanya dibedakan arah hadapnya, sehingga bidak tawanan mudah dipakai lagi. Berkat aturan ini, papan tak pernah kosong dan remis jarang terjadi."],"quiz":[["Tanggal berapa tertulis pada label yang ditemukan bersama bidak Kōfuku-ji?","1058 (Tenki 6)","701 (Taihō 1)","1582 (Tenshō 10)","1868 (Meiji 1)"],["Kapan aturan bidak tawanan diduga muncul?","Sekitar abad ke-16","Sekitar abad ke-8","Sekitar abad ke-19","Pada abad ke-20"],["Apa alasan yang disebut mengapa bidak tawanan mudah dipakai lagi?","Bidak kedua pihak sewarna, dibedakan arah hadapnya","Bidaknya dari emas","Petak papannya sedikit","Bidak dipilih dengan dadu"]],"kf":["Kerabat catur yang lahir di India lalu tumbuh di Jepang, dimainkan di papan 9×9","Bidak tertua berasal dari bekas lahan Kōfuku-ji, ditemukan bersama label bertanggal 1058","“Bidak di tangan” — memakai bidak tangkapan sebagai milik sendiri — diduga lahir sekitar abad ke-16"],"more":[{"h":"Satu warna, dibedakan oleh arah","p":["Bidak catur dicat putih dan hitam, tetapi bidak shogi semuanya berwarna kayu: pemiliknya terlihat dari arah ujung bidak bersisi lima itu. Bentuk inilah yang memungkinkan bidak tangkapan cukup diputar lalu diturunkan lagi ke papan.","Setiap bidak bertuliskan namanya, dan saat masuk wilayah lawan ia boleh dibalik untuk “promosi”. Pion menjadi と di sisi belakangnya dan bergerak seperti jenderal emas. Bidak pipih bertulisan, bukan patung ukir, adalah ciri yang sama dengan kerabatnya di Asia Timur: xiangqi Tiongkok dan janggi Korea."],"cap":["Bidak shogi berwarna sama untuk kedua pihak dan dibedakan dari arah ujungnya. Kanan: pion yang dibalik, “dipromosikan” (tokin)"]},{"h":"Zaman shogi raksasa","p":["Dari zaman Kamakura dan Muromachi hingga zaman Edo, dibuat shogi yang makin besar dengan jenis bidak yang makin banyak. Chū shogi 12×12 banyak dimainkan sepanjang zaman Edo dan masih punya penggemar.","Catatan bahkan menyebut dai shogi 15×15, tai shogi 25×25, dan taikyoku shogi dengan 804 bidak di papan 36×36. Namun permainan sehari-hari adalah shō shogi 9×9, yang kemudian mendapat aturan bidak di tangan dan menjadi shogi masa kini."],"cap":["Perbandingan ukuran papan, digambar dari satu sudut: 9×9 shogi masa kini (40 bidak), 12×12 chū shogi (92), 15×15 dai shogi (130), 25×25 tai shogi (354), 36×36 taikyoku shogi (804)"]},{"h":"Shogi di zaman Edo","p":["Pada zaman Edo muncul keluarga shogi yang digaji keshogunan; Ōhashi Sōkei dianggap sebagai master pertama. Setiap tahun para pemain terbaik bertanding di depan shogun dalam “pertandingan istana”, yang kemudian ditetapkan tanggal 17 November — asal Hari Shogi sekarang.","Shogi juga hiburan rakyat: cetakan Harunobu menggambarkan pasangan muda bermain di dekat kelambu. Lahir pula kumpulan soal tsume-shogi seindah karya seni, seperti Shōgi Zukō karya Itō Kanju (1755)."],"cap":["Cetakan kayu berwarna karya Suzuki Harunobu (sekitar 1767–69): seorang pemuda dan pemudi bermain shogi di dekat kelambu"]}],"tl":[["1058","Bidak dari bekas lahan Kōfuku-ji (ditemukan bersama label tahun Tengi 6)"],["Pertengahan abad ke-11","Shinsarugakuki menyebut shogi"],["Awal Kamakura","Nichūreki mencatat bidak shogi Heian"],["Sekitar abad ke-16","Aturan bidak di tangan diduga lahir"],["1612","Ōhashi Sōkei dkk. konon menerima gaji dari keshogunan"],["1716","Pertandingan istana ditetapkan pada 17 November"],["1755","Shōgi Zukō karya Itō Kanju"],["1975","17 November menjadi Hari Shogi"]]},"pachisi":{"title":"Bagaimana pachisi menjadi ludo","lead":"Permainan papan berbentuk salib dari istana India berganti nama dan sampai ke kamar bermain di seluruh dunia.","s":["India punya chaupar dan pachisi: empat pemain menjalankan bidak mengelilingi papan berbentuk salib. Chaupar memakai dadu panjang (pasa), pachisi memakai cangkang kauri yang dilempar. Nama pachisi berarti “dua puluh lima”, angka tertinggi dari lemparan kauri.","Para dewa pun bermain. Lukisan dari akhir abad ke-17 menampilkan Dewa Siwa dan istrinya Parwati di depan papan chaupar di atas kulit harimau.","Di Fatehpur Sikri, kota Kaisar Mughal Akbar (abad ke-16), sebuah halaman masih memiliki papan raksasa berbentuk salib di lantainya. Konon Akbar bermain dengan orang-orang berbaju warna-warni sebagai bidaknya.","Pada abad ke-19 permainan ini menyeberangi lautan. Di Amerika ia dijual dengan nama Parcheesi, menjadi merek dagang pada 1874. Di Inggris ia dijual pada 1890-an dengan nama Ludo — bahasa Latin untuk “aku bermain” — dan menjadi permainan keluarga.","Ludo lebih sederhana: satu dadu, dan angka 6 untuk mengeluarkan bidak. Kerabatnya dengan nama lain ada di seluruh dunia, seperti parchís di Spanyol dan Mensch ärgere Dich nicht (“Jangan marah”) di Jerman."],"quiz":[["Apa arti nama “pachisi”?","Dua puluh lima","Jalan raja","Salib","Cangkang kauri"],["Kota Akbar mana yang masih punya halaman berpapan raksasa?","Fatehpur Sikri","Qutb Minar di Delhi","Taj Mahal","Ellora"],["Apa arti “ludo” dalam bahasa Latin?","Aku bermain","Aku menang","Aku berlari","Aku melempar"]],"kf":["Permainan balapan di papan India berbentuk salib: empat pemain dalam dua tim membawa bidaknya berkeliling","Namanya berarti “25” — lemparan terbesar dari kerang cowrie","Pada abad ke-19 menyeberang lautan dan menyebar ke seluruh dunia sebagai Parcheesi, ludo, dan lainnya"],"more":[{"h":"Salib dan jalurnya","p":["Papan pachisi berbentuk salib dengan empat lengan yang memanjang dari charkoni di tengah. Setiap lengan berukuran 3 × 8 petak, total 96 petak. Papannya sering disulam di atas kain sehingga bisa digulung dan disimpan.","Bidak keluar dari pusat, turun lewat kolom tengah lengannya sendiri, mengelilingi papan sekali berlawanan arah jarum jam, lalu naik lagi lewat kolom tengah ke pusat. Pemain yang duduk berhadapan adalah kawan; satu tim menang bila keduanya membawa pulang keempat bidaknya."],"cap":["Papan berbentuk salib (setiap lengan 3 × 8 petak). Garis biru adalah jalur seorang pemain: turun lewat tengah lengannya sendiri, berkeliling penuh berlawanan arah jarum jam, lalu naik lagi lewat tengah ke pusat"]},{"h":"Menghitung cowrie","p":["Dalam pachisi dilempar enam kerang cowrie, dan jumlah yang jatuh dengan mulut ke atas menentukan langkah. Dua sampai enam berarti maju sebanyak itu; tetapi satu berarti maju 10, dan tak satu pun berarti maju 25.","Dengan peluang 1 banding 64, angka 25 adalah lemparan paling langka dan terbesar — dan menjadi nama permainan ini. Angka 6, 10, atau 25 memberi lemparan tambahan. Chaupar sebaliknya memakai tiga dadu batang panjang bertanda 1, 2, 5, dan 6."],"cap":["Dari enam cowrie, berapa yang jatuh dengan mulut menghadap ke atas (baris atas) dan berapa petak melangkah (baris bawah). Tinggi batang menunjukkan seberapa sering itu terjadi bila setiap kerang jatuh ke sisi mana pun sama mungkinnya"]},{"h":"Nama baru, negeri baru","p":["Melalui orang Inggris di India, permainan ini tiba di Eropa dan Amerika pada abad ke-19. Di AS menjadi merek Parcheesi; di Inggris ludo dipatenkan pada 1896, dengan aturan lebih sederhana dan satu dadu kubus sebagai pengganti cowrie.","Jerman mendapat Mensch ärgere dich nicht (“Jangan kesal”) pada 1914, dan Spanyol memainkan parchís. Nama dan detail berbeda di tiap negara, tetapi kerangkanya tetap: mengelilingi salib dan pulang ke rumah."],"cap":[]}],"tl":[["Abad ke-16","Halaman bergambar papan salib raksasa dibuat di Fatehpur Sikri milik Akbar"],["Abad ke-17–18","Lukisan miniatur India sering menggambarkan orang berkumpul di sekitar chaupar"],["1694–95","Devidasa melukis Siwa dan Parwati bermain chaupar"],["1874","Parcheesi menjadi merek dagang di AS"],["1896","Ludo dipatenkan di Inggris"],["1914","Mensch ärgere dich nicht mulai dijual di Jerman"]]},"go":{"title":"Kisah papan go berusia 1.300 tahun","lead":"Papan go di Shōsōin punya 19 garis seperti sekarang — dan 17 tanda bunga, tidak seperti sekarang.","s":["Go lahir di Tiongkok kuno. Menurut legenda, raja bijak Yao menciptakannya untuk mendidik putranya. Kitab Mencius, dari sebelum Masehi, menyebut seorang ahli permainan ini, Yi Qiu.","Ukuran papan diduga berubah seiring waktu: pada masa awal papan 17 garis juga dipakai, lalu papan 19 garis seperti sekarang menyebar.","Kapan go sampai ke Jepang belum jelas, tetapi pada zaman Nara sudah dimainkan. Aturan bagi biksu dan biksuni melarang musik dan judi, tetapi membolehkan go dan koto — sangat berbeda dari perlakuan terhadap sugoroku.","Papan go bertatah di Shōsōin diwariskan sebagai pusaka yang terkait dengan Kaisar Shōmu. Garisnya 19 seperti sekarang, tetapi ada 17 tanda bunga di tempat papan sekarang memiliki 9 titik bintang. Dua lacinya saling terhubung: menarik satu membuat yang lain ikut keluar. Shōsōin juga menyimpan batu go dari gading yang diwarnai merah dan biru tua, diukir dengan burung.","Pada zaman Heian, Hikayat Genji menggambarkan orang bermain go. Pada zaman Edo, keluarga seperti Hon’inbō mengabdi pada keshogunan, dan go menjadi seni tempat pemain profesional beradu kemahiran."],"quiz":[["Berapa garis papan go Shōsōin?","19","17","13","9"],["Apa yang dibolehkan aturan bagi biksu dan biksuni?","Go dan koto","Sugoroku","Judi","Kemari"],["Berapa tanda bunga di papan Shōsōin sebagai ganti titik bintang?","17","9","4","25"]],"kf":["Batu hitam dan putih diletakkan di titik persilangan garis, berlomba mengepung wilayah terluas — permainan yang lahir di Tiongkok kuno","Setelah masa papan 17 garis datanglah 19 garis; Shōsōin menyimpan papan 19 garis dari abad ke-8","Di Jepang zaman Edo keluarga go mengabdi pada keshogunan; pada abad ke-21 AI mengalahkan pemain terbaik dunia"],"more":[{"h":"Kepung untuk menangkap, kurung untuk menang","p":["Dalam go, hitam dan putih bergantian meletakkan batu di titik persilangan garis. Batu yang sudah diletakkan tidak bergerak lagi. Bila semua titik kosong di sebelah sebuah batu (atau kelompok) terisi batu lawan, batu itu ditangkap dan diangkat dari papan.","Pada akhirnya, wilayah yang dikurung ditambah batu tangkapan menentukan pemenang. Aturannya sedikit, tetapi papannya luas: jumlah posisi yang mungkin di papan 19 garis dihitung sekitar 10 pangkat 170."],"cap":["Cara menangkap batu. Kiri: batu hitam punya empat titik kosong di sebelahnya (merah). Tengah: putih mengepungnya dari tiga sisi, tersisa satu. Kanan: yang terakhir pun tertutup dan batu hitam ditangkap"]},{"h":"Dari 17 garis ke 19","p":["Di makam masa Han Timur di Wangdu, Hebei, Tiongkok, ditemukan papan go batu 17 garis. Sementara itu Kitab Go Dunhuang, yang diperkirakan dari sekitar abad ke-6, menyebut 361 titik — papan 19 garis. Rupanya papan membesar di antara keduanya.","Papan Shōsōin bergaris 19, tetapi alih-alih sembilan titik bintang masa kini, ia punya tanda bunga di 17 tempat. Peralihan dari 289 ke 361 titik saja sudah membuat permainan jauh lebih dalam."],"cap":["Papan 17 dan 19 garis dibandingkan menurut jumlah titiknya. Sembilan titik hitam di papan masa kini adalah “titik bintang”"]},{"h":"Go para dewa, go para master","p":["Sebuah kisah Tiongkok bercerita tentang penebang kayu yang berhenti di gunung untuk menonton para dewa bermain go — lalu sadar bahwa begitu banyak tahun telah lewat sampai gagang kapaknya lapuk. Go sebagai hiburan para dewa menjadi tema kesukaan piring dan lukisan.","Di Jepang zaman Edo, keluarga go seperti Hon’inbō digaji keshogunan dan go diasah menjadi seni. Pertandingan perpisahan Hon’inbō Shūsai pada 1938 menjadi novel Kawabata Yasunari “Sang Master Go”. Pada 2016, AI AlphaGo mengalahkan pemain terbaik dunia Lee Sedol 4–1 dan mengejutkan dunia."],"cap":["Piring pernis ukir bergambar para dewa bermain go (dinasti Ming, masa Xuande, 1425–36)"]}],"tl":[["Sekitar abad ke-4 SM","Mencius menyebut master go Yi Qiu"],["Han Timur","Papan batu 17 garis dimasukkan ke makam di Wangdu"],["Sekitar abad ke-6","Kitab Go Dunhuang menyebut 19 garis dan 361 titik"],["Abad ke-8","Papan go cendana bertatah di Shōsōin"],["1612","Hon’inbō Sansa dkk. konon menerima gaji dari keshogunan"],["1938","Pertandingan perpisahan Hon’inbō Shūsai, kelak novel Kawabata"],["2016","AlphaGo mengalahkan Lee Sedol 4–1"]]},"draughts":{"title":"Bagaimana dam lahir","lead":"Permainan papan Arab, papan catur, dan menteri catur: dam diduga lahir dari pertemuan ketiganya.","s":["Leluhur dam diduga alquerque, dimainkan di kisi 5×5 titik yang dihubungkan garis. Dalam bahasa Arab disebut qirq dan disebut dalam Kitab Lagu abad ke-10. Bangsa Moor membawanya ke Spanyol, dan aturannya tercantum dalam Kitab Permainan yang dibuat atas perintah Raja Alfonso X dari Kastilia pada abad ke-13.","Sekitar abad ke-12, mungkin di Prancis selatan, orang mulai menjalankan bidak alquerque di papan catur. Lahirlah fierges. Bidaknya diberi nama sama dengan menteri catur kala itu, fers.","Promosi — bidak yang mencapai ujung menjadi lebih kuat — sudah dicatat dalam kronik pertengahan abad ke-13. Mungkin diambil dari pion catur yang berubah menjadi menteri.","Perubahan besar terjadi di Prancis sekitar 1535: ditambahkan aturan wajib makan — jika bisa makan, harus makan — dan permainannya disebut jeu forcé, “permainan paksa”. Dam Inggris dan checkers Amerika berasal dari cabang ini.","Permainan lama tanpa wajib makan bertahan sebagai “permainan lembut untuk para wanita” dan kemudian melahirkan dam internasional 10×10. Dari satu leluhur bercabang banyak “permainan ratu”."],"quiz":[["Permainan apa yang diduga leluhur dam?","Alquerque","Senet","Liubo","Congklak"],["Kapan dan di mana aturan wajib makan ditambahkan?","Prancis, sekitar 1535","Bagdad, abad ke-10","Amerika, 1900","Jepang, abad ke-8"],["Bidak fierges dinamai menurut apa?","Menteri catur (fers)","Raja catur","Dadu","Kuda"]],"kf":["Lahir ketika bidak permainan Arab alquerque dipindahkan ke papan catur","Bidak bergerak diagonal dan menangkap dengan melompat; sampai di baris terakhir, ia menjadi raja","Sekitar 1535 ditambahkan wajib menangkap, dan pada 2007 permainan (8 × 8) terpecahkan"],"more":[{"h":"Dari titik dan garis ke papan catur","p":["Papan alquerque terdiri atas 25 titik dalam kisi 5 × 5 yang dihubungkan garis. Tiap pihak menata 12 bidak, dan permainan dimulai dari satu-satunya titik kosong di tengah. Bidak bergerak menyusuri garis dan menangkap dengan melompati bidak lawan di sebelahnya.","Ketika bidak dipindahkan ke papan catur, hanya petak satu warna yang dipakai. Papan 8 × 8 punya 32 petak gelap; bila tiga baris pertama di tiap sisi diisi, masing-masing mendapat 12 bidak — sama dengan alquerque."],"cap":["Papan alquerque dan susunan awalnya: 5 × 5 titik dihubungkan garis lurus dan diagonal, 12 bidak per pihak, hanya bagian tengah kosong"]},{"h":"Melompat, menangkap, menjadi raja","p":["Bidak maju satu petak secara diagonal dan menangkap dengan melompati bidak lawan di sebelahnya bila petak di baliknya kosong. Bila setelah itu ada tangkapan lain, ia terus melompat. Dalam aturan sekarang, jika bisa menangkap, wajib menangkap.","Bidak yang mencapai baris terakhir menjadi raja — bidak kedua ditumpuk di atasnya — dan boleh bergerak mundur. Dalam permainan internasional 10 × 10, raja meluncur sejauh apa pun di diagonal, sehingga babak akhir berubah total."],"cap":["Menangkap dan menjadi raja. Bidak merah melompati dua bidak putih berturut-turut (×), lalu kelak mencapai baris terakhir dan menjadi raja: dua bidak bertumpuk"]},{"h":"Permainan yang terpecahkan, keluarga yang meluas","p":["Di Kanada, Jonathan Schaeffer dan timnya membuat program Chinook. Pada 1992 program itu melawan Marion Tinsley, yang lebih dari 40 tahun nyaris tak pernah kalah, dan Tinsley menang. Tim itu terus menghitung dan pada 2007 membuktikan bahwa bila kedua pihak bermain sempurna, permainan (8 × 8) berakhir remis.","Sementara itu, keluarga dari leluhur yang sama hidup di seluruh dunia: dam internasional 10 × 10, shashki Rusia, dama Turki yang bergerak lurus, dam Kanada 12 × 12 — dan turnamen terus digelar di tiap negara."],"cap":[]}],"tl":[["Abad ke-10","Kitab Lagu menyebut qirq (alquerque)"],["Sekitar abad ke-12","Fierges lahir, mungkin di Prancis selatan"],["1283","Kitab Permainan Alfonso X menjelaskan alquerque"],["Sekitar 1535","Aturan wajib menangkap ditambahkan di Prancis"],["1547","Torquemada menerbitkan buku dam pertama di Spanyol"],["Abad ke-18","Papan 10 × 10 menyebar di Prancis dan Belanda"],["1992","Tinsley mengalahkan program Chinook"],["2007","Terbukti permainan (8 × 8) remis bila dimainkan sempurna"]]},"reversi":{"title":"Reversi dan Othello: siapa penemunya?","lead":"Permainan menjepit dan membalik keping hitam-putih — dan dua pria di Inggris abad ke-19 yang memperebutkannya.","s":["Di London tahun 1880-an, dua orang Inggris, Lewis Waterman dan John W. Mollett, masing-masing mengaku sebagai penemu permainan ini dan menyebut yang lain penipu.","Permainan Mollett, Annexation, dimainkan di papan berbentuk salib. Reversi milik Waterman memakai papan biasa 8×8, dan bentuk dialah yang bertahan. Pertikaian soal nama bahkan sampai ke pengadilan.","Reversi menyebar ke Eropa; pada 1893 perusahaan Jerman Ravensburger menjadikannya salah satu produk pertamanya. Di Jepang ia diuraikan dalam buku-buku zaman Meiji dan juga disebut genpei-go.","Popularitasnya tidak bertahan lama. Pada 1971 Goro Hasegawa meluncurkan “Othello”, menetapkan pembukaan dengan empat keping pertama bersilang di tengah, dan permainan ini menjadi demam di Jepang.","Namanya konon diambil dari drama Shakespeare: jenderal berkulit hitam Othello dan istrinya yang berkulit putih, Desdemona, menggemakan keping hitam dan putih. Aturan turnamen sekarang adalah aturan Othello."],"quiz":[["Kapan dan di mana kedua pria yang memperebutkan reversi hidup?","Inggris, abad ke-19","Prancis, abad ke-18","Jepang, abad ke-20","Italia, abad ke-16"],["Apa bentuk papan Annexation milik Mollett?","Salib","Lingkaran","Segitiga","Persegi 8×8"],["Siapa yang meluncurkan Othello pada 1971?","Goro Hasegawa","Hon’inbō Shūsaku","Lewis Waterman","Ravensburger"]],"kf":["Jepit bidak lawan di antara bidakmu untuk membaliknya; di akhir, yang bidaknya lebih banyak menang","Di London tahun 1880-an, dua orang Inggris memperebutkan gelar penemunya","Pada 1970-an meledak di Jepang dengan nama Othello, dan pada 2023 terbukti remis bila dimainkan sempurna"],"more":[{"h":"Jepit lalu balik","p":["Bidak hanya boleh ditaruh di tempat yang menjepit sederet bidak lawan di antara bidak itu dan bidakmu yang lain. Deretan bisa ke delapan arah — mendatar, tegak, dan diagonal — dan satu langkah bisa menjepit beberapa arah sekaligus. Semua bidak yang terjepit dibalik menjadi warnamu.","Bila tak ada langkah, kamu lewat; permainan selesai bila keduanya tak bisa melangkah. Bidak di sudut tak pernah bisa dijepit, jadi merebut sudut sangat menguntungkan. Pemain kuat lebih memikirkan mengurangi tempat lawan bisa melangkah daripada jumlah bidak saat itu."],"cap":["Cara bidak dibalik. Bidak hitam yang ditaruh di petak berlingkaran merah menjepit putih ke tiga arah — mendatar, tegak, dan diagonal — dan ketujuh bidak bertepi emas berubah hitam"]},{"h":"Empat bidak pertama","p":["Pada reversi awal, kedua pemain bergantian menaruh empat bidak pertama di empat petak tengah, sehingga pembukaannya bisa berdampingan atau menyilang.","Othello menetapkan awal menyilang. Sejak langkah pertama kedua warna mudah dijepit, sehingga pertarungan langsung dimulai. Kejuaraan dunia masa kini berangkat dari posisi ini."],"cap":["Empat bidak pertama. Kiri: salah satu awal reversi lama (warna sama berdampingan). Kanan: awal menyilang yang ditetapkan Othello"]},{"h":"Manusia dan komputer","p":["Othello menyebar dari Jepang ke seluruh dunia, dan Kejuaraan Dunia Othello pertama digelar di Tokyo pada 1977. Aturannya sederhana, jadi kedalaman perhitungan yang menentukan; pemain terbaik melihat puluhan langkah ke depan.","Pada 1997 program Logistello melawan juara dunia Takeshi Murakami dalam enam partai dan memenangkan semuanya. Pada 2023 perhitungan menunjukkan bahwa Othello 8 × 8 berakhir remis bila kedua pihak bermain sempurna."],"cap":[]}],"tl":[["1880-an","Waterman dan Mollett memperebutkan penemuan di London"],["1893","Ravensburger di Jerman meluncurkan Reversi"],["Zaman Meiji","Buku Jepang memperkenalkannya sebagai genpei-go"],["1973","Set Othello mulai dijual di Jepang"],["1977","Kejuaraan Dunia Othello pertama di Tokyo"],["1997","Logistello mengalahkan juara dunia Takeshi Murakami 6–0"],["2023","Othello 8 × 8 terbukti remis bila dimainkan sempurna"]]},"mancala":{"title":"Di mana mancala lahir?","lead":"Permainan menyebar batu dari lubang ke lubang seperti menabur benih, dimainkan di Afrika dan Asia dengan ratusan nama.","s":["Mancala adalah nama keluarga permainan di mana batu atau biji diambil dari sebuah lubang lalu ditabur satu per satu ke lubang-lubang berikutnya. Konon kata ini berasal dari bahasa Arab naqala, “memindahkan”.","Nama dan aturannya berbeda di tiap tempat — oware di Afrika Barat, bao di Afrika Timur, mangala di Turki, congklak di Asia Tenggara, dan ratusan lainnya —, dengan dua atau empat baris dan jumlah lubang yang beragam.","Ia sering disebut sangat tua, tetapi bukti yang pasti lebih muda dari dugaan. Papan tertua yang bertanggal pasti sejauh ini adalah papan tembikar dan batu dari sekitar abad ke-6–7 yang ditemukan di situs Kerajaan Aksum kuno, di Matara dan Yeha (Eritrea dan Etiopia).","Ada contoh yang diklaim lebih tua, tetapi belum pasti apakah deretan lubang itu memang untuk mancala, dan para ahli berbeda pendapat. Pandangan yang kuat menyebut permainan ini menyebar dari Aksum ke Arab dan pedalaman Afrika.","Uraian lengkap cara bermainnya baru muncul sekitar abad ke-17. Di Atlas, kamu bisa bermain mancala dengan delapan aturan, termasuk oware dan mangala."],"quiz":[["Apa arti kata Arab asal “mancala”?","Memindahkan","Biji","Lubang","Raja"],["Di mana papan mancala tertua yang bertanggal pasti ditemukan?","Di situs Kerajaan Aksum kuno (Etiopia dan Eritrea)","Di Colosseum Roma","Di Tembok Besar Tiongkok","Di Stonehenge"],["Mancala mana yang dimainkan di Afrika Barat?","Oware","Liubo","Tafl","Pachisi"]],"kf":["Keluarga permainan “menabur”: biji diambil dari satu lubang lalu dijatuhkan satu per satu ke lubang berikutnya","Papan tertua yang pasti tarikhnya berasal dari Kerajaan Aksum kuno, sekitar abad ke-6–7","Dua baris atau empat, dengan atau tanpa lumbung — papan dan aturannya berbeda di tiap wilayah"],"more":[{"h":"Menabur","p":["Dalam mancala, kamu memilih satu lubang di sisimu, mengambil semua bijinya, lalu menjatuhkannya satu per satu ke lubang-lubang berikutnya. Gerakan seperti menabur benih di ladang ini disebut menabur.","Oware dari Afrika Barat dimulai dengan 48 biji, empat di tiap 12 lubang. Bila biji terakhir membuat lubang lawan berisi dua atau tiga, biji itu kamu ambil. Mengetahui di mana taburan akan berhenti — menghitung lebih dulu — adalah kuncinya. Oware menyeberangi Atlantik dan juga dimainkan di Karibia."],"cap":["Menabur dalam oware. Tiga biji dari lubang bercincin emas dijatuhkan satu per satu berlawanan arah jarum jam; biji terakhir membuat lubang lawan berisi tepat 3, maka ketiganya diambil (cincin merah)"]},{"h":"Dua baris dan empat","p":["Papan mancala secara garis besar terbagi dua: dua baris dan empat baris. Papan dua baris banyak di Afrika Barat dan Asia; papan empat baris tersebar dari Afrika Timur hingga Afrika bagian selatan. Bao dari Tanzania berukuran 4 baris × 8 lubang; namanya dalam bahasa Swahili berarti “papan”.","Sebagian, seperti congklak dan sungka di Asia Tenggara, punya lubang besar di tiap ujung — lumbung — untuk biji tangkapan. Kalah, yang lahir di Amerika abad ke-20, adalah permainan dua baris dengan lumbung; pada 2000 perhitungan menunjukkan Kalah dengan enam lubang berisi empat biji selalu dimenangkan pemain pertama."],"cap":["Contoh bentuk papan mancala: 2 baris × 6 (oware dll.), 2 baris × 7 dengan lumbung di kedua ujung (congklak di Asia Tenggara dll.), 4 baris × 8 (bao di Afrika Timur dll.)"]},{"h":"Mereka yang mencatatnya","p":["Sarjana Eropa pertama yang menggambarkan mancala secara rinci biasanya disebut Thomas Hyde dari Inggris. Dalam De Ludis Orientalibus (1694) ia mencatat nama Arabnya dan cara bermainnya.","Pada 1836, Edward W. Lane, saat menggambarkan kehidupan sehari-hari di Kairo, mencatat “mankalah” yang dimainkan di kedai kopi. Kini para peneliti telah mengumpulkan permainan dari mana-mana, dan aturan yang tercatat mencapai ratusan."],"cap":[]}],"tl":[["Abad ke-6–7","Papan tertua yang pasti tarikhnya, dari situs Aksum"],["1694","Thomas Hyde menggambarkan mancala dalam De Ludis Orientalibus"],["Abad ke-18–19","Oware dan lainnya menyeberangi Atlantik ke Karibia"],["1836","E. W. Lane mencatat mankalah di Kairo"],["Pertengahan abad ke-20","Kalah, dua baris dengan lumbung, dijual di AS"],["2000","Dihitung bahwa Kalah enam lubang empat biji dimenangkan pemain pertama"]]},"morris":{"title":"Nine men’s morris ada di mana-mana","lead":"Atap kuil, kapal Viking, bangku batu katedral: garis-garisnya diukir di mana pun orang duduk bersama.","s":["Dalam nine men’s morris, tiap pemain menaruh sembilan bidak di 24 titik tiga persegi bersarang; tiga sebaris, sebuah “gilingan”, mengambil satu bidak lawan. Nama Inggris “morris” tak berhubungan dengan tarian: konon berasal dari bahasa Latin merellus, keping atau bidak.","Papan yang diukir di batu atap kuil Kurna di Mesir sering disebut tertua, sekitar 1400 SM. Namun peneliti Friedrich Berger menemukan salib Koptik di antara ukiran yang sama dan menyimpulkan bahwa ukiran itu tak bisa ditanggali. Contoh yang pasti dimulai pada zaman Romawi.","Di kapal Gokstad dari Norwegia, sekitar tahun 900, sebuah papan diukir di papan geladak. Di Inggris, papan masih ada di bangku batu serambi katedral seperti Canterbury dan Salisbury.","Kitab Permainan Alfonso X tahun 1283 bahkan menggambarkannya dimainkan dengan dadu. Shakespeare dalam Mimpi di Malam Pertengahan Musim Panas menulis hujan membuat “nine men’s morris” penuh lumpur — papan yang digali di padang rumput desa.","Pada 1996, Ralph Gasser dari Jerman memeriksa semua posisi dengan komputer dan membuktikan bahwa bila kedua pihak bermain sempurna, hasilnya seri. Antara dua orang, ini tetap permainan yang sangat bagus."],"quiz":[["Dari mana nama “morris” konon berasal?","Dari bahasa Latin “bidak”","Dari tarian Inggris","Dari nama orang","Dari nama kapal"],["Apa yang ditunjukkan peneliti tentang papan di Kurna?","Tak bisa ditanggali","Terbuat dari emas","Berasal dari Tiongkok","Milik seorang kaisar"],["Apa yang dibuktikan komputer pada 1996?","Bermain sempurna berakhir seri","Yang mulai selalu menang","Yang kedua selalu menang","Delapan bidak sudah cukup"]],"kf":["Sembilan bidak tiap pemain di 24 titik tiga persegi bersarang; tiga sebaris mengambil satu bidak lawan","Sejak zaman Romawi papannya dipahat di mana pun orang berkumpul: geladak kapal, bangku katedral","Pada 1996 semua posisi diperiksa komputer: bila dimainkan sempurna, hasilnya remis"],"more":[{"h":"Taruh, gerakkan, terbang","p":["Permainan berjalan dalam tiga tahap. Mula-mula pemain bergantian menaruh sembilan bidaknya di titik kosong. Setelah semua tertaruh, satu bidak digerakkan tiap giliran menyusuri garis ke titik tetangga yang kosong.","Tiga bidakmu sebaris di satu garis membentuk “gilingan”, dan kamu mengambil satu bidak lawan dari papan. Aturan yang lazim membolehkan pemain yang tinggal punya tiga bidak untuk “terbang” ke titik kosong mana pun. Yang kalah adalah yang tinggal punya dua bidak atau tak bisa bergerak."],"cap":["Papan nine men’s morris. Putih membentuk gilingan di sisi terluar (emas) dan boleh mengambil satu bidak hitam (silang merah)"]},{"h":"Dari tiga bidak hingga dua belas","p":["Keluarga ini dinamai menurut jumlah bidaknya. Morris tiga bidak adalah papan kecil yang mirip tic-tac-toe. Morris enam bidak memakai papan dua persegi bersarang.","Morris dua belas bidak menambahkan garis diagonal pada papan morris sembilan. Di Afrika Selatan namanya morabaraba; konon anak-anak penggembala menggambarnya di tanah, dan kini ia punya turnamen sendiri."],"cap":["Perbandingan papan. Angka menunjukkan jumlah bidak tiap pemain: morris tiga, enam, sembilan, dan dua belas"]},{"h":"Juara catur dan komputer","p":["Juara dunia catur Emanuel Lasker termasuk yang tergila-gila pada permainan ini. Dalam bukunya Brettspiele der Völker (1931) ia mengusulkan versi dengan sepuluh bidak tiap pemain, yang bidaknya boleh digerakkan sebelum semua ditaruh.","Pada 1996 Ralph Gasser dari Swiss menggabungkan tabel lengkap posisi akhir dengan penelusuran dari pembukaan, dan menunjukkan bahwa nine men’s morris berakhir remis bila kedua pihak bermain sempurna. Papannya hanya 24 titik, tetapi jumlah posisinya mencapai miliaran."],"cap":[]}],"tl":[["Zaman Romawi","Papan dipahat di batu di seluruh kekaisaran (contoh pasti pertama)"],["Sekitar 900","Papan dipahat di papan geladak kapal Gokstad (Norwegia)"],["1283","Kitab Permainan Alfonso X menggambarkan morris"],["Abad Pertengahan","Papan dipahat di bangku serambi katedral Inggris"],["1590-an","A Midsummer Night’s Dream karya Shakespeare menyebut papan yang penuh lumpur"],["1931","Lasker mengusulkan versi baru dalam Brettspiele der Völker"],["1996","Gasser membuktikan remis bila dimainkan sempurna"]]},"patolli":{"title":"Patolli, balapan kacang suku Aztek","lead":"Papan berbentuk salib dan kacang sebagai dadu: permainan taruhan yang begitu panas hingga dilarang orang Spanyol.","s":["Patolli adalah permainan balap orang Aztek di Meksiko. Namanya berarti kacang: lima kacang merah yang diberi tanda atau dilubangi di satu sisi dilempar, lalu bidak maju sebanyak tanda yang tampak, di lintasan berbentuk salib yang dilukis di tikar atau di tanah.","Diego Durán, yang mencatat wilayah itu pada abad ke-16, menulis bahwa pemain membakar dupa dan berdoa kepada kacang sebelum melempar, serta memohon kemenangan kepada Macuilxochitl, dewa permainan.","Para bangsawan mempertaruhkan perhiasan, jubah, bahkan diri mereka sendiri; sebagian yang kalah menjadi budak. Konon Kaisar Moctezuma juga menonton para bangsawannya bermain.","Biarawan Spanyol yang tak suka taruhan dan doa kepada dewa-dewa lama melarang patolli, merusak tikarnya, dan membakar kacangnya, sehingga hanya sedikit perangkat yang tersisa. Namun papan yang diukir di lantai batu dan bebatuan ditemukan di Teotihuacan dan situs Maya, serta pada 1977 di antara petroglif di Jalisco.","Papan salib dengan bidak yang berkeliling sangat mirip pachisi dari India. Pada 1878, E. B. Tylor dari Inggris berpendapat asalnya dari Asia; kini kebanyakan orang menganggap keduanya lahir terpisah."],"quiz":[["Apa yang dilempar dalam patolli sebagai pengganti dadu?","Kacang bertanda","Tulang hewan","Cangkang","Tongkat kayu"],["Menurut catatan, mengapa patolli dilarang?","Taruhan dan doa kepada dewa-dewa lama","Papannya terlalu besar","Kacangnya mahal","Rajanya kalah"],["Papan patolli sangat mirip permainan apa?","Pachisi","Go","Dam","Congklak"]],"kf":["Permainan balapan Aztek: lima kacang bertanda dilempar dan bidak dijalankan di papan berbentuk salib","Karena terkait taruhan dan doa kepada para dewa, permainan ini dilarang para biarawan Spanyol","Sangat mirip pachisi dari India, tetapi keduanya diduga lahir terpisah"],"more":[{"h":"Jalur salib 52 petak","p":["Papan patolli adalah jalur berbentuk salib yang digambar di kain, tikar, atau lantai batu. Rekonstruksi biasanya memberi tiap lengan dua lajur petak, yang bersama empat petak tengah berjumlah 52.","Lima puluh dua juga jumlah tahun dalam satu putaran kalender Aztek, sehingga sebagian peneliti melihat papan ini sebagai gambaran kalender atau perjalanan waktu. Bidak dibawa berkeliling sekali, dan yang pertama pulang menang."],"cap":["Papan patolli seperti yang sering direkonstruksi: empat lengan dengan dua lajur berisi enam petak, ditambah empat petak tengah, total 52. Petak merah di ujung lengan diduga petak khusus"]},{"h":"Lima kacang","p":["Sebagai pengganti dadu dilempar lima kacang yang salah satu sisinya dilubangi atau diberi tanda, lalu bidak maju sebanyak tanda yang muncul. Kelima tanda muncul bersamaan hanya sekali dalam 32 lemparan.","Konon sebelum melempar orang berbicara kepada kacang dan menyeru Macuilxochitl, dewa permainan. Kodeks Magliabechiano dari abad ke-16 menggambarkan orang-orang mengelilingi papan patolli di bawah pengawasan sang dewa."],"cap":["Dari lima kacang, berapa yang jatuh dengan sisi bertanda di atas (0–5) dan seberapa sering (dari 32), bila setiap kacang jatuh ke sisi mana pun sama mungkinnya"]},{"h":"Kembaran pachisi","p":["Bidak yang mengelilingi papan salib, langkah yang ditentukan oleh berapa benda lemparan jatuh menghadap ke atas: patolli dan pachisi atau chaupar dari India sangat mirip. Pada 1878 antropolog Inggris Tylor berpendapat bahwa ini bukan kebetulan, melainkan tanda permainan itu datang dari Asia.","Namun tak ada bukti penyeberangan samudra semacam itu. Kini kebanyakan orang berpendapat bahwa manusia di tempat yang berbeda sampai sendiri pada gagasan yang sama: jalur yang berputar dan benda untuk dilempar."],"cap":["Lukisan chaupar di India (1694–95): bidak mengelilingi papan berbentuk salib, seperti pada patolli"]}],"tl":[["Zaman Teotihuacan","Papan salib dipahat di lantai batu"],["1519–21","Spanyol menaklukkan Aztek"],["Abad ke-16","Kodeks Magliabechiano menggambarkan patolli dan Macuilxochitl"],["Sekitar 1577","Sahagún mencatat patolli dalam Kodeks Firenze"],["Sekitar 1581","Durán menggambarkan doa dan taruhan"],["1878","Tylor mengajukan asal-usul Asia"],["1977","Sebuah papan ditemukan di antara lukisan batu di Jalisco"]]},"xiangqi":{"title":"Sungai dan meriam xiangqi","lead":"“Sungai” di tengah dan meriam yang melompat untuk memakan: kapan catur Tiongkok mendapat bentuknya sekarang?","s":["Xiangqi adalah catur Tiongkok yang dimainkan di titik-titik kisi 9×10. Bidaknya berupa cakram bulat bertuliskan aksara, dan bergerak di atas garis, bukan di dalam petak seperti catur.","Petunjuk awal adalah Xuanguai lu, kumpulan kisah aneh karya menteri Dinasti Tang Niu Sengru (779–847). Mimpi seorang pria tentang pasukan mungil menyebut kuda langit, jenderal, kereta perang, dan prajurit, serta isyarat tentang ketapel. Namun papan dan langkahnya belum seperti sekarang.","Bentuk sekarang — papan 9×10, sungai, dan meriam — muncul dalam catatan Dinasti Song (960–1279). Satu set lengkap bidak ditemukan di makam Song Utara di Luoyang.","Di sungai sering tertulis “Sungai Chu, Perbatasan Han”, dari garis antara Chu milik Xiang Yu dan Han milik Liu Bang dalam perang abad ke-3 SM. Jenderal tak boleh keluar dari istananya, dan dua jenderal tak boleh berhadapan tanpa ada bidak di antaranya.","Meriam hanya bisa memakan dengan melompati tepat satu bidak. Xiangqi digemari di Vietnam sebagai cờ tướng, dan di Korea berkembang menjadi kerabat dekatnya, janggi. Di Atlas, keduanya bisa dimainkan."],"quiz":[["Di mana bidak xiangqi bergerak?","Di titik-titik garis","Di dalam petak","Mengelilingi lingkaran","Di segi enam"],["Pada dinasti apa xiangqi masa kini muncul dalam catatan?","Song","Han","Ming","Qing"],["Bagaimana meriam memakan?","Melompati satu bidak","Satu langkah lurus","Dua langkah diagonal","Hanya setelah menyeberang sungai"]],"kf":["Catur Tiongkok: bidak bundar bertulisan bertempur di titik-titik kisi 9 × 10 garis","“Sungai” melintang di tengah dan tiap pihak punya “istana” untuk jenderalnya; tiap bidak punya wilayahnya","Mendapat bentuk sekarang pada dinasti Song dan masih dimainkan puluhan juta orang di Tiongkok dan Vietnam"],"more":[{"h":"Papan bersungai dan beristana","p":["Tiap pihak punya 16 bidak: satu jenderal, 2 penasihat, 2 gajah, 2 kuda, 2 kereta, 2 meriam, dan 5 prajurit. Merah dan hitam menulis beberapa bidak berperan sama dengan aksara yang sedikit berbeda.","Jenderal dan penasihat tak boleh keluar istana, dan gajah tak boleh menyeberangi sungai. Prajurit hanya maju sebelum menyeberang sungai; setelahnya ia juga boleh ke samping. Kuda tak bisa melompat bila tepat di sampingnya, ke arah yang dituju, ada bidak. Papan itu sendiri menentukan peran tiap bidak."],"cap":["Susunan awal xiangqi. Hitam di atas, merah di bawah. Tulisan 楚河 漢界 menandai sungai; area 3 × 3 berdiagonal adalah istana"]},{"h":"Meriam yang melompat","p":["Meriam biasanya bergerak seperti kereta, sejauh apa pun menyusuri garis. Tetapi untuk menangkap, ia harus melompati tepat satu bidak di antaranya — warna apa pun — yang disebut penyangga.","Memakai bidak sebagai penyangga melahirkan taktik yang tak ada di permainan lain. Memindahkan meriam ke lajur tengah di awal, “meriam tengah”, masih termasuk pembukaan paling populer."],"cap":["Cara meriam menangkap: meriam merah melompati tepat satu bidak di antaranya — kuda hitam — untuk memakan kereta hitam di seberangnya"]},{"h":"Catatan partai dan para master","p":["Pada dinasti Ming terbit banyak buku kumpulan partai indah dan soal. Shiqing yaqu (1570) dan Juzhong mi (1632) adalah karya klasik yang masih dipelajari.","Pada abad ke-20 Hu Ronghua menjuarai kejuaraan nasional Tiongkok sepuluh kali berturut-turut, dan pada 1993 Federasi Xiangqi Dunia didirikan sehingga turnamen internasional digelar. Di taman-taman Tiongkok dan Vietnam, setiap hari orang berkerumun mengelilingi papan."],"cap":[]}],"tl":[["Abad ke-9","Xuanguai lu karya Niu Sengru menyebut jenderal, kereta, dan kuda"],["Song (960–1279)","Bentuk sekarang dengan papan 9 × 10, sungai, dan meriam muncul dalam catatan"],["Song Utara","Satu set bidak lengkap dimasukkan ke makam di Luoyang"],["1570","Kumpulan partai Shiqing yaqu"],["1632","Kumpulan partai Juzhong mi"],["1960–70-an","Hu Ronghua menjuarai kejuaraan nasional sepuluh kali berturut-turut"],["1993","Federasi Xiangqi Dunia didirikan"]]},"backgammon":{"title":"Apakah backgammon berumur 5.000 tahun?","lead":"Papan yang disebut “backgammon tertua” dan leluhur sejati permainan ini — dari istana Persia sampai klub-klub New York.","s":["“Kota Terbakar” Shahr-e Sukhteh di Iran menghasilkan papan berumur sekitar 5.000 tahun beserta 60 bidak dan dadu, yang sering disebut backgammon tertua. Namun petak-petaknya dibentuk lilitan ular yang diukir, sekitar dua puluh — bentuk yang berbeda dari permainan sekarang.","Leluhur langsung backgammon kemungkinan adalah nard dari Persia, yang muncul antara abad ke-3 dan ke-6. Sebuah kisah berbahasa Persia Tengah dari abad ke-7 sampai ke-9 menyebut menteri Bozorgmehr, setelah memecahkan teka-teki catur kiriman India, menciptakan nard sebagai balasan.","Roma punya permainan papan sendiri dengan tiga dadu, tabula — permainan sial Kaisar Zeno di kisah 3. Keluarga “tables” ini menyebar ke seluruh Eropa dan melahirkan banyak kerabat, seperti trictrac Prancis.","Nama “backgammon” muncul di Inggris abad ke-17, dan pada 1743 Edmond Hoyle menerbitkan aturan serta strateginya.","Penemuan besar terakhir, dadu pelipat ganda, konon lahir di klub-klub New York tahun 1920-an. Karena taruhan bisa dilipatgandakan di tengah permainan, backgammon menjadi permainan mendalam tentang kapan harus menekan."],"quiz":[["Bagaimana bentuk papan Shahr-e Sukhteh?","Petak dari lilitan ular","Sama dengan backgammon sekarang","Cakram bundar","Salib"],["Menurut kisah, siapa yang menciptakan nard?","Menteri Bozorgmehr","Kaisar Zeno","Edmond Hoyle","Alfonso X"],["Apa yang konon lahir di New York tahun 1920-an?","Dadu pelipat ganda","Dua dadu","24 segitiga","Lima belas bidak"]],"kf":["Lima belas bidak tiap pihak berlomba di 24 segitiga menurut lemparan dua dadu; yang pertama mengeluarkan semuanya menang","Leluhur langsungnya adalah nard dari Persia dan tabula dari Romawi, keluarga permainan “tables”","Kubus penggandaan dan komputer memberinya kedalaman baru di abad ke-20"],"more":[{"h":"Lima belas bidak dan 24 titik","p":["Papan punya 24 segitiga panjang, disebut titik, dan tiap pemain punya 15 bidak. Dua dadu dilempar, lalu satu bidak digerakkan untuk tiap angka, atau satu bidak untuk keduanya. Angka kembar boleh dipakai empat kali.","Mendarat di bidak lawan yang sendirian akan “memukulnya” ke bar di tengah; bidak itu harus masuk lagi lewat rumah lawan. Setelah kelima belas bidak sampai di rumah, bidak mulai dikeluarkan dari papan, dan yang selesai lebih dulu menang."],"cap":["Susunan awal backgammon. Putih bergerak dari 24 ke 1 (berlawanan arah jarum jam); titik 1–6 di kanan bawah adalah rumahnya. Hitam bergerak ke arah sebaliknya"]},{"h":"Makin dekat, makin mudah kena","p":["Bisa tidaknya memukul bidak yang sendirian sangat bergantung pada jarak. Dari enam titik, 17 dari 36 lemparan kena; dari tujuh titik, hanya 6.","Mengetahui angka-angka ini menunjukkan di mana bidak terancam. Di awal, tiap pemain butuh total 167 angka dadu untuk membawa pulang dan mengeluarkan semua bidak; pemain kuat menghitung “pip count” ini untuk menilai siapa yang unggul."],"cap":["Berapa dari 36 lemparan dua dadu yang bisa memukul bidak sendirian berjarak 1–12 titik (bila jalannya kosong)"]},{"h":"Dari klub ke kejuaraan dunia","p":["Pada 1743 Edmond Hoyle di Inggris menerbitkan buku aturan dan strategi. Di Inggris abad ke-19 permainan ini begitu disukai hingga dilukis di perabot, dan di klub-klub New York tahun 1920-an lahirlah kubus penggandaan.","Pada 1964 kejuaraan dunia digelar di Bahama, dan pada 1970-an permainan ini meledak. Pada 1979 program Hans Berliner mengalahkan juara dunia Luigi Villa, dan sekitar 1992 TD-Gammon, yang belajar dengan melawan dirinya sendiri, mendekati kekuatan manusia terbaik."],"cap":["Lemari bergambar dua pemain backgammon (London, 1861), salah satu karya awal Morris, Marshall, Faulkner & Co."]}],"tl":[["Sekitar 3000 SM","Papan berbentuk ular melingkar, bidak, dan dadu dikubur di Shahr-e Sukhteh"],["Sekitar abad ke-3–6","Nard muncul di Persia"],["1743","Hoyle menerbitkan buku backgammon"],["1920-an","Kubus penggandaan lahir di New York"],["1964","Kejuaraan dunia di Bahama"],["1979","Program Berliner mengalahkan juara dunia"],["Sekitar 1992","Muncul TD-Gammon yang belajar dari bermain melawan diri sendiri"]]},"hex":{"title":"Hex, ditemukan dua kali","lead":"Seorang penyair Denmark dan seorang jenius muda Amerika menciptakan permainan yang sama tanpa saling tahu.","s":["Dalam Hex, pemain bergantian meletakkan batu di belah ketupat dari segi enam; yang menghubungkan dua sisi berseberangan miliknya menang. Itu saja.","Yang pertama memikirkannya adalah matematikawan dan penyair Denmark Piet Hein. Pada 1942 ia memperkenalkannya di Institut Niels Bohr, Kopenhagen; pada 26 Desember tahun itu surat kabar Politiken memuatnya dengan nama “Polygon”, dan dijual dalam blok 50 lembar.","Pada 1943 Hein harus meninggalkan Denmark, dan permainan itu menghilang. Beberapa tahun kemudian, 1948–49, John Nash, mahasiswa pascasarjana di Princeton, menciptakan permainan yang sama secara sepenuhnya terpisah; konon teman-temannya menyebutnya “Nash”.","Pada 1952 Parker Brothers menjualnya sebagai “Hex”, dan pada 1957 Martin Gardner menampilkannya di kolomnya di Scientific American sehingga dikenal di seluruh dunia.","Hex tak pernah berakhir seri. Dan Nash membuktikan bahwa pemain pertama selalu punya strategi menang — tanpa menunjukkan apa itu. Di papan besar, cara menang itu masih belum diketahui."],"quiz":[["Bagaimana cara menang di Hex?","Menghubungkan dua sisi sendiri","Memakan semua batu","Mengepung raja","Lima sebaris"],["Apa nama permainan Hein di surat kabar Denmark?","Polygon","Nash","Con-tac-tix","Othello"],["Apa yang dibuktikan Nash?","Pemain pertama selalu bisa menang","Pemain kedua selalu menang","Selalu seri","Langkah menang yang tepat"]],"kf":["Bergantian menaruh batu di sel segi enam; yang menghubungkan dua sisi seberang warnanya menang","Ditemukan terpisah oleh Piet Hein di Denmark (1942) dan John Nash di AS (1948–49)","Tak ada remis dan terbukti pemain pertama menang — tetapi di papan besar tak ada yang tahu caranya"],"more":[{"h":"Permainan menyambung","p":["Papannya berupa belah ketupat dari sel segi enam; ukuran resminya 11 × 11. Merah memegang sisi atas dan bawah, biru sisi kiri dan kanan, dan mereka bergantian menaruh satu batu. Batu tak pernah bergerak dan tak pernah ditangkap.","Ketika papan penuh, salah satu pihak pasti sudah tersambung. Segi enam tak pernah bersentuhan hanya di sudut, jadi kamu tak bisa menyelinap menembus barisan lawan. Pada 1979 matematikawan David Gale menunjukkan bahwa sifat “tanpa remis” ini setara dengan hasil matematika terkenal, teorema titik tetap Brouwer."],"cap":["Papan hex 7 × 7. Merah menang bila menyambung atas dan bawah, biru bila menyambung kiri dan kanan. Batu merah bertepi emas sudah menyambung atas ke bawah"]},{"h":"Jembatan dan tangga","p":["Alat kesukaan pemain kuat adalah jembatan. Bila batu ditaruh bukan tepat di sebelah batu sebelumnya melainkan satu sel lebih jauh, keduanya berbagi dua sel kosong. Bila lawan menutup satu, ambil yang lain — secara praktis keduanya sudah tersambung.","Di dekat tepi dikenal banyak pola tetap, seperti “tangga” batu yang menyusuri tepi untuk mencapainya. Karena pemain pertama terlalu diuntungkan, biasanya dipakai aturan tukar: setelah langkah pertama, pemain kedua boleh mengambil batu itu sebagai miliknya."],"cap":["“Jembatan”. Dua batu merah bisa tersambung lewat salah satu dari dua sel kosong di antaranya (lingkaran putus-putus). Bila biru mengambil satu, merah mengambil yang lain"]},{"h":"Permainan para matematikawan","p":["Nash membuktikan pemain pertama menang dengan argumen “mencuri strategi”: bila pemain kedua punya strategi menang, pemain pertama bisa mengambilnya — sebuah kontradiksi. Ini bukti aneh yang tak menunjukkan satu pun langkah menang.","Pada 1950-an Claude Shannon, bapak teori informasi, membuat mesin yang bermain hex dengan rangkaian listrik. Pada 2010-an komputer memecahkan semua papan hingga 9 × 9, tetapi papan resmi 11 × 11 masih belum terpecahkan."],"cap":[]}],"tl":[["1942","Hein menerbitkan “Polygon” di koran Denmark"],["1948–49","Nash di Princeton menemukan permainan yang sama"],["1952","Parker Brothers menjualnya sebagai “Hex”"],["1950-an","Shannon membuat mesin listrik yang bermain hex"],["1957","Gardner memperkenalkannya di kolomnya"],["1979","Gale menunjukkan kaitannya dengan teorema titik tetap"],["2010-an","Papan hingga 9 × 9 dipecahkan komputer"]]},"foxgeese":{"title":"Rubah, angsa, dan bidak perak sang raja","lead":"Satu rubah, banyak angsa: sejarah panjang “permainan berburu” yang kedua pihaknya sama sekali tidak setara.","s":["Dalam rubah dan angsa, seekor rubah melompati angsa untuk memakannya, sementara para angsa berusaha mengurungnya agar tak bisa bergerak. Kedua pihak punya aturan berbeda, di papan salib dengan 33 titik yang dihubungkan garis.","Petunjuk awal adalah “halatafl” dalam Saga Grettir dari Islandia, yang ditulis sekitar abad ke-14. Artinya “papan ekor”, dan ekornya diduga ekor rubah. Kemungkinan ia cabang dari permainan tafl Nordik.","Di Inggris, pembukuan Raja Edward IV abad ke-15 mencatat pembelian “dua rubah dan 26 anjing pemburu dari perak bersepuh emas” — bidak untuk dua set, yang tampaknya waktu itu disebut “rubah dan anjing”.","Dengan 13 angsa semula, rubah terlalu kuat, sehingga cara bermain dengan lebih banyak angsa menyebar. Konon pada abad ke-19 Ratu Victoria menyukai permainan ini.","Papan salib yang sama dipakai untuk peg solitaire, permainan satu orang. Permainan berburu tempat harimau atau serigala mengejar mangsanya, seperti bagh-chal dari Nepal, ada di seluruh dunia. Di Atlas, kamu bisa memainkan rubah dan angsa maupun peg solitaire."],"quiz":[["Apa arti “hala” dalam halatafl?","Ekor","Rubah","Raja","Salju"],["Bidak apa yang tercatat di pembukuan Edward IV?","Rubah dan anjing perak","Angsa emas","Raja gading","Dadu kayu"],["Permainan satu orang apa yang memakai papan salib yang sama?","Peg solitaire","Sudoku","Solitaire (kartu)","Tangram"]],"kf":["Seekor rubah melawan 13 angsa (kemudian 17) di papan salib 33 titik","Rubah menangkap dengan melompat; angsa menang bila mengepung rubah hingga tak bisa bergerak","Papan yang sama dipakai untuk peg solitaire, dan permainan berburu semacam ini ada di seluruh dunia"],"more":[{"h":"Satu lawan tiga belas","p":["Rubah melangkah satu titik menyusuri garis dan menangkap dengan melompati angsa di sebelahnya bila titik di baliknya kosong; seperti dam, ia bisa melompat beberapa kali berturut-turut. Angsa tak bisa menangkap, dan dalam banyak versi tak boleh mundur.","Angsa berusaha merapatkan barisan tanpa celah, memojokkan rubah, dan membuatnya tak bisa melangkah. Konon dengan tiga belas angsa rubah terlalu diuntungkan; dengan tujuh belas angsa yang tak boleh mundur, permainan yang baik membuat angsa menang."],"cap":["Papan rubah dan angsa: 33 titik berbentuk salib yang dihubungkan garis. Tiga belas angsa di atas; rubah (oranye) bisa memakan angsa tepat di depannya (×) dengan melompat ke titik kosong di belakangnya"]},{"h":"Keluarga permainan berburu","p":["Sedikit bidak kuat memburu banyak bidak lemah: permainan berburu seperti ini ada di mana-mana. Dalam bagh-chal dari Nepal, empat harimau memburu dua puluh kambing di papan 5 × 5; pada 2004 perhitungan menunjukkan hasilnya remis bila dimainkan sempurna.","Asalto, yang populer di Jerman abad ke-19, memakai papan salib yang sama: dua perwira melawan dua puluh empat prajurit. Di sini para perwira mempertahankan benteng yang hendak direbut para prajurit."],"cap":["Permainan berburu dalam angka: pemburu di kiri (oranye), buruan di kanan (putih). Dari atas: rubah dan angsa (1:13), versi dengan lebih banyak angsa (1:17), bagh-chal dari Nepal (4:20), dan asalto (2:24)"]},{"h":"Dari bidak raja ke peg solitaire","p":["Catatan keuangan Edward IV dari Inggris (bertakhta 1461–83) mencatat pembelian bidak perak bersepuh emas untuk permainan rubah dan anjing pemburu. Ini juga hiburan para raja dan bangsawan.","Papan salib 33 lubang yang sama dipakai untuk peg solitaire, yang dimainkan sendirian. Sebuah gravur Prancis tahun 1697 menggambarkan seorang bangsawati memainkannya — salah satu catatan tertua tentang peg solitaire."],"cap":[]}],"tl":[["Sekitar abad ke-14","“Hala-tafl” muncul dalam Saga Grettir dari Islandia"],["Akhir abad ke-15","Edward IV membeli bidak perak untuk rubah dan anjing pemburu"],["1697","Gravur Prancis menggambarkan bangsawati bermain peg solitaire"],["Abad ke-19","Ratu Victoria konon menyukai permainan ini"],["Abad ke-19","Asalto di papan yang sama populer di Jerman"],["2004","Bagh-chal dari Nepal terbukti remis bila dimainkan sempurna"]]},"latrunculi":{"title":"Papan para prajurit Romawi","lead":"Permainan yang digemari orang Romawi, dinamai menurut prajurit bayaran. Tak ada buku aturan yang tersisa — hanya puisi, anekdot, dan papan yang digali dari tanah.","s":["Ludus latrunculorum adalah permainan perang untuk dua orang di Roma kuno. Latrunculi semula berarti prajurit bayaran atau perampok, dan bidaknya melambangkan prajurit.","Bidak bergerak di papan berkisi, dan bidak yang terjepit di antara dua bidak lawan ditangkap. Puisi abad ke-1, Laus Pisonis, menggambarkan bidak yang maju dan mundur, serta bidak yang terkepung sampai tak bisa bergerak.","Filsuf Seneca menceritakan kisah Julius Canus, yang dijatuhi hukuman mati oleh kaisar Caligula. Saat perwira datang menjemputnya, Canus sedang bermain latrunculi; ia menghitung bidak dan berkata kepada lawannya agar jangan mengaku menang setelah ia mati.","Papan-papan ditemukan di seluruh kekaisaran. Kisi yang dipahat di batu benteng dan kota berukuran sekitar 8 × 8 sampai 12 × 12. Sebuah makam abad ke-1 di Stanway, Inggris, menyimpan bidak kaca yang masih tertata di atas papannya.","Tak ada buku aturan terperinci yang tersisa; aturan sekarang adalah rekonstruksi para peneliti. Latrunculi di Atlas berpijak pada salah satunya."],"quiz":[["Bagaimana menangkap bidak dalam latrunculi?","Menjepitnya di antara dua bidak","Melompatinya","Dengan lemparan dadu","Mengepung raja"],["Siapa yang sedang bermain latrunculi saat dijemput untuk dieksekusi?","Julius Canus","Caesar","Nero","Cicero"],["Apa yang masih ada di atas papan dalam makam Stanway?","Bidak kaca","Koin emas","Bidak catur","Kartu remi"]],"kf":["Permainan perang untuk dua orang di Roma kuno, bidaknya dianggap prajurit","Bidak yang terjepit di antara dua lawan ditangkap; bidak yang tak bisa bergerak juga disebut","Tanpa buku aturan: direkonstruksi dari puisi, anekdot, dan papan galian"],"more":[{"h":"Menjepit dan mengepung","p":["Sumber terlengkap untuk rekonstruksi adalah puisi abad ke-1 Laus Pisonis. Puisi itu menggambarkan permainan seperti medan perang: satu bidak maju memancing musuh, yang lain menjaga punggungnya, dan bidak yang terjepit di antara dua musuh hilang.","Puisi itu juga menyebut bidak yang terkepung dan tak bisa bergerak, sehingga banyak rekonstruksi menambahkan aturan untuk bidak terkunci selain penangkapan dengan menjepit. Permainan tafl dari Eropa Utara memakai cara menangkap yang sangat mirip."],"cap":["Cara menangkap dalam latrunculi (rekonstruksi). Kiri: maju seperti panah biru membuat bidak putih terjepit di antara dua hitam dan ditangkap (×). Kanan: bidak putih yang terkunci dari empat sisi tak bisa bergerak"]},{"h":"Papan dua sisi","p":["Dalam puisi pengiring hadiah, penyair Martialis (abad ke-1) menggambarkan papan yang di satu sisinya bidak maju menurut dadu, sedangkan di sisi lain prajurit dua warna bertempur: permainan untung-untungan dan permainan otak di satu papan.","Sisi dadu diduga permainan balapan bernama “dua belas garis”, pendahulu tabula dan backgammon. Menara dadu (pyrgus) dalam koleksi museum juga alat yang dipakai orang Romawi."],"cap":["Gambaran papan dua sisi karya Martialis: satu sisi untuk balapan dua belas garis dengan dadu, sisi lain untuk kisi permainan prajurit"]},{"h":"Papan dari dalam tanah","p":["Prajurit Romawi memahat kisi di batu dan lantai benteng mereka untuk bermain. Papan pahatan ditemukan dekat Tembok Hadrianus di Britania, juga di Jerman, Spanyol, dan Afrika Utara.","Di makam Stanway (pertengahan abad ke-1), papan kayunya sudah lapuk, tetapi bidak kaca putih dan biru di atasnya masih di tempatnya, seolah permainan belum selesai. Pemiliknya mungkin seorang dokter: alat-alat kedokteran ikut dikubur bersamanya."],"cap":["Menara dadu (pyrgus). Orang Romawi melempar dadu lewat menara seperti ini agar tak ada kecurangan"]}],"tl":[["Abad ke-1 SM","Varro menyebut latrunculi"],["Akhir abad ke-1 SM","Ovidius menyinggung permainan ini dalam puisi cintanya"],["Abad ke-1","Laus Pisonis melukiskan permainan dalam puisi"],["Pertengahan abad ke-1","Papan dengan bidak tertata dikubur di Stanway"],["Abad ke-1","Seneca menceritakan anekdot Julius Canus"],["Akhir abad ke-1","Martialis menulis tentang papan dua sisi"],["1994","Schädler menerbitkan rekonstruksi aturannya"]]},"amazons":{"title":"Permainan yang membakar papannya sendiri","lead":"Lahir di Argentina pada 1988, Permainan Amazon memadukan langkah ratu catur dengan menghitung wilayah seperti go.","s":["Permainan Amazon dimainkan dua orang di papan 10 × 10, masing-masing dengan empat “amazon”. Permainan ini diciptakan pada 1988 oleh Walter Zamkauskas dari Argentina.","Satu langkah terdiri atas dua bagian. Mula-mula amazon bergerak seperti ratu catur, lurus mendatar, tegak, atau diagonal; lalu dari tempat ia mendarat, ia melepaskan anak panah dengan cara yang sama. Petak yang terkena anak panah tak bisa dilewati lagi.","Setiap langkah mengisi satu petak lagi, dan pemain yang tak bisa bergerak lagi kalah. Tak ada remis.","Menjelang akhir, anak-anak panah membagi papan menjadi ruang-ruang terpisah. Pemenangnya adalah yang punya lebih banyak petak kosong miliknya sendiri, jadi posisi dinilai dengan menghitung wilayah, seperti go.","Ada lebih dari 2.000 kemungkinan langkah pertama, sehingga permainan ini sulit bahkan bagi komputer. Para matematikawan menelitinya, dan ia menjadi nomor lomba di turnamen komputer."],"quiz":[["Di negara mana Permainan Amazon lahir?","Argentina","Brasil","Spanyol","Meksiko"],["Apa yang terjadi pada petak yang terkena anak panah?","Tak seorang pun bisa melewatinya lagi","Hilang pada giliran berikutnya","Menjadi bidak lawan","Menjadi poin"],["Siapa yang kalah dalam Permainan Amazon?","Yang pertama tak bisa bergerak","Yang pertama kehilangan bidak","Yang pertama membentuk wilayah","Yang kehabisan waktu"]],"kf":["Permainan dua orang di papan 10 × 10, lahir di Argentina pada 1988","Amazon bergerak seperti ratu, lalu dari tempat mendaratnya melepaskan anak panah yang membakar satu petak","Yang tak bisa bergerak kalah; di akhir wilayah dihitung seperti go"],"more":[{"h":"Bergerak, lalu memanah","p":["Amazon boleh bergerak sejauh apa pun asalkan tak melewati bidak lain atau anak panah. Dari petak tempatnya tiba, ia lalu melepaskan anak panah, juga dengan gerak ratu — bahkan ke petak yang baru saja ia tinggalkan.","Tak ada yang pernah ditangkap. Sebaliknya, setiap langkah menutup satu petak papan dan memotong jalan lawan: serangan dan pertahanan ditentukan oleh anak panah yang sama."],"cap":["Satu langkah Permainan Amazon. Amazon putih bergerak seperti ratu (biru), lalu dari tempat mendarat melepaskan anak panah dengan cara yang sama (merah). Petak anak panah tertutup selamanya"]},{"h":"Papan yang terbagi menjadi ruang","p":["Seiring permainan berjalan, anak-anak panah menyekat papan menjadi ruang-ruang. Bila di sebuah ruang hanya ada amazon milik satu pemain, petak kosongnya hanya miliknya, dipakai satu per langkah.","Saat itu permainan menjadi hitung-hitungan: yang punya lebih banyak petak terpakai bisa bergerak lebih lama. Hal ini cocok dengan teori permainan kombinatorial, dan Elwyn Berlekamp serta yang lain meneliti babak akhir Amazon secara mendalam."],"cap":["Posisi akhir (ilustrasi). Dinding petak terbakar membagi papan menjadi empat ruang: ruang hijau hanya bisa dipakai putih, ruang biru hanya hitam. Yang punya lebih banyak petak kosong bisa bergerak lebih lama"]},{"h":"Lahir di majalah, diperebutkan komputer","p":["Konon permainan ini pertama kali dimuat di sebuah majalah teka-teki Argentina. Aturannya singkat dan cukup papan catur serta beberapa bidak, sehingga ia menyebar ke seluruh dunia lewat internet.","Dengan lebih dari 2.000 kemungkinan langkah pertama, pembukaannya menuntut rasa terhadap seluruh papan, seperti go. Sejak 2000-an ia menjadi nomor lomba di turnamen komputer, tempat program-program saling bertanding."],"cap":[]}],"tl":[["1988","Walter Zamkauskas menciptakan Permainan Amazon"],["1990-an","Menyebar ke seluruh dunia lewat internet"],["2000","Berlekamp menerbitkan kajian matematika tentang babak akhirnya"],["2000-an","Menjadi nomor lomba di Olimpiade Komputer"]]},"loa":{"game":"Lines of Action","title":"Bidak yang melangkah sejauh hitunganmu","lead":"Lines of Action lahir dalam buku Sid Sackson tahun 1969. Kemenangan bukan soal memakan bidak, melainkan menyatukan semua bidakmu menjadi satu kelompok.","s":["Lines of Action (LOA) adalah permainan dua orang di papan 8 × 8, masing-masing dengan dua belas bidak. Permainan ini diciptakan Claude Soucie dan diperkenalkan pada 1969 dalam A Gamut of Games, buku karya kolektor permainan Sid Sackson.","Bidak bergerak lurus, mendatar, tegak, atau diagonal. Jauhnya tepat sama dengan jumlah bidak — milikmu dan milik lawan — di garis itu. Setiap langkah mengubah hitungan itu, sehingga jaraknya pun berubah.","Kamu boleh melompati bidakmu sendiri, tetapi tidak pernah bidak lawan. Jika berhenti di petak berisi bidak lawan, bidak itu dimakan.","Tujuannya menyatukan semua bidakmu menjadi satu kelompok yang saling bersentuhan secara mendatar, tegak, atau diagonal. Memakan bidak mengecilkan pasukan lawan, yang kadang malah membantunya bersatu — sebuah kejutan yang unik.","Aturannya singkat, tetapi sulit dihitung jauh ke depan, sehingga permainan ini lama dipakai dalam riset AI permainan. Program dari Universitas Maastricht di Belanda berkali-kali menjuarai turnamen komputer."],"quiz":[["Apa yang menentukan berapa petak sebuah bidak melangkah?","Jumlah bidak di garis itu","Hasil lemparan dadu","Jumlah bidak yang sudah dimakan","Selalu tiga petak"],["Bagaimana cara menang di LOA?","Menyatukan semua bidakmu menjadi satu kelompok","Memakan semua bidak lawan","Mencapai tepi papan seberang","Memakan raja lawan"],["Siapa yang memperkenalkan LOA dalam buku tahun 1969?","Sid Sackson","Martin Gardner","Edmond Hoyle","H. J. R. Murray"]],"kf":["Permainan dua orang di papan 8 × 8, dua belas bidak masing-masing; diciptakan Claude Soucie dan diperkenalkan dalam buku Sid Sackson tahun 1969","Bidak melangkah tepat sebanyak jumlah bidak di garisnya; boleh melompati bidak sendiri, tidak pernah bidak lawan","Yang menang bukan yang paling banyak memakan, tetapi yang pertama menyatukan semua bidaknya"],"more":[{"h":"Hitung, lalu melangkah","p":["Misalnya ada tiga bidak di baris yang melewati sebuah bidak; bidak itu melangkah tepat tiga petak di sepanjang baris tersebut, tidak lebih dan tidak kurang. Ia boleh melewati bidaknya sendiri, tetapi jika ada bidak lawan di antaranya, ia tidak bisa ke arah itu.","Setiap bidak berada di empat garis — satu baris, satu kolom, dan dua diagonal — masing-masing dengan hitungannya sendiri. Saat satu bidak bergerak, hitungan beberapa garis di sekitarnya berubah, sehingga “jarak” di papan teracak ulang setiap langkah. Inilah yang membuat LOA sulit ditebak."],"cap":["Ke mana bidak hitam tempat panah bermula bisa pergi. Di baris ada 3 bidak, jadi ia melangkah 3 (melompati bidak sendiri boleh); di kolom ada 2, jadi ia melangkah 2 dan memakan bidak putih. Di diagonal juga ada 3, tetapi bidak putih menghalangi jalan (×)"]},{"h":"Satu kelompok menang","p":["Bidak dianggap tersambung bila bersentuhan secara mendatar, tegak, atau diagonal. Pemain yang tinggal punya satu bidak juga dianggap “tersambung”, jadi memakan terlalu banyak bisa malah menghadiahkan kemenangan kepada lawan.","Apa yang terjadi jika satu langkah menyatukan kedua pihak sekaligus berbeda menurut edisi dan turnamen. Edisi pertama buku Sackson menyebutnya seri, edisi sesudahnya kemenangan bagi yang melangkah, dan kebanyakan turnamen kini menghitungnya seri. Dalam LOA di Atlas ini, yang melangkah menang."],"cap":["Posisi menang. Bidak putih (tepi emas) saling bersentuhan, termasuk diagonal, dan membentuk satu kelompok. Hitam masih terpecah menjadi tiga (garis putus-putus)"]},{"h":"Permainan yang diperebutkan komputer","p":["Dengan papan kecil, aturan singkat, dan permainan yang dalam, LOA menjadi ajang uji AI permainan. MIA, program buatan Mark Winands di Universitas Maastricht, menjuarai Olimpiade Komputer pada 2003, 2004, 2006, dan 2009, dan karyanya dihimpun dalam disertasi doktoralnya tahun 2004, Informed Search in Complex Games.","Pada 2008 Winands memecahkan LOA di papan kecil 6 × 6, menunjukkan bahwa dengan permainan sempurna pemain pertama (Hitam) menang. Permainan penuh 8 × 8 diyakini masih belum terpecahkan. Para pemain manusia juga bertanding dalam kejuaraan dunia yang digelar setiap tahun di Mind Sports Olympiad."],"cap":[]}],"tl":[["sekitar 1960","Claude Soucie disebut-sebut menciptakan LOA"],["1969","Diperkenalkan dalam A Gamut of Games karya Sid Sackson"],["2003","MIA karya Winands menjuarai Olimpiade Komputer (lagi pada 2004, 2006, dan 2009)"],["2004","Disertasi doktoral Winands, Informed Search in Complex Games"],["2008","LOA 6 × 6 terpecahkan: pemain pertama menang"]]},"konane":{"title":"Permainan lava hitam dan karang putih","lead":"Kōnane, yang dimainkan orang Hawaii, tercatat dalam kisah pelayaran Cook; pada abad ke-20 para matematikawan membedahnya dengan teori permainan kombinatorial.","s":["Kōnane adalah permainan dua orang dari penduduk asli Hawaii. Batu hitam dan putih memenuhi papan secara berselang-seling tanpa celah, dan pemain memakan batu lawan dengan melompatinya.","Dulu batu hitam terbuat dari lava dan yang putih dari pecahan karang. Papannya, disebut papamū, berupa batu datar besar yang permukaannya dipahat lekukan-lekukan kecil. Konon permainan ini bahkan muncul dalam Kumulipo, nyanyian penciptaan Hawaii.","Mula-mula Hitam mengangkat salah satu batunya, lalu Putih mengangkat satu batu di sebelahnya. Dua lubang yang terbentuk menjadi titik awal lompatan.","Setiap langkah adalah memakan. Batu melompat mendatar atau tegak melewati batu lawan di sebelahnya dan mendarat di petak kosong di baliknya. Selama lurus, ia boleh terus melompat.","Pemain yang tak lagi bisa memakan kalah; tidak ada hasil seri. Rancangan sederhana ini kelak menarik minat para matematikawan."],"quiz":[["Dari apa batu putih kōnane zaman dulu dibuat?","Karang","Gading","Marmer putih","Tulang hewan"],["Siapa yang kalah dalam kōnane?","Pemain yang tak lagi bisa memakan","Pemain yang semua batunya dimakan","Yang pertama mencapai tepi papan","Pemain yang tinggal punya satu batu"],["Saat melompat beruntun, apa yang tidak boleh?","Berbelok di tengah jalan","Memakan lebih dari satu batu dalam satu giliran","Berhenti di tengah","Mendarat di sebelah batu sendiri"]],"kf":["Permainan dua orang penduduk asli Hawaii, dimulai dengan batu hitam (lava) dan putih (karang) berselang-seling memenuhi papan","Setiap langkah melompati batu lawan secara mendatar atau tegak dan memakannya; bila lurus, boleh melompat lagi","Yang tak lagi bisa memakan kalah; matematikawan menelitinya dengan teori permainan kombinatorial"],"more":[{"h":"Lompat dan makan","p":["Lompatan hanya mendatar atau tegak, tidak pernah diagonal. Jika petak di balik batu lawan di sebelahnya kosong, batu melompat dan mendarat di sana, lalu batu yang dilompati diangkat dari papan.","Jika dari tempat mendarat ia bisa melompat lagi, ia boleh melanjutkan ke arah yang sama. Ia tidak boleh berbelok di tengah jalan, dan boleh berhenti kapan saja. Setiap giliran hanya satu batu yang bergerak."],"cap":["Batu putih melompat dua kali ke kanan dalam satu giliran dan memakan dua batu hitam (biru 1 dan 2). Ia tidak boleh berbelok dan melompat ke bawah dari tempat mendarat (×)"]},{"h":"Dua lubang pertama","p":["Di papan yang penuh batu, tak ada yang bisa melompat. Karena itu Hitam, yang jalan lebih dulu, mengangkat salah satu batunya dari empat petak tengah atau dari sudut. Lalu Putih mengangkat batunya yang bersebelahan mendatar atau tegak dengan lubang itu.","Dua lubang yang berdampingan menjadi tempat mendarat pertama. Di mana lubang itu dibuka menentukan seluruh jalannya permainan."],"cap":["Dua cara memulai. Hitam mengangkat batunya dari empat petak tengah (kiri) atau dari sudut (kanan) (1), lalu Putih mengangkat batu di sebelahnya (2)"]},{"h":"Papan batu dan 238 petak","p":["Kisah pelayaran ketiga James Cook (jilid III, terbit 1784) menggambarkan permainan batu yang dilihat di Hawaii “sangat mirip dengan dam kami”, tetapi lebih rumit. Penulisnya perwira James King, yang menyebut papannya sekitar dua kaki panjangnya dengan 238 petak, empat belas per baris.","Ukurannya tidak tetap: dikenal papan 6 × 7, 9 × 13, 13 × 20, dan lainnya. Kini permainan biasanya dimainkan di papan persegi bersisi genap, dan Atlas ini menyediakan 6 × 6, 8 × 8, dan 10 × 10. Di Taman Bersejarah Nasional Puʻuhonua o Hōnaunau di Pulau Hawaii, papamū yang dipahat di batu masih bisa dilihat."],"cap":["Perbandingan ukuran papan: papan 14 × 17 (238 petak) dalam kisah pelayaran Cook, serta papan 10 × 10, 8 × 8, dan 6 × 6 yang bisa dimainkan di Atlas ini"]},{"h":"Permainan yang ditemukan para matematikawan","p":["Dalam kōnane, yang tak bisa bergerak kalah, dan menjelang akhir papan terpecah menjadi bagian-bagian yang berdiri sendiri — sangat cocok untuk teori permainan kombinatorial Elwyn Berlekamp dan rekan-rekannya. Michael Ernst menulis makalah singkat tentang kōnane bersama Berlekamp pada 1993, lalu dalam makalah 1995 menghitung nilai banyak posisi.","Penelitian lain menyusul: Alice Chan dan Alice Tsai meneliti kōnane satu baris (2002), dan Bob Hearn menunjukkan bahwa di papan yang makin besar, menentukan siapa pemenangnya menjadi luar biasa sulit (PSPACE-lengkap). Permainan melompatkan batu telah menjadi pokok bahasan teori komputasi."],"cap":[]}],"tl":[["1778","Kapal-kapal Cook tiba di Hawaii"],["1784","Kisah pelayaran ketiga Cook terbit, memuat gambaran King tentang permainan batu"],["1993","Ernst dan Berlekamp menulis makalah singkat tentang kōnane"],["1995","Makalah Ernst “Playing Konane Mathematically”"],["2002","Chan dan Tsai merangkum hasil penelitian kōnane satu baris"]]},"peg":{"title":"Teka-teki lompat yang lahir di istana","lead":"Peg solitaire dimainkan pada akhir abad ke-17 di istana Prancis Louis XIV. Teka-teki sederhana mengurangi pasak satu per satu ini memikat para matematikawan sejak itu.","s":["Peg solitaire adalah teka-teki untuk satu orang. Pasak memenuhi lubang-lubang papan, dan hanya satu lubang dibiarkan kosong.","Pasak melompati pasak di sebelahnya, mendatar atau tegak, ke lubang kosong di baliknya. Pasak yang dilompati diangkat dari papan.","Tujuannya terus melompat sampai tinggal satu pasak. Menyisakannya tepat di tengah adalah akhir yang sempurna.","Catatan pasti pertama berasal dari Prancis akhir abad ke-17, dari istana Louis XIV. Pada 1697 majalah Mercure galant memuat papan dan aturannya, dan sebuah gravur menampilkan seorang bangsawan wanita dengan papan di sisinya.","Kelihatannya mudah, tetapi sulit. Matematikawan Leibniz pun tertarik, dan pada abad ke-20 para matematikawan menjelaskan, dengan mewarnai lubang-lubangnya, mengapa sebagian soal tak bisa diselesaikan."],"quiz":[["Apa yang terjadi pada pasak yang dilompati?","Diangkat dari papan","Menjadi milik lawan","Bergeser ke lubang sebelah","Kembali pada giliran berikutnya"],["Berapa lubang di papan Inggris?","33","37","45","64"],["Dari mana catatan pasti pertama peg solitaire berasal?","Istana Prancis Louis XIV, akhir abad ke-17","Pemandian Romawi kuno","Sekolah kuil Jepang zaman Edo","Bar di Amerika abad ke-19"]],"kf":["Teka-teki lompat untuk satu orang: lompati pasak untuk mengangkatnya, dan menang bila tersisa satu","Catatan pasti dimulai sekitar 1697 di istana Louis XIV; papan klasik punya 33 (Inggris) dan 37 (Eropa) lubang","Mewarnai lubang dengan tiga warna memberi tahu lebih dulu soal mana yang mustahil"],"more":[{"h":"Lompat dan angkat","p":["Lompatan hanya mendatar atau tegak, tidak pernah diagonal (kecuali di papan bergaris diagonal seperti segitiga). Setiap lompatan mengurangi satu pasak, jadi dari 32 pasak perlu 31 lompatan hingga tersisa satu.","Pasak yang sama boleh melompat beberapa kali berturut-turut. Bila rangkaian itu dihitung satu langkah, soal “dari tengah ke tengah” di papan Inggris dapat diselesaikan dalam 18 langkah. Ernest Bergholt menemukan solusi ini pada 1912, dan pada 1964 John Beasley membuktikan bahwa tidak bisa lebih pendek."],"cap":["Langkah pertama di papan Inggris. Saat tengah kosong, pasak di atas melompati pasak di bawahnya ke tengah (biru); pasak yang dilompati diangkat (×)"]},{"h":"Dari hiburan istana","p":["Sejarah pasti peg solitaire bermula di istana Louis XIV sekitar 1697. Agustus tahun itu, majalah Mercure galant menjelaskan papan, aturan, dan beberapa soal, dan pembuat gravur Claude-Auguste Berey menggambarkan Putri Soubise dengan papan di sisinya.","Ada pula kisah terkenal tentang seorang bangsawan yang dipenjara di Bastille dan menciptakan teka-teki ini untuk mengusir bosan, tetapi itu legenda yang tak bisa dipastikan. Papan 37 lubang yang dipakai di Prancis konon juga sudah ada sejak abad ke-17, sedangkan papan 33 lubang yang sudutnya dipotong disebut papan Inggris."],"cap":["Dua papan klasik: Inggris dengan 33 lubang (kiri) dan Eropa dengan 37 lubang (kanan). Lubang kosong adalah lubang awal yang biasa dipakai masing-masing"]},{"h":"Yang terungkap oleh tiga warna","p":["Warnai lubang-lubang dengan tiga warna sehingga warnanya berjajar mengikuti diagonal. Maka tiga lubang berurutan, mendatar atau tegak, selalu berwarna tiga yang berbeda. Satu lompatan mengurangi satu pasak dari dua warna dan menambah satu pada warna ketiga, sehingga ganjil-genap jumlah ketiga warna berubah bersama-sama.","Di papan Eropa dengan tengah kosong, setiap warna punya 12 pasak — semuanya genap. Setiap lompatan hanya berganti antara “semua genap” dan “semua ganjil”, sehingga posisi satu pasak terakhir — satu warna 1, dua lainnya 0 — tak pernah tercapai. Di papan ini, soal yang dimulai dari tengah tidak punya solusi. Pemeriksaan yang sama di papan Inggris mempersempit lubang tempat pasak terakhir bisa tersisa, bila dimulai dari tengah, menjadi hanya lima."],"cap":["Papan Eropa 37 lubang yang diwarnai tiga warna mengikuti garis diagonal. Saat tengah kosong, setiap warna punya 12 pasak"]},{"h":"Mainan para matematikawan","p":["Leibniz konon menulis dalam catatan tahun 1710 bahwa ia suka memainkannya terbalik — mengisi kembali lubang yang telah dilompati. Berpikir mundur dari akhir masih menjadi cara dasar menyelesaikannya.","Winning Ways (1982) karya Berlekamp, Conway, dan Guy menganalisis teka-teki ini secara mendalam dan memperkenalkan “fungsi pagoda”: beri setiap lubang nilai sehingga tak ada lompatan yang menaikkan jumlahnya, maka beberapa tujuan dapat dibuktikan mustahil. Pada 1999, pencarian komputer konon telah memeriksa semua posisi."],"cap":[]}],"tl":[["1697","Dimainkan di istana Louis XIV; Mercure galant edisi Agustus memuat papan dan aturan"],["1710","Leibniz konon menulis tentang memainkannya terbalik"],["1912","Bergholt menemukan solusi 18 langkah di papan Inggris"],["1964","Beasley membuktikan tak ada solusi kurang dari 18 langkah"],["1982","Winning Ways memaparkan analisisnya, termasuk fungsi pagoda"]]},"fanorona":{"title":"Memakan dengan mendekat, memakan dengan menjauh","lead":"Fanorona adalah permainan nasional Madagaskar. Menurut legenda, permainan ini pernah menentukan takhta — dan pada abad ke-21 komputer menunjukkan bahwa dengan permainan terbaik hasilnya seri.","s":["Fanorona adalah permainan dua orang yang sangat populer di Madagaskar. Dimainkan di papan 9 × 5 bergaris mendatar, tegak, dan diagonal, dengan 22 bidak per pihak.","Papannya tampak seperti dua papan alquerque — permainan dunia Arab dan Eropa — yang diletakkan berdampingan. Alquerque diduga tiba di pulau itu dan berkembang menjadi permainan tersendiri.","Ciri utamanya adalah cara memakan. Bergerak mendekati bidak lawan (“pendekatan”) atau menjauhinya (“penarikan”) memakan seluruh deret bidak lawan pada garis itu.","Memakan itu wajib, dan bidak yang sudah memakan boleh berganti arah dan terus memakan. Satu giliran bisa mengubah papan sepenuhnya — itulah serunya fanorona.","Dicintai selama berabad-abad, permainan ini bahkan punya legenda tentang pangeran yang kehilangan takhta karena tak bisa berhenti bermain. Pada 2007, peneliti Belanda menunjukkan dengan komputer bahwa bila kedua pihak bermain terbaik, hasilnya seri."],"quiz":[["Berapa ukuran papan fanorona?","9 × 5","8 × 8","7 × 7","6 × 6"],["Apa dua cara memakan dalam fanorona?","Pendekatan dan penarikan","Melompat dan menjepit","Mengepung dan mendorong","Dadu dan undian"],["Apa yang ditunjukkan komputer bila bermain terbaik?","Seri","Pemain pertama menang","Pemain kedua menang","Belum diketahui apa-apa"]],"kf":["Permainan dua orang dari Madagaskar: 22 bidak masing-masing di papan 9 × 5, hanya titik tengah kosong di awal","Mendekati bidak lawan atau menjauhinya memakan seluruh deret pada garis itu","Pada 2007 komputer menunjukkan bahwa dengan permainan terbaik hasilnya seri"],"more":[{"h":"Pendekatan dan penarikan","p":["Dalam pendekatan, jika tepat setelah titik tujuan ada bidak lawan, bidak itu dan semua bidak lawan yang berderet di belakangnya tanpa celah dimakan. Penarikan kebalikannya: dimakan bidak lawan yang tepat di belakang titik awal beserta yang berderet di belakangnya.","Karena satu langkah bisa menghapus beberapa bidak sekaligus, pasukan cepat menyusut sejak awal. Jika satu langkah memungkinkan pendekatan dan penarikan sekaligus, pemain memilih salah satu."],"cap":["Dua cara memakan. Atas: putih melangkah ke kanan mendekati bidak hitam dan memakan tiga hitam yang berderet di depannya (pendekatan). Bawah: putih melangkah ke kanan menjauhi bidak hitam dan memakan dua hitam di belakangnya (penarikan)"]},{"h":"Dua papan alquerque berdampingan","p":["Papan punya 5 × 9 = 45 titik; selain garis mendatar dan tegak, garis diagonal melewati titik secara berselang. Bidak bergerak satu langkah di sepanjang garis ke titik tetangga. Di awal hanya titik tengah kosong, jadi langkah pertama selalu memakan.","Papan ini adalah dua papan alquerque 5 × 5 yang disambung. Alquerque adalah permainan tua yang namanya sudah muncul dalam buku Arab abad ke-10, dan fanorona diduga berasal darinya. Kapan dan bagaimana tiba di pulau itu tidak jelas; sebagian buku menyebut sekitar abad ke-17."],"cap":["Posisi awal: 22 bidak hitam dan 22 putih di titik-titik 9 × 5, hanya titik tengah yang kosong. Kotak putus-putus menandai dua papan alquerque 5 × 5"]},{"h":"Rantai makan","p":["Bidak yang sudah memakan boleh memakan lagi. Namun setiap langkah harus ke arah yang berbeda, dan tidak boleh kembali ke titik yang sudah dilewati. Lanjut atau tidak terserah pemain.","Bila rantai seperti ini berhasil, satu giliran bisa menghabiskan hampir separuh bidak lawan. Namun bila berakhir di tempat buruk, bidak itu segera dimakan balik."],"cap":["Contoh rantai makan. Putih (1) mendekat ke kanan dan memakan dua; (2) menarik diri ke atas dan memakan dua; (3) mendekat ke kiri dan memakan dua. Setelah (1) ia tidak boleh terus ke kanan (×)"]},{"h":"Takhta dan komputer","p":["Menurut legenda, Ralambo, raja Imerina sekitar abad ke-16, berpura-pura sakit agar putra yang pertama pulang mewarisi takhta. Si sulung, Andriantompokoindrindra, tak bisa meninggalkan posisi fanorona yang sulit, dan si bungsu, Andrianjaka, menjadi raja. Kisah lain menyebut bahwa saat invasi Prancis tahun 1895 pihak ratu mengandalkan permainan fanorona ritual; keduanya tak dapat dipastikan.","Pada 2007, Maarten Schadd dan rekan-rekannya dari Universitas Maastricht, Belanda, menghitung semua posisi dengan tujuh bidak atau kurang dan, dengan pencarian bilangan bukti, menunjukkan bahwa posisi awal adalah seri (makalahnya terbit 2008). Perhitungannya memakan lebih dari seminggu di satu mesin."],"cap":[]}],"tl":[["sekitar abad ke-16","Legenda suksesi Raja Ralambo dan fanorona"],["sekitar abad ke-17","Salah satu pendapat tentang kapan fanorona lahir dari alquerque"],["1895","Legenda permainan fanorona ritual saat invasi Prancis"],["2007","Schadd dan rekan menunjukkan dengan komputer bahwa hasilnya seri"],["2008","Makalah “Best Play in Fanorona Leads to Draw”"]]},"janggi":{"title":"Papan tanpa sungai dan meriam yang melompat sekali saja","lead":"Janggi, yang sangat digemari di Korea, memakai papan 9 × 10 yang sama dengan xiangqi Tiongkok — tetapi menghapus sungainya dan banyak mengubah cara bidak bergerak.","s":["Janggi adalah permainan catur dua orang yang sudah lama dimainkan di Korea. Diduga berasal dari xiangqi Tiongkok; bidaknya diletakkan di titik-titik jaringan 9 × 10 garis.","Berbeda dengan xiangqi, papan tidak punya “sungai” di tengah, jadi gajah dan prajurit bisa ke mana saja. Jenderal (raja) mulai di tengah “istana”-nya dan tidak pernah boleh keluar.","Kedua pihak adalah Cho (biru atau hijau) dan Han (merah). Bidaknya segi delapan, dan makin kuat bidaknya makin besar ukurannya. Cho jalan lebih dulu.","Sebelum bermain, setiap pihak memilih satu dari empat cara menata kuda dan gajah. Han menata lebih dulu dan Cho memutuskan setelah melihatnya, jadi adu siasat dimulai sebelum langkah pertama.","Selain skakmat, permainan bisa diputuskan dengan poin. Cho, yang jalan duluan, mulai dari 72 poin; Han mendapat “deom” 1,5 poin dan mulai dari 73,5. Setiap bidak yang hilang mengurangi poin."],"quiz":[["Apa yang tidak ada di papan janggi?","Sungai di tengah","Istana","Garis diagonal di istana","90 titik"],["Apa yang selalu harus dilakukan meriam untuk bergerak?","Melompati tepat satu bidak","Berada di sebelah bidak lawan","Berada di dalam istana","Tidak sedang diskak"],["Dalam hitungan poin, berapa “deom” yang diterima Han, pemain kedua?","1,5","0,5","3","6,5"]],"kf":["Catur Korea yang lahir dari xiangqi: papan 9 × 10, tetapi tanpa sungai","Gajah bergerak satu lurus dan dua diagonal; meriam bergerak dan memakan dengan melompati tepat satu bidak","Setiap pihak memilih satu dari empat tatanan kuda dan gajah; dalam hitungan poin Han mendapat deom 1,5"],"more":[{"h":"Papan tanpa sungai dan empat tatanan","p":["Papan janggi punya 9 × 10 titik yang sama dengan xiangqi, tetapi tanpa sungai di tengah. Setiap istana punya garis diagonal berbentuk X, dan jenderal serta pengawal bergerak satu langkah di dalamnya, juga di sepanjang diagonal. Jenderal mulai tepat di tengah istananya.","Ada empat tatanan, hasil menukar posisi kuda dan gajah. Han menata lebih dulu, dan Cho memilih setelah melihatnya. Gajah ditaruh di dalam atau di luar akan mengubah jalur serangan pembukaan."],"cap":["Papan janggi dan posisi awal. Tidak ada sungai; istana di atas dan di bawah punya garis diagonal. Lingkaran putus-putus menandai tempat kuda dan gajah bisa ditukar; Han (atas) dan Cho (bawah) memilih tatanan berbeda"]},{"h":"Kuda, gajah, dan titik yang terhalang","p":["Kuda melangkah satu titik lurus dulu, lalu satu titik diagonal ke luar. Gajah lebih jauh: satu titik lurus, lalu dua diagonal. Pada keduanya, bidak di titik sepanjang jalan menghalangi arah itu.","Gajah xiangqi tak bisa menyeberangi sungai dan hanya bergerak dua titik diagonal, tetapi gajah janggi berkaki panjang dan bisa menjelajah seluruh papan. Sebagai gantinya, jalannya mudah dihalangi."],"cap":["Kuda (kiri) bergerak satu lurus dan satu diagonal; gajah (kanan) satu lurus dan dua diagonal. Titik biru menunjukkan tujuan. Bidak di titik sepanjang jalan menghalangi arah itu (×)"]},{"h":"Meriam yang melompat sekali saja","p":["Meriam harus melompati tepat satu bidak di antaranya, baik untuk bergerak maupun memakan. Jika tak ada apa-apa di antaranya, ia tak bisa bergerak, sehingga di posisi awal meriam diam.","Baik bidak yang dilompati maupun yang dimakan tidak boleh meriam, jadi dua meriam hanya bisa saling menatap. Dibanding meriam xiangqi, yang bebas bergerak saat tidak memakan, ini bidak yang jauh lebih rewel."],"cap":["Meriam. Atas: melompati tepat satu prajurit dan pergi ke titik di baliknya, atau memakan kereta (biru). Tengah: tak bisa melompat bila bidak di antaranya meriam. Bawah: meriam tak bisa memakan meriam (×)"]},{"h":"Jenderal berhadapan dan poin","p":["Bila dua jenderal berhadapan di garis tanpa apa pun di antaranya, itu disebut “bikjang”. Menurut satu aturan, jika pihak yang dihadapi tidak memecahkannya, permainan seri. Aturan tradisional juga membolehkan melewatkan giliran bila tidak sedang diskak.","Nilainya: kereta 13, meriam 7, kuda 5, gajah 3, pengawal 3, prajurit 2. Cho berjumlah 72 poin, Han 73,5 dengan deom. Karena ada setengah poin, hitungan poin tak pernah seri. Dalam janggi di Atlas ini, poin ini menentukan hasil bila posisi terulang tiga kali atau setelah 200 langkah."],"cap":[]}],"tl":[["Zaman Goryeo","Satu pendapat menyebut sudah dimainkan (waktu kedatangannya diperdebatkan)"],["abad ke-18","Varian papan besar, gwangsanghui, konon tercatat"],["1895","Korean Games karya Stewart Culin memuat gambar orang bermain janggi"],["2009","Turnamen internasional pertama konon diadakan di Harbin, Tiongkok"]]},"pic":{"tlvmirror":"Cermin TLV (Han Timur, Museum Seni Cleveland)","kotoboard":"Empat Keterampilan (zaman Edo, sekitar 1620–50, Museum Seni Cleveland)","homerbg":"Winslow Homer, Backgammon (cukil kayu, sekitar 1877, Museum Seni Cleveland)","trictrac":"Philips de Koninck, Para pemain tric-trac (gambar, sekitar 1660, Museum Seni Cleveland)","gametable":"Meja permainan dengan papan catur dan Nine Men’s Morris (Mainz, sekitar 1735, Museum Seni Cleveland)","kota":"Penguasa Kota memuja Krishna; di anak tangga ada kain chaupar berbentuk salib (sekitar 1825, Museum Seni Cleveland)"},"mahjong":{"game":"Mahjong","title":"Permainan ubin yang dinamai burung pipit","lead":"Mahjong lahir di Tiongkok abad ke-19. Permainan kartu berubah menjadi ubin, menjadi demam di Amerika tahun 1920-an, dan di Jepang tumbuh menjadi riichi mahjong.","s":["Mahjong adalah permainan ubin untuk empat orang. Memakai 136 ubin (144 dengan bunga), dan pemain yang pertama melengkapi tangan berbentuk tertentu menang.","Mahjong lahir di Tiongkok abad ke-19. Akarnya adalah permainan “ambil dan buang” dengan kartu bergambar satuan uang; kartu kertas diduga berubah menjadi ubin sekitar pertengahan abad itu.","Ubin tertua yang masih ada berasal dari sekitar 1870 dan diperoleh di Ningbo, Shanghai, dan Fuzhou. Sebagian buku menyebut permainan ini lahir di Ningbo; yang lain menyebut asalnya hiburan nelayan Fujian dan Guangdong.","“Máquè” berarti burung pipit, dan satu teori mengaitkan namanya dengan permainan kartu yang lebih tua, madiao. Kisah yang sering diulang bahwa Konfusius menciptakannya sama sekali tidak berdasar.","Pada abad ke-20 mahjong menyeberangi lautan. Ia menjadi demam di Amerika tahun 1920-an, dan di Jepang aturan “riichi” yang muncul kemudian menjadikannya permainan tersendiri."],"quiz":[["Tanpa bunga, berapa jumlah ubin mahjong?","136","144","108","152"],["Apa bentuk dasar tangan yang menang?","Empat set dan satu pasang","Hanya tujuh set","Tiga belas ubin sama","Tiga set dan dua pasang"],["Di negara mana mahjong menjadi demam pada 1920-an?","Amerika Serikat","Rusia","Brasil","Mesir"]],"kf":["Permainan ubin untuk empat orang yang lahir dari permainan kartu di Tiongkok abad ke-19","Ubin angka karakter, bulatan, dan bambu, ditambah angin dan naga; menang dengan empat set dan satu pasang","Demam di Amerika 1920-an; di Jepang pascaperang tumbuh riichi mahjong"],"more":[{"h":"136 ubin","p":["Ubin angka terdiri atas tiga jenis — karakter, bulatan, dan bambu — masing-masing 1 sampai 9 dengan empat salinan: 108 ubin. Ditambah empat dari tiap angin (timur, selatan, barat, utara) dan tiap naga (putih, hijau, merah), jumlahnya 136.","Banyak cara bermain di Tiongkok juga memakai delapan ubin bunga: plum, anggrek, krisan, dan bambu, serta empat musim. Ubin itu tidak masuk tangan; bila terambil, disisihkan dan menambah skor. Mahjong Jepang biasanya tidak memakainya."],"cap":["Jenis-jenis ubin. Karakter, bulatan, dan bambu 1–9, angin (timur, selatan, barat, utara), dan naga (putih, hijau, merah), masing-masing empat: 136. Dengan delapan bunga di bawah garis titik-titik (masing-masing satu): 144"]},{"h":"Empat set dan satu pasang","p":["Tangan berisi 13 ubin; pemain mengambil satu dan membuang satu, berulang-ulang. Bila ubin yang diambil, atau yang dibuang orang lain, melengkapi empat set dan satu pasang, tangan itu menang.","Setnya adalah chow (tiga angka berurutan satu jenis), pung (tiga ubin sama), dan kong (empat ubin sama). Set juga bisa dibentuk dengan mengklaim buangan pemain lain, jadi permainan menjadi adu baca panjang tentang apa yang diambil dan apa yang dilepas."],"cap":["Bentuk dasar tangan yang menang: empat set — chow (tiga berurutan satu jenis), pung (tiga sama), atau kong (empat sama) — dan satu pasang"]},{"h":"Mahjong menyeberangi lautan","p":["Pada 1920 Joseph Park Babcock menerbitkan buku aturan berbahasa Inggris, dan sebuah toko di New York mulai mengimpor set dari Tiongkok. Mahjong menjadi demam di Amerika 1920-an, dan National Mah Jongg League yang berdiri pada 1937 menjaga cara bermain ala Amerika.","Mahjong tiba di Jepang pada 1920-an; konon pada 1924 Saburo Hirayama membuka tempat bermain dan sekolah di Tokyo, dan pada 1929 Liga Mahjong Jepang berdiri dengan penulis Kan Kikuchi sebagai ketuanya. Pada 1952, setelah perang, Daizō Amano konon menerbitkan aturan dengan “riichi” di sebuah koran, dan dari situ riichi mahjong Jepang menyebar."],"cap":["Penyebaran mahjong: dari Tiongkok ke AS dan Jepang pada 1920-an; aturan riichi di Jepang pada 1952 dan aturan resmi Tiongkok pada 1998"]},{"h":"Legenda dan sejarah sebenarnya","p":["Asal-usul mahjong punya banyak legenda. Kisah bahwa Konfusius yang menciptakannya tidak berdasar. Kisah tentang seorang pria Ningbo bernama Chen Yumen yang menciptakannya kemungkinan besar juga karangan, karena dokumen yang konon menjadi sumbernya tak pernah ditemukan.","Yang pasti, permainan ambil-dan-buang Tiongkok abad ke-19 dengan kartu uang berubah menjadi permainan ubin. Set-set awal tidak punya bunga maupun naga hijau, melainkan ubin “raja” dan lainnya. Pada 1998 Tiongkok juga menetapkan aturan resmi nasional."],"cap":[]}],"tl":[["pertengahan abad ke-19","Permainan kartu diduga berubah menjadi permainan ubin"],["sekitar 1870","Set tertua yang masih ada (Ningbo, Shanghai, Fuzhou)"],["1920","Babcock menerbitkan buku aturan berbahasa Inggris"],["1929","Liga Mahjong Jepang berdiri"],["1952","“Aturan Hochi” dengan riichi diterbitkan"],["1998","Tiongkok menetapkan aturan resmi nasional"]],"figL":{"hand":["Chow","Pung","Kong","Chow","Pasang"],"spread":[["skt. 1870","Ningbo, Shanghai","Ubin tertua"],["1920","Amerika Serikat","Aturan Babcock, demam"],["1920-an","Jepang","Tiba; liga 1929"],["1952","Jepang","Aturan riichi"],["1998","Tiongkok","Aturan resmi, 81 pola"]]}},"gomoku":{"title":"Gomoku: ketika pemain pertama terlalu kuat","lead":"Gomoku, yang dimainkan dengan papan dan batu go, digemari di Jepang sejak zaman Edo. Untuk meredam keunggulan pemain pertama lahirlah aturan “renju” — dan akhirnya komputer memberi jawabannya.","s":["Gomoku adalah permainan dua orang dengan papan dan batu go. Hitam dan Putih bergantian meletakkan batu, dan yang pertama menjajarkan lima batunya — mendatar, tegak, atau diagonal — menang.","Asal-usulnya tidak jelas. Ada yang mengaitkannya dengan Tiongkok kuno atau Jepang zaman Heian, tetapi catatan pasti berasal dari zaman Edo; konon sudah dimainkan pada pertengahan abad ke-18.","Makin sering dimainkan, makin jelas bahwa Hitam, yang jalan duluan, lebih unggul. Karena itu di Jepang lambat laun dibuat aturan yang memberi “langkah terlarang” hanya kepada Hitam.","Pada 1899 Ruikō Kuroiwa dari surat kabar Yorozu chōhō menamai permainan ini “renju”, yang berarti “mutiara yang dirangkai”.","Pada 1988 Federasi Renju Internasional (RIF) didirikan di Stockholm, Swedia, dan kejuaraan dunia pun digelar. Sementara itu komputer menunjukkan bahwa gomoku tanpa langkah terlarang adalah kemenangan pemain pertama."],"quiz":[["Bagaimana cara menang gomoku?","Menjajarkan lima batu sendiri","Mengepung dan memakan batu","Menguasai lebih dari separuh papan","Memakan lima batu lawan"],["Siapa yang menamai permainan ini “renju”?","Ruikō Kuroiwa","Honinbō Dōsaku","Natsume Sōseki","Fukuzawa Yukichi"],["Dalam renju, langkah apa yang terlarang hanya bagi Hitam?","Tiga ganda, empat ganda, dan deret panjang","Bermain di tepi papan","Bermain di sebelah batu putih","Mengepung batu lawan"]],"kf":["Permainan dengan papan dan batu go: lima sejajar menang; catatan pasti bermula pada zaman Edo","Karena Hitam unggul sebagai pemain pertama, renju melarangnya tiga ganda, empat ganda, dan deret panjang","Pada 1994 terbukti bahwa gomoku bebas di papan 15 × 15 dimenangkan pemain pertama"],"more":[{"h":"Lima sejajar dan empat-tiga","p":["Permainan ditentukan oleh ancaman ganda yang tak bisa ditangkis lawan dalam satu langkah. “Empat” — kurang satu batu menuju lima — harus segera ditutup atau kalah. “Tiga” yang terbuka di kedua ujung, bila dibiarkan, menjadi empat terbuka yang tak bisa dihentikan lagi.","Langkah yang sekaligus membentuk empat dan tiga — “empat-tiga” — memaksa Putih menutup yang empat, lalu yang tiga tumbuh dan menang. Makin pandai bermain gomoku berarti makin cepat melihat bentuk ini datang."],"cap":["Kiri: lima sejajar diagonal menang. Kanan: batu di cincin merah sekaligus membentuk “empat” mendatar (main di 4 jadi lima) dan “tiga” terbuka tegak (titik 3) — Putih tak bisa menutup keduanya (empat-tiga)"]},{"h":"Langkah terlarang hanya bagi Hitam","p":["Dalam renju Hitam tidak boleh membuat tiga ganda, empat ganda, atau deret panjang (enam atau lebih berjajar); melakukannya adalah pelanggaran dan ia kalah. Putih tidak punya langkah terlarang, bahkan enam batu atau lebih berjajar tetap membuatnya menang.","Untuk menang, Hitam harus membangun bentuk seperti empat-tiga yang tidak terlarang. Putih bahkan bisa sengaja menggiring Hitam ke langkah terlarang — adu akal yang membuat renju begitu dalam."],"cap":["Langkah yang terlarang bagi Hitam dalam renju (×). Dari kiri: “tiga ganda” (dua tiga sekaligus), “empat ganda” (dua empat sekaligus), dan “deret panjang” (enam atau lebih)"]},{"h":"Gomoku terpecahkan","p":["Pada 1994 Victor Allis dari Belanda membuktikan dengan komputer bahwa dalam gomoku bebas di papan 15 × 15, pemain pertama, Hitam, selalu bisa menang. Pada 2001 Wágner dan Virág menunjukkan bahwa renju tanpa aturan pembukaan juga dimenangkan pemain pertama.","Orang tetap bermain karena jalur kemenangannya terlalu rumit untuk dihafal. Turnamen memakai “aturan pembukaan” yang mengatur cara memainkan langkah-langkah awal — seperti Yamaguchi atau Soosõrv-8 — agar pertandingan adil."],"cap":["Kisah gomoku dan renju: dari gomoku zaman Edo ke nama renju, federasi internasional, dan pembuktian komputer"]},{"h":"Lima sejajar di seluruh dunia","p":["Pada abad ke-19 permainan ini tiba di Inggris dengan nama “Go Bang”. Kini permainan serupa dimainkan di mana-mana: omok dari Korea, caro dari Vietnam, dan pente, yang memungkinkan batu dimakan berpasangan.","Gomoku di Atlas ini dimainkan di papan 15 × 15 dengan tiga pilihan aturan: renju, standar, dan bebas. Bandingkan dan lihat seberapa besar langkah terlarang renju meredam pemain pertama."],"cap":[]}],"tl":[["pertengahan abad ke-18","Gomoku konon dimainkan di Jepang zaman Edo"],["1856","Buku gomoku tertua yang masih ada, Gomoku Jōseki"],["1899","Ruikō Kuroiwa menamai permainan ini renju"],["1988","Federasi Renju Internasional didirikan di Stockholm"],["1994","Allis membuktikan gomoku bebas dimenangkan pemain pertama"],["2001","Wágner dan Virág: renju tanpa aturan pembukaan dimenangkan pemain pertama"]],"figL":{"time":[["1700-an","Jepang (Edo)","Gomoku dimainkan"],["1899","Jepang","Dinamai “renju”"],["1988","Stockholm","RIF didirikan"],["1994","Belanda","Gomoku: pemain 1 menang"],["2001","Hungaria","Renju: Hitam menang"]]}},"carrom":{"title":"Carrom: sentil masuk lubang","lead":"Di India dan Asia Selatan, keluarga dan tetangga berkumpul untuk bermain carrom. Keping yang disentil dengan jari dikirim ke lubang di empat sudut papan — permainan yang mirip biliar.","s":["Carrom dimainkan di papan licin berukuran sekitar 74 sentimeter persegi. Di tiap sudut ada lubang; dua orang duduk berhadapan, atau empat orang bermain berpasangan.","Ada 19 keping: 9 putih, 9 hitam, dan satu “ratu” merah. Pada gilirannya, pemain meletakkan “striker” yang lebih besar dan berat di garis di depannya — garis dasar — lalu menyentilnya dengan jari ke arah keping.","Pemain yang memasukkan semua keping warnanya menang. Namun ratu merah baru menjadi milikmu bila, setelah memasukkannya, kamu langsung memasukkan satu kepingmu sendiri untuk “menutupnya”.","Carrom konon berasal dari India; di sebuah istana di Patiala, India utara, masih dipajang papan berpermukaan kaca. Pada awal abad ke-20 sudah ada turnamen tingkat negara bagian di India.","Pada 1988 Federasi Carrom Internasional didirikan di Chennai, India, dan kejuaraan dunia diadakan sejak 1991. Permainan sentil serupa ada di seluruh dunia, dari crokinole Kanada hingga novuss Latvia."],"quiz":[["Tanpa striker, berapa keping dalam carrom?","19","16","24","32"],["Bagaimana ratu merah menjadi milikmu?","Langsung memasukkan satu kepingmu (menutupnya)","Memasukkannya paling akhir","Memasukkannya pada pukulan pertama","Mengenainya dua kali berturut-turut"],["Di kota mana Federasi Carrom Internasional didirikan pada 1988?","Chennai","London","Kolombo","Mumbai"]],"kf":["Papan dengan lubang di sudut-sudutnya: striker disentil jari untuk memasukkan keping","9 putih, 9 hitam, dan ratu merah; ratu harus “ditutup” dengan memasukkan kepingmu sesudahnya","Konon berasal dari India; Federasi Internasional 1988, kejuaraan dunia sejak 1991"],"more":[{"h":"Papan dan 19 kepingnya","p":["Setiap sudut papan punya lubang berjaring, dan garis dasar ganda ditarik di sepanjang tiap sisi. Striker diletakkan menyentuh kedua garis, lalu disentil dari situ.","Di awal, ratu diletakkan di tengah papan dan keping putih serta hitam disusun mengelilinginya berbentuk bunga. Pukulan pertama yang memecah bunga itu adalah “break” yang membuka permainan."],"cap":["Papan carrom dan posisi awal. Ratu merah di tengah, keping putih dan hitam mengelilinginya seperti bunga. Lubang di sudut, garis dasar ganda di tiap sisi; striker (cincin biru) diletakkan di garis dasar terdekat"]},{"h":"Sentil dan pantul","p":["Striker biasanya disentil dengan kuku; ada yang memakai jari tengah, telunjuk, atau ibu jari. Bila memasukkan kepingmu, kamu main lagi; bila tidak, giliran lawan.","Bantalannya memantul dengan baik, jadi pantulan dipakai seperti dalam biliar. Memasukkan striker sendiri adalah pelanggaran dan dikenai hukuman."],"cap":["Striker disentil (biru), memantul di bantalan kanan, lalu mengenai keping putih yang meluncur ke lubang kanan atas (merah). Keping yang tak bisa dibidik langsung tetap terjangkau lewat pantulan"]},{"h":"Keluarga permainan sentil","p":["Permainan sentil seperti carrom ada di seluruh dunia. Crokinole dari Kanada membidik lubang di tengah papan bundar, dan pichenotte juga sudah lama dimainkan di Kanada. Carrom sendiri konon tiba di Amerika Utara pada akhir abad ke-19 bersama para misionaris yang pulang dari Asia.","Novuss dari Latvia dan Estonia konon muncul pada 1920-an; kepingnya dipukul dengan stik kecil, bukan jari. Ia menjadi salah satu olahraga terpopuler di Latvia, dan sejak 1993 diadakan kejuaraan internasional."],"cap":["Kerabat carrom yang dimainkan dengan jari atau stik kecil: crokinole dan pichenotte dari Kanada, novuss dari Latvia dan Estonia, serta couronne dari Skandinavia"]},{"h":"Poin dan kejuaraan dunia","p":["Menurut aturan internasional, menutup ratu menambah 3 poin, dan yang lebih dulu mencapai 25 poin menang. Dalam permainan keluarga ada banyak aturan setempat, misalnya ratu bernilai 5 poin.","Turnamen serius konon dimulai di Sri Lanka sekitar 1935, dan pada 1958 India serta Sri Lanka sudah memiliki federasi resmi. Federasi Carrom Internasional (ICF) didirikan di Chennai pada 1988, dan kejuaraan dunia digelar sejak 1991."],"cap":[]}],"tl":[["awal abad ke-20","Turnamen negara bagian di India"],["sekitar 1935","Turnamen serius konon dimulai di Sri Lanka"],["1958","India dan Sri Lanka memiliki federasi resmi"],["1988","Federasi Carrom Internasional didirikan di Chennai"],["1991","Kejuaraan Dunia Carrom pertama"]],"figL":{"family":[["Carrom","India · Asia Selatan"],["Crokinole","Kanada"],["Pichenotte","Kanada"],["Novuss","Latvia · Estonia"],["Couronne","Swedia · Denmark"]]}},"crokinole":{"title":"Mengincar lubang di tengah","lead":"Crokinole sangat digemari di pedesaan Kanada. Cakram disentil dengan jari di atas papan kayu bundar, mengincar lubang kecil di tengah. Papan tertua yang diketahui berasal dari tahun 1876.","s":["Crokinole dimainkan di papan kayu bundar berdiameter sekitar 66 sentimeter. Dua orang duduk berhadapan, atau empat orang bermain berpasangan, menyentil cakram mereka ke arah tengah.","Papan ditandai lingkaran: dari luar ke dalam, cincin bernilai 5, 10, dan 15 poin, dan di tengah lubang kecil bernilai 20. Delapan pasak kayu mengelilingi cincin 15 dan menghalangi jalan lurus.","Sekadar mengincar tengah tidak cukup. Bila ada cakram lawan di papan, tembakanmu harus mengenainya; meleset, cakrammu diangkat.","Papan tertua yang diketahui dibuat pada 1876 di Ontario, Kanada, oleh perajin Eckhardt Wettlaufer — konon sebagai hadiah ulang tahun kelima putranya. Kini papan itu ada di sebuah museum di Kitchener.","Namanya diduga berasal dari kata Prancis croquignole, “sentilan”. Sejak 1999, setiap Juni diadakan kejuaraan dunia di Tavistock, tempat Wettlaufer tinggal."],"quiz":[["Berapa poin lubang di tengah papan crokinole?","20","15","10","50"],["Bila ada cakram lawan di papan, apa yang harus dilakukan tembakanmu?","Mengenai cakram lawan","Masuk ke lubang tengah","Keluar dari papan","Mengenai pasak"],["Kapan dan di mana papan crokinole tertua yang diketahui dibuat?","Kanada, 1876","Prancis, 1776","Amerika Serikat, 1926","Inggris, 1676"]],"kf":["Papan kayu bundar: cakram disentil ke cincin 5, 10, 15 dan lubang 20 di tengah","Bila ada cakram lawan di papan, harus dikenai; meleset, cakrammu diangkat","Papan tertua: Ontario (Kanada), 1876; kejuaraan dunia sejak 1999"],"more":[{"h":"Cincin, pasak, dan parit","p":["Cakram ditembakkan dari cincin terluar bernilai 5, di dalam seperempat bagianmu sendiri. Di luar tepi papan ada parit, tempat cakram yang jatuh atau diangkat berakhir.","Cakram yang masuk ke lubang 20 langsung dikeluarkan dan dihitung 20. Pada akhirnya, cakram yang tersisa di papan bernilai 5, 10, atau 15 sesuai cincinnya, dan biasanya hanya selisih kedua pihak yang dicatat."],"cap":["Papan crokinole: cincin 5, 10, dan 15 dari luar ke dalam, dan lubang 20 di tengah. Delapan pasak menjaga cincin 15, dan parit di sekelilingnya menampung cakram yang diangkat"]},{"h":"Kenai, atau diangkat","p":["Bila ada satu saja cakram lawan di papan, tembakanmu harus mengenai cakram lawan, langsung atau lewat cakram lain. Bila meleset, cakram yang ditembakkan dan cakrammu yang bergeser oleh tembakan itu diangkat.","Bila tak ada cakram lawan, banyak aturan mewajibkan cakram yang ditembakkan berhenti di dalam cincin 15 atau menyentuh garisnya. Jadi tak seorang pun bisa sekadar bersembunyi, dan permainan menjadi duel serangan dan pertahanan."],"cap":["Aturan tembakan. Kiri: bila ada cakram lawan (hitam) di papan, cukup mengenainya dengan cakrammu (merah) (✓). Kanan: bila meleset, cakrammu diangkat dari papan (×)"]},{"h":"Dari papan Ontario ke kejuaraan dunia","p":["Catatan pertama di Kanada konon berasal dari 1867, dan di Amerika Serikat Joshua K. Ingalls mematenkan permainan serupa pada 1880. Kaitan dengan permainan sentil dari Inggris dan Asia Selatan, seperti carrom, juga pernah dikemukakan.","Kadang disebut sebagai permainan kaum Mennonit atau Amish, tetapi itu dianggap salah kaprah tanpa dasar. Meski begitu, kaum Mennonit asal Rusia konon lama memainkannya dengan nama Knipsbrat, “papan sentil”."],"cap":["Crokinole dari masa ke masa: dari catatan pertama di Kanada ke papan Wettlaufer, paten Amerika, dan kejuaraan dunia di Tavistock"]},{"h":"Kejuaraan dan permainan","p":["Kejuaraan dunia diadakan sejak 1999 pada Sabtu pertama bulan Juni di Tavistock. Pada 2009 didirikan asosiasi internasional, dan ada klub di seluruh Amerika Utara dan Eropa.","Crokinole di Atlas ini hanya tersedia dalam 3D, dengan beberapa pilihan tampilan papan. Rasakan sentilan seperti di carrom dan serunya mengincar cincin seperti main dart."],"cap":[]}],"tl":[["1867","Konon catatan pertama di Kanada"],["1876","Wettlaufer membuat papan untuk putranya"],["1880","Di AS, Ingalls mematenkan permainan serupa"],["1999","Kejuaraan dunia dimulai di Tavistock"],["2009","Asosiasi internasional didirikan"]],"figL":{"time":[["1867","Kanada","Catatan pertama"],["1876","Ontario","Papan tertua"],["1880","Amerika Serikat","Paten Ingalls"],["1999","Tavistock","Kejuaraan dunia dimulai"],["2009","Internasional","Asosiasi internasional"]]}},"ugolki":{"title":"Lompat, lompat, sampai ke sudut seberang","lead":"Ugolki dari Rusia, halma dari Amerika, dan “dam Cina” di papan bintang adalah satu keluarga: tidak ada bidak yang dimakan, bidak saling dilompati sampai kedua pasukan bertukar sudut.","s":["Ugolki berarti “sudut-sudut” dalam bahasa Rusia. Putih dan hitam menyusun bidak berbentuk kotak di sudut yang berseberangan pada papan 8×8, dan yang pertama membawa semua bidaknya ke sudut lawan menang.","Dalam satu langkah, bidak maju satu petak ke petak tetangga yang kosong, atau melompati bidak tetangga ke petak kosong tepat di belakangnya. Boleh melompati bidak sendiri maupun bidak lawan, dan terus melompat selama bisa. Tidak ada yang dimakan: bidak yang dilompati tetap di papan.","Permainan jenis ini yang paling terkenal adalah halma dari Amerika. Konon permainan ini dirancang sekitar 1883–84 oleh ahli bedah George Howard Monks, dari beberapa gagasan permainan Inggris bernama Hoppity. Namanya berasal dari kata Yunani untuk “lompatan”.","Pada 1892 muncul di Jerman versi dengan papan bintang, “Stern-Halma” (halma bintang). Pada 1928 perusahaan Amerika Pressman menjualnya dengan nama “Chinese checkers” (dam Cina), dan permainan ini menjadi demam; padahal permainan ini sama sekali tidak berasal dari Cina.","Tidak ada yang tahu pasti kapan ugolki lahir. Menurut satu cerita, ugolki diciptakan di Eropa pada akhir abad ke-18, tetapi tidak ditemukan catatan yang pasti. Kini anak-anak dan orang dewasa memainkannya di Rusia dan negara-negara bekas Uni Soviet."],"quiz":[["Dalam ugolki, apa yang terjadi pada bidak yang dilompati?","Tetap di papan","Diangkat dari papan","Berganti warna","Kembali ke sudutnya"],["Kapan permainan ini pertama dijual sebagai “dam Cina”?","1928, di AS","1892, di Cina","abad ke-18, di Cina zaman Qing","1950-an, di Jepang"],["Siapa yang konon menciptakan halma?","Monks, ahli bedah Amerika","sebuah pabrik mainan Jerman","seorang matematikawan Rusia","seorang kaisar Cina"]],"kf":["Dari sudut ke sudut di papan 8×8: yang lebih dulu memindahkan semua bidak menang. Tidak ada yang dimakan","Satu langkah, atau lompat atas bidak tetangga — milik sendiri atau lawan — dan boleh terus melompat","Halma (AS, sekitar 1883–84) → Stern-Halma (Jerman, 1892) → “dam Cina” (1928). Bukan dari Cina"],"more":[{"h":"Maju dengan melompat","p":["Saat melompat, tidak penting milik siapa bidaknya. Susun bidakmu seperti “tangga”, pakai juga bidak lawan sebagai pijakan, dan satu langkah bisa menyeberangi setengah papan.","Melompat tidak pernah wajib, dan boleh berhenti di tengah jalan. Tetapi satu langkah biasa dan lompatan tidak boleh digabung dalam satu giliran."],"cap":["Rangkaian lompatan: bidak putih melompati bidak hitam, putih, hitam, lalu putih, empat lompatan dalam satu langkah (1–4). Semua bidak yang dilompati tetap di papan"]},{"h":"Papan dan kubu ugolki","p":["Kubu ada beberapa ukuran: 3×3 (9 bidak), 3×4 (12), dan 4×4 (16). Dalam aturan klasik bidak hanya bergerak lurus, menurut baris dan kolom; ada varian yang juga membolehkan gerak diagonal.","Kalau seseorang diam saja di kubunya sendiri, lawan tidak akan pernah bisa mengisinya. Karena itu, menurut aturan yang lazim di Rusia, pemain yang masih punya bidak di kubunya sendiri setelah langkah ke-40 kalah. Jika sampai langkah ke-80 belum ada keputusan, jumlah bidak di kubu lawan yang menentukan."],"cap":["Papan ugolki: putih mulai dari kubu 3×4 di kiri bawah (a1–d3), hitam di kanan atas (e6–h8), dan masing-masing menuju sudut lawan (panah). Kubu juga bisa 3×3 atau 4×4"]},{"h":"Keluarga halma","p":["Halma dimainkan di papan 16×16, dengan 19 bidak per orang untuk dua pemain atau 13 untuk empat pemain, yang bergerak ke delapan arah. Monks mendapat paten Amerika pada 1888. Konon matematikawan Thomas Hill, yang kemudian menjadi rektor Harvard, yang memberinya nama.","Papan bintang punya 121 lubang; biasanya tiap pemain punya 10 bidak, dan bisa dimainkan berdua, bertiga, berempat, atau berenam. Di Cina disebut tiaoqi, “catur lompat”, dan di Jepang permainan serupa dikenal sebagai “permainan berlian”. Di sini pun, lawan yang diam di sudut tujuanmu bisa menghalangimu mengisinya."],"cap":["Keluarga permainan lompat dan tukar sudut: halma di papan 16×16, Stern-Halma dan “dam Cina” di papan bintang, ugolki di papan 8×8"]},{"h":"Cobalah","p":["Aturan ugolki bisa dipelajari dalam semenit. Tetapi membangun tangga panjang dengan bidak lawan juga, tanpa menyisakan pijakan baginya, menjadi adu hitungan yang dalam.","Di Atlas ini kamu bisa memainkan ugolki dengan kubu 3×3, 3×4, atau 4×4, atau dengan gerak diagonal. Papan 3D-nya dari porselen putih dan biru kobalt, seperti keramik Gzhel dari Rusia."],"cap":[]}],"tl":[["1883","Halma lahir (sekitar 1883–84, AS)"],["1888","Monks mendapat paten AS untuk halma"],["1892","Stern-Halma di papan bintang, di Jerman"],["1928","Dijual sebagai “dam Cina” di AS"],["1941","Milton Bradley memperoleh hak atas nama itu"]],"figL":{"fam":[["sekitar 1883–84","Halma","AS · papan 16×16"],["1892","Stern-Halma","Jerman · papan bintang"],["1928","Dam Cina","nama baru di AS"],["tak diketahui","Ugolki","Rusia · papan 8×8"]]}},"agon":{"title":"Ratu ke takhta, pengawal di sekelilingnya","lead":"Agon dimainkan di Inggris zaman Victoria pada papan berpetak segi enam. Dudukkan ratumu di takhta di tengah dan kelilingi dengan enam pengawalmu, maka kamu menang.","s":["Agon adalah permainan untuk dua orang, disebut juga “Pengawal Ratu”. Namanya berasal dari kata Yunani untuk “pertandingan”. Papannya terdiri dari 91 petak segi enam, dan petak di tengah adalah takhta.","Lima cincin mengelilingi takhta, masing-masing berbeda warna dengan cincin berikutnya. Tiap pemain punya satu ratu dan enam pengawal; yang menang adalah yang mendudukkan ratunya di takhta dan mengisi enam petak di sekelilingnya dengan pengawalnya.","Bidak bergerak satu petak setiap kali, di sepanjang cincin yang sama atau ke cincin sebelah dalam. Bidak tidak pernah boleh keluar: sekali masuk, tak bisa kembali. Hanya ratu yang boleh masuk ke takhta.","Catatan tertua yang diketahui adalah aturan yang diterbitkan di London pada 1842. Permainan ini dikaitkan dengan Anthony Peacock dari London, dan dinikmati di rumah-rumah zaman Victoria.","Agon sering disebut permainan papan tertua yang diketahui dengan petak segi enam. Satu cerita mengatakan permainan ini lahir di Prancis abad ke-18, tetapi papan-papan tua yang dijadikan bukti dianggap tambahan dari masa kemudian, jadi belum pasti."],"quiz":[["Bagaimana cara menang dalam agon?","Ratu di takhta, dikelilingi enam pengawalmu","Menangkap ratu lawan","Menjajarkan semua bidak di tepi","Mengelilingi takhta yang kosong"],["Ke arah mana bidak agon tidak pernah boleh bergerak?","Ke cincin luar","Di sepanjang cincin yang sama","Ke cincin dalam","Ke takhta (jika ratu)"],["Kapan dan di mana aturan agon pertama kali diterbitkan?","London, 1842","Paris, 1742","Berlin, 1892","New York, 1942"]],"kf":["91 petak segi enam: takhta di tengah dan lima cincin di sekelilingnya","Satu langkah di cincin yang sama atau ke dalam, tak pernah keluar. Hanya ratu yang menempati takhta","Terbit di London pada 1842; sering disebut permainan papan segi enam tertua"],"more":[{"h":"Papan takhta dan cincin","p":["Pada awal standar, ratu dan pengawal kedua pemain berselang-seling di cincin terluar. Dalam aturan 1842, ratu mulai di sudut yang berseberangan dan pengawal diletakkan satu per satu secara bergiliran.","Papannya seperti papan sasaran, cincin berwarna mengelilingi takhta. Sekilas terlihat di cincin mana sebuah bidak berada, sehingga mudah menghitung berapa langkah lagi menuju takhta."],"cap":["Papan agon dan susunan awal. Petak hijau di tengah adalah takhta, dikelilingi lima cincin merah dan gading berselang-seling. Ratu (mahkota) dan enam pengawal tiap pihak berselang-seling di tepi"]},{"h":"Ke dalam, terus ke dalam","p":["Setiap giliran, satu bidak melangkah ke petak tetangga yang kosong, mengitari cincin yang sama atau ke dalam.","Bidak tidak boleh masuk ke petak yang diapit dua bidak lawan. Karena itu, dinding bidak musuh adalah penghalang nyata di jalan menuju pusat."],"cap":["Cara bergerak. Pengawal putih boleh melangkah di cincinnya atau ke cincin dalam (hijau), tetapi tidak kembali keluar (× merah)"]},{"h":"Diapit, lalu diusir keluar","p":["Apit bidak lawan dalam garis lurus di antara dua bidakmu, maka bidak itu tertangkap. Pemiliknya harus memakai giliran berikutnya untuk menaruh pengawal yang tertangkap di petak kosong cincin terluar.","Ratu yang tertangkap kembali ke petak kosong mana saja kecuali takhta, dan dipindah lebih dulu. Semua langkah yang susah payah diraih hilang, jadi pertahanan sangat penting. Rincian aturannya sedikit berbeda dari buku ke buku."],"cap":["Penangkapan. (1) Pengawal putih maju dan mengapit pengawal hitam dalam satu garis di antara dua bidak putih. (2) Pada giliran berikut pemiliknya, pengawal hitam yang tertangkap dipindah ke petak kosong di tepi"]},{"h":"Cobalah","p":["Jika enam pengawalmu mengelilingi takhta saat takhta kosong, kamu langsung kalah. Kirim ratu lebih dulu, atau buka jalan dengan pengawal? Urutan langkah menentukan permainan.","Di Atlas ini kamu bisa memainkan agon dengan awal standar di tepi atau awal 1842 yang meletakkan pengawal satu per satu. Papan 3D-nya dari kayu mahoni ala Victoria bergaris emas, dengan bidak dari tulang dan eboni."],"cap":[]}],"tl":[["akhir abad ke-18","Cerita tentang asal Prancis (tanpa bukti kuat)"],["1842","Aturan “Agon, or the Queen’s Guards” terbit di London"],["abad ke-19","Populer di Inggris zaman Victoria; papan dijual Jaques dan lainnya"],["1999","Dibahas dalam Oxford History of Board Games karya Parlett"],["kini","Masuk ke Ludii, sistem untuk meneliti permainan"]]},"dots":{"title":"Titik, garis, dan keping yang jatuh — permainan yang terpecahkan","lead":"Dots and Boxes dengan pensil dan kertas, dan Connect Four dengan menjatuhkan keping: dua permainan yang bisa dimainkan anak-anak, yang dipecahkan dengan serius oleh matematikawan dan komputer.","s":["Dots and Boxes dimainkan di kertas berisi kisi titik. Bergiliran, pemain menghubungkan dua titik bertetangga dengan garis; yang menggambar sisi keempat sebuah persegi mengambil kotak itu dan menggambar satu garis lagi. Kotak terbanyak menang.","Permainan ini diperkenalkan dengan nama “La Pipopipette” oleh matematikawan Prancis Édouard Lucas, menurut kebanyakan sumber pada 1889. Setelah ia wafat, permainan ini juga dimuat dalam bukunya L’Arithmétique amusante (1895).","Connect Four dimainkan dengan menjatuhkan keping ke bingkai tegak berisi 7 kolom dan 6 baris. Keping jatuh ke lubang kosong paling bawah, dan empat keping sewarna berderet — mendatar, tegak, atau miring — menang. Perusahaan Amerika Milton Bradley mulai menjualnya pada 1974.","Pada Oktober 1988, Connect Four “dipecahkan”. Pada tanggal 1 James Dow Allen, dan tanggal 16 Victor Allis, masing-masing secara terpisah, menunjukkan bahwa pemain pertama selalu bisa menang jika mulai di kolom tengah.","Untuk Dots and Boxes pun, matematikawan Elwyn Berlekamp dan kawan-kawan membangun teori “rantai panjang”, yang dihimpun dalam buku pada 2000. Di balik permainan yang bisa dimainkan siapa saja, tersimpan matematika yang dalam."],"quiz":[["Dalam Dots and Boxes, apa yang dilakukan pemain yang menggambar sisi keempat kotak?","Mengambil kotak dan menggambar lagi","Giliran pindah","Memberikan kotak ke lawan","Permainan berakhir"],["Dalam Connect Four, langkah pertama mana yang memastikan pemain pertama menang?","Kolom tengah","Kolom paling kiri","Kolom paling kanan","Kolom mana saja"],["Siapa yang secara terpisah memecahkan Connect Four pada 1988?","Allen dan Allis","Lucas dan Berlekamp","Wexler dan Strongin","Conway dan Guy"]],"kf":["Dots and Boxes: tutup kotak, ambil, gambar lagi. Yang pertama membuka rantai panjang biasanya kalah","Connect Four: 7 kolom × 6 baris, keping jatuh ke bawah. Dijual sejak 1974","Dipecahkan Allen dan Allis secara terpisah pada 1988: pemain pertama menang dari tengah"],"more":[{"h":"Rantai panjang dan silang ganda","p":["Membuka “rantai” kotak yang bersambung berarti lawan bisa mengambil semuanya. Karena itu akhir permainan menjadi perebutan siapa yang terpaksa membuka rantai panjang lebih dulu. Yang pertama membuka rantai panjang biasanya kalah.","Pemain yang mengambil rantai bisa sengaja menyisakan dua kotak terakhir untuk lawan (silang ganda). Rugi dua kotak, tetapi lawan harus membuka rantai berikutnya, dan rantai-rantai besar yang tersisa jadi milikmu."],"cap":["Pertarungan rantai panjang. (1) B membuka rantai lima kotak. A mengambil tiga, lalu alih-alih dua terakhir, menggambar garis ujung (2) dan menyerahkannya. (3) B mengambil keduanya dengan satu garis, tetapi harus menggambar lagi — dan membuka rantai berikutnya"]},{"h":"Keping jatuh, baris ganjil dan genap","p":["Keping tak bisa diletakkan sesuka hati: kolom terisi dari bawah. Jadi lubang kemenangan tak berguna selama lubang di bawahnya masih kosong — dan yang lebih dulu mengisi lubang itu menyerahkan kemenangan kepada lawan.","Saat bingkai makin penuh, jumlah “lubang yang tak ingin diisi siapa pun” menentukan hasil. Menurut analisis Allis, ancaman di baris ganjil kuat bagi pemain pertama, dan di baris genap bagi pemain kedua."],"cap":["Bingkai Connect Four. Keping yang dimasukkan dari atas jatuh ke lubang kosong paling bawah. Merah punya ancaman di baris ketiga, baris ganjil (garis putus merah). Siapa pun yang mengisi lubang di bawahnya (×) menyerahkan kemenangan kepada merah"]},{"h":"Linimasa permainan yang terpecahkan","p":["Connect Four dikaitkan dengan orang Amerika Howard Wexler dan Ned Strongin. Permainan serupa juga disebut “kekasih sang kapten”, dari cerita bahwa Kapten Cook berjam-jam memainkannya di kabinnya — tetapi tak ada bukti kuat untuk cerita itu.","Menurut analisis Allen dan Allis, pemain pertama yang mulai di tengah menang paling lambat pada langkah ke-41; mulai di kolom sebelahnya berakhir seri, dan mulai di salah satu dari empat kolom luar membuat pemain kedua menang. Teori Dots and Boxes dibahas panjang dalam Winning Ways (1982)."],"cap":["Langkah-langkah menuju permainan yang terpecahkan: pipopipette karya Lucas, Connect Four mulai dijual, tahun dipecahkannya, dan buku Berlekamp"]},{"h":"Cobalah","p":["Tahu jawabannya adalah satu hal; bermain melawan orang adalah hal lain sama sekali. Menghitung rantai, menghitung baris ganjil dan genap, selangkah di depan lawan — keseruannya tetap sama.","Atlas ini punya Dots and Boxes dan Connect Four. Gambarlah garis di buku tulis atau papan tulis batu, jatuhkan keping ke bingkai kulit atau es, dan intiplah apa yang dilihat para matematikawan."],"cap":[]}],"tl":[["1889","Lucas memperkenalkan “La Pipopipette” (menurut kebanyakan sumber)"],["1974","Milton Bradley mulai menjual Connect Four"],["1982","Winning Ways menganalisis Dots and Boxes"],["1988","Allen dan Allis memecahkan Connect Four secara terpisah"],["2000","Buku Berlekamp The Dots and Boxes Game"]],"figL":{"time":[["1889","La Pipopipette","Lucas · Prancis"],["1974","Connect Four","Milton Bradley"],["1988","Connect Four terpecahkan","Allen & Allis · pemain 1 menang"],["2000","Buku Dots and Boxes","Berlekamp"]]}},"hitblow":{"title":"Temukan empat yang tersembunyi — keluarga Hit & Blow","lead":"Menebak empat warna atau angka tersembunyi hanya dengan petunjuk “tepat” dan “hampir tepat”. Permainan ini tumbuh dari hiburan kertas-pensil menjadi pasak berwarna Mastermind, lalu masuk ke ilmu komputer.","s":["Dalam Hit & Blow, seorang pemain diam-diam menyusun empat warna atau angka. Setiap tebakan pemain lain hanya dijawab berapa yang benar warna dan letaknya (hit) dan berapa yang benar warnanya tetapi salah letak (blow).","Asalnya permainan angka dengan kertas dan pensil, “Bulls and Cows” (banteng dan sapi): yang tepat disebut banteng, yang hampir tepat disebut sapi. Kadang dikatakan usianya sudah seabad, tetapi asal-usul sebenarnya tidak diketahui.","Pada 1970, Mordecai Meirowitz, kepala kantor pos dan ahli telekomunikasi asal Israel, menjadikannya permainan papan dengan pasak berwarna. Invicta Plastics di dekat Leicester, Inggris, membeli haknya dan meluncurkannya sebagai Mastermind pada 1971–72, lalu permainan ini mendunia.","Pada masa yang sama, komputer pun bermain tebak angka. Sebelum 1970, versi bernama MOO ditulis untuk komputer Titan di Universitas Cambridge, dan pada 1972 dipindahkan ke Multics di MIT, Amerika Serikat.","Pada 1976–77, ilmuwan komputer Donald Knuth menunjukkan bahwa dalam Mastermind 6 warna dan 4 lubang (1.296 kode seluruhnya), tebakan yang tepat selalu menemukan kode dalam paling banyak lima kali."],"quiz":[["Jika warna tebakan berada di tempat yang sama dengan kode, disebut apa?","Hit (tepat)","Blow (hampir tepat)","Meleset","Pasangan"],["Siapa yang menciptakan Mastermind dengan pasak berwarnanya?","Meirowitz dari Israel","Knuth dari AS","kantor pos Inggris","mahasiswa Cambridge"],["Menurut Knuth, berapa tebakan selalu cukup untuk Mastermind 6 warna dan 4 lubang?","Paling banyak lima","Paling banyak tiga","Paling banyak delapan","Paling banyak sepuluh"]],"kf":["Hit: warna dan letak benar; blow: warna benar, letak salah. Tak pernah diberi tahu yang mana","Bulls and Cows di kertas → pasak berwarna Meirowitz 1970 → Mastermind 1971–72","Knuth (1976–77): 1.296 kode dari 6 warna × 4 lubang ditemukan paling banyak dalam lima tebakan"],"more":[{"h":"Hit dan blow","p":["Pasak jawaban tak pernah memberi tahu letak mana yang hit — hanya bahwa ada “satu hit dan dua blow”. Karena itu jawaban dari tebakan ke tebakan digabungkan untuk mempersempit kode.","Mengulang tebakan tidak memberi apa-apa. Biasanya dipilih susunan yang cocok dengan semua jawaban, tetapi kadang tebakan yang mustahil menjadi kode justru mengumpulkan lebih banyak informasi dan mempersingkat jalan."],"cap":["Satu tebakan dan jawabannya. Di atas kode tersembunyi, di bawah tebakan. Yang paling kiri benar warna dan letaknya: hit (pasak merah muda). Yang kedua dan keempat warnanya ada di kode tetapi salah letak: blow (pasak putih). Yang ketiga tidak ada (×)"]},{"h":"Setiap jawaban mempersempit kemungkinan","p":["Metode Knuth setiap kali memilih tebakan yang menyisakan kode paling sedikit meskipun jawaban terburuk yang datang. Langkah pertamanya memakai dua warna masing-masing dua kali.","Penelitian kemudian juga menemukan metode dengan rata-rata terendah: pada 1993 Koyama dan Lai menunjukkan rata-rata sekitar 4,34 tebakan (enam dalam kasus terburuk). Bulls and Cows dengan empat angka berbeda selalu bisa dipecahkan dalam tujuh tebakan."],"cap":["Satu kode yang ditemukan dengan metode Knuth. 1.296 kode dari 6 warna × 4 lubang turun menjadi 256 setelah tebakan pertama, 41 setelah kedua, 6 setelah ketiga, dan 1 setelah keempat; tebakan kelima tepat (batang dalam skala logaritma)"]},{"h":"Dari angka ke warna","p":["Mastermind punya banyak kerabat, di antaranya Super Mastermind dengan 8 warna dan 5 lubang (1972) dan Word Mastermind, tempat orang menebak huruf.","Di Jepang, permainan tebak angka dikenal sebagai “Hit & Blow” dan pernah muncul di televisi serta di kumpulan permainan untuk konsol."],"cap":["Keluarga ini dari masa ke masa: Bulls and Cows di kertas, MOO di komputer Cambridge, Mastermind karya Meirowitz, dan “lima” dari Knuth"]},{"h":"Cobalah","p":["Saat terbaik adalah ketika, sambil membandingkan baris-baris petunjuk, kamu sadar: “warna ini hanya bisa di sini”. Jika setiap tebakan memangkas kemungkinan setengah atau lebih, kamu bermain seperti master.","Hit & Blow di Atlas ini punya lima jenis — 4 dari 6 warna tanpa pengulangan (360 kode), dengan pengulangan (1.296 milik Knuth), 3 atau 4 angka, dan permainan ahli 5 dari 8 warna — ditambah soal harian."],"cap":[]}],"tl":[["1970","MOO di komputer Cambridge; Meirowitz merancang papan pasak"],["1971","Invicta Plastics membeli hak dan meluncurkan Mastermind"],["1972","MOO pindah ke Multics di MIT; Super Mastermind"],["1977","Knuth: “paling banyak lima” (makalah 1976–77)"],["1993","Koyama dan Lai: metode dengan rata-rata sekitar 4,34"]],"figL":{"time":[["?","Bulls and Cows","angka di kertas"],["1970","MOO","komputer Cambridge"],["1971","Mastermind","Meirowitz · Invicta"],["1977","Selalu dalam lima","bukti Knuth"]]}},"botao":{"title":"Sepak bola dengan kancing mantel","lead":"Futebol de botão dari Brasil adalah sepak bola meja: kancing disentil untuk membawa bola mungil ke gawang. Permainan kantong anak-anak ini menjadi olahraga yang diakui negara.","s":["Futebol de botão berarti “sepak bola kancing”. Di lapangan sepanjang sekitar 167 cm, tiap tim memasang sepuluh kancing bundar dan satu balok persegi sebagai kiper, lalu menyentil kancing untuk membawa bola flanel berdiameter 1 cm ke gawang lawan.","Konon permainan ini bermula pada awal abad ke-20, ketika anak-anak di Brasil dan Hungaria mencopot kancing mantel dan kemeja untuk bermain. Di Hungaria permainan ini masih disebut gombfoci, “sepak bola kancing”.","Di Brasil, permainan ini ditata oleh Geraldo Décourt, seniman dari Rio de Janeiro. Pada 1930 (1929 menurut beberapa sumber) ia menerbitkan buku aturan pertama dan menamai permainan itu “Foot-Ball Celotex”, menurut lapisan papan tempat bermain.","Pada 1962 berdiri federasi negara bagian São Paulo, dan pada 1988 Dewan Olahraga Nasional Brasil mengakui “futebol de mesa” (sepak bola meja) sebagai olahraga resmi. Hari ulang tahun Décourt, 14 Februari, adalah Hari Pemain Kancing di negara bagian São Paulo.","Negara lain juga punya sepak bola sentil. Di Inggris, permainan sejenis lahir di Liverpool pada 1929, dan pada 1947 muncul sepak bola meja yang menyentil figur kecil dengan jari; sepak bola meja dengan figur di batang sudah dipatenkan sejak 1920-an."],"quiz":[["Satu tim futebol de botão terdiri dari apa?","Sepuluh kancing dan seorang kiper","Sebelas kancing","Lima kancing dan seorang kiper","Sebelas figur"],["Kapan diakui sebagai olahraga resmi di Brasil?","1988","1930","1962","2001"],["Dalam sepak bola meja yang lahir di Inggris pada 1947, apa yang disentil dengan jari?","Figur pemain berpemberat","Kancing mantel","Tutup botol","Koin"]],"kf":["Sepak bola meja dengan sepuluh kancing dan balok kiper, disentil untuk membawa bola flanel","Permainan anak awal 1900-an → buku aturan Décourt 1930 → olahraga resmi di Brasil 1988","Kerabat: gombfoci Hungaria, sepak bola sentil dari Inggris (1929 dan 1947), serta sepak bola meja berbatang"],"more":[{"h":"Sentil, umumkan, tembak","p":["Kancing bisa disentil dengan jari, tetapi banyak pemain menekan tepinya dengan alat pipih bernama palheta agar meluncur. Kancing itu sendiri yang harus mengenai bola.","Dalam aturan 12 sentuhan, tembakan harus diumumkan dengan suara keras dan ditunggu sampai lawan memasang kipernya. Gol tanpa pengumuman tidak sah."],"cap":["Cara menyentil kancing. (1) Tepi kancing ditekan dengan alat pipih, kancing meluncur dan mengenai bola. (2) Bola lewat di samping kiper (balok biru) dan masuk gawang"]},{"h":"Aturan yang berubah dengan jumlah sentuhan","p":["Brasil punya aturan tradisional dari berbagai daerah: gaya Bahia, satu sentuhan dengan cakram; gaya Rio, tiga sentuhan dengan bola; dan gaya São Paulo, dua belas sentuhan dengan bola.","Dengan dua belas sentuhan, satu penguasaan boleh disentil hingga dua belas kali, dan kancing yang sama hingga tiga kali berturut-turut. Makin sedikit sentuhan, makin sedikit gol; permainan satu sentuhan, yang bergantian setiap sentilan, dianggap untuk para ahli."],"cap":["Satu tim berisi sepuluh kancing dan kiper persegi. Tiga aturan klasik Brasil berbeda dalam berapa sentilan (sentuhan) yang boleh dalam satu penguasaan"]},{"h":"Keluarga sepak bola sentil","p":["Sepak bola meja Inggris tahun 1947, yang menyentil figur dengan jari, konon mencontoh permainan sejenis yang lahir di Liverpool pada 1929. Figur pemain kecil berpemberat disentil untuk menggiring bola.","Sepak bola meja, tempat deretan figur di batang diputar untuk menendang bola, dipatenkan di Inggris pada 1921, dan di Spanyol Alejandro Finisterre mematenkan futbolín miliknya pada 1937."],"cap":["Keluarga sepak bola meja sentil: gombfoci Hungaria, dua permainan sentil dari Inggris, serta sepak bola meja dengan figur di batang"]},{"h":"Cobalah","p":["Alirkan bola dengan umpan ke depan gawang, umumkan tembakan, bidik celah di samping kiper: kekuatan dan sudut satu tekanan menentukan pertandingan.","Futebol de botão di Atlas ini adalah permainan khusus 3D berdasarkan aturan 12 sentuhan. Kamu bisa memilih pertandingan menurut jumlah langkah, jumlah gol, atau adu penalti, serta lapangan rumput, kayu, dan lainnya."],"cap":[]}],"tl":[["awal abad ke-20","Anak-anak di Hungaria dan Brasil bermain dengan kancing"],["1930","Buku aturan pertama Décourt (1929 menurut beberapa sumber)"],["1947","Sepak bola meja dengan figur yang disentil lahir di Inggris"],["1962","Federasi negara bagian São Paulo didirikan"],["1988","Diakui sebagai olahraga resmi di Brasil"]],"figL":{"rules":[["1","Bahia\ncakram"],["3","Rio\nbola"],["12","São Paulo\nbola"]],"family":[["Futebol de botão","Brasil · buku aturan 1930"],["Gombfoci","Hungaria · kancing mantel"],["Permainan Liverpool","Inggris · 1929 · sejenis"],["Sepak bola figur","Inggris · 1947 · disentil jari"],["Sepak bola meja","figur di batang · paten 1921"]]}},"hockey":{"title":"Dari papan buatan rumah ke gelanggang udara","lead":"Hoki meja ada dua jenis: hoki batang, tempat batang-batang menggerakkan pemain, dan hoki udara, tempat keping yang melayang di atas udara dipukul bolak-balik. Inilah kisah sebuah papan buatan rumah dari Kanada dan para insinyur Amerika.","s":["Hoki meja adalah hoki di gelanggang kecil di atas meja. Secara garis besar ada dua jenis: hoki batang, tempat batang di bawah papan menggerakkan figur pemain kecil, dan hoki udara, tempat keping melayang di atas bantalan udara dan dipukul dengan pemukul.","Hoki meja pertama konon dibuat di Toronto, Kanada, pada 1932 oleh Donald Munro. Karena uang untuk Natal kurang di masa Depresi, ia membuat papan untuk anak-anaknya dari sisa kayu, kawat, dan pegas jam. Papan itu dijual di sebuah toserba di Toronto dan laris.","Dalam hoki batang, figur berdiri di celah yang dibuat pada papan dan tersambung ke batang di bawahnya. Dorong atau tarik batang, pemain meluncur sepanjang celah; putar batang, pemain mengayunkan stiknya. Kemudian permainan ini populer di negara-negara Nordik dan tempat lain, dengan federasi internasional dan kejuaraan dunia.","Pada 1969, para insinyur perusahaan Amerika Brunswick mulai mengerjakan permainan di permukaan dengan gesekan kecil. Bob Lemieux menghidupkan lagi proyek yang sempat terhenti, dan lahirlah “hoki udara” dengan keping tipis, dua pemukul, dan gawang berbentuk celah; permainan ini dijual pada awal 1970-an.","Membuat benda melayang di atas meja udara adalah gagasan yang lebih tua, dipakai untuk memindahkan beban berat dan untuk alat fisika di sekolah. Hoki udara laris: pada pertengahan 1970-an sudah ada turnamen di Amerika Serikat, dan pada 1978 kejuaraan dunia dimulai."],"quiz":[["Di mana hoki meja pertama konon dibuat?","Toronto, 1932","Chicago, 1972","Stockholm, 1900","Tokyo, 1950"],["Mengapa keping hoki udara terus meluncur?","Melayang di atas udara dari lubang-lubang kecil di meja","Terbuat dari es","Mejanya miring","Ada roda di bawahnya"],["Bagaimana menggerakkan pemain dalam hoki batang?","Mendorong, menarik, dan memutar batang di bawah papan","Menyentilnya dengan jari","Dengan magnet","Dengan tali"]],"kf":["Hoki batang: dorong, tarik, dan putar batang di bawah papan untuk menggerakkan pemain di celahnya","Hoki udara: udara dari lubang membuat keping melayang, lalu dipukul dengan pemukul","Papan buatan rumah di Toronto 1932 → riset sejak 1969 → hoki udara awal 1970-an"],"more":[{"h":"Pemain di dalam celah","p":["Karena tiap orang mengendalikan beberapa pemain, berpindah batang dengan cepat adalah kuncinya. Rencana dasarnya: mengoper dan membidik sisi yang berlawanan dengan kiper.","Konon papan pertama Munro lebih tinggi di tengah dan menurun ke tiap ujung, dengan tuas untuk kiper dan pelontar untuk pemain lain. Batang putar seperti sekarang baru menyebar kemudian."],"cap":["Papan hoki batang. Setiap pemain berdiri di celah dan digerakkan batang di bawah papan: (1) mendorong atau menarik batang membuatnya meluncur sepanjang celah; (2) memutarnya membuat stik terayun (garis putus-putus adalah batang di bawah papan)"]},{"h":"Keping yang melayang di atas udara","p":["Nyaris tanpa gesekan, keping memantul di dinding berulang-ulang. Tembakan pantul, yang mengubah sudut di dinding, adalah teknik dasar; yang bertahan bergerak cepat ke sudut-sudut gawang, membentuk segitiga.","Meja turnamen panjangnya 8 kaki (sekitar 2,4 m). Pemukulnya juga disebut dayung atau striker, dan kepingnya dari plastik keras."],"cap":["Meja hoki udara. Udara berembus dari lubang-lubang kecil yang tak terhitung (panah di kiri), keping sedikit melayang dan meluncur tanpa henti. Dipukul pemukul merah, keping memantul di dinding kanan dan melewati pemukul biru yang menjaga tengah gawang (garis putus)"]},{"h":"Hoki meja dari masa ke masa","p":["Pada 1980-an, meja hoki batang di bawah kubah transparan populer di pusat permainan. Sepak bola meja, dengan figur di batang yang menendang bola, termasuk keluarga “digerakkan batang” yang sama.","Di Jepang pun hoki udara menjadi andalan pusat permainan sekitar 1980-an, dan ada meja kecil untuk di rumah."],"cap":["Hoki meja dari masa ke masa: hoki batang di Toronto 1932, riset meja udara sejak 1969, hoki udara awal 1970-an, dan kejuaraan dunia sejak 1978"]},{"h":"Cobalah","p":["Bertahan, manfaatkan dinding, selinap lewat celah di samping pemukul lawan: mata yang membaca keping cepat dan tangan yang gesit menentukan pertandingan.","Hoki meja di Atlas ini khusus 3D, dengan enam meja termasuk gelanggang flanel kecil dan meja udara. Gunakan tembakan tepi — pukulan menyerempet dengan pinggir pemukul — untuk menjebol gawang lawan."],"cap":[]}],"tl":[["1932","Munro membuat hoki meja di Toronto"],["1969","Riset permainan di meja udara dimulai di AS"],["1972","Hoki udara mulai dijual (awal 1970-an)"],["1975","Asosiasi hoki udara berdiri di AS"],["1978","Kejuaraan dunia hoki udara dimulai"]],"figL":{"time":[["1932","Hoki batang","Toronto · buatan rumah"],["1969","Riset meja udara","para insinyur Amerika"],["1972","Hoki udara","diluncurkan Brunswick"],["1978","Kejuaraan dunia","turnamen hoki udara"]]}},"solitaire":{"title":"Patience: kartu untuk seorang diri","lead":"Solitaire, permainan kartu untuk satu orang, di Inggris disebut “patience” (kesabaran). Dari buku Jerman abad ke-18 hingga layar komputer, inilah kisah kartu yang dimainkan sendirian.","s":["Solitaire adalah sebutan untuk permainan kartu satu orang. Kartu disusun dalam pola tertentu, dipindahkan menurut aturan, dan kamu menang jika setiap jenis tersusun dari As sampai Raja. Di Inggris disebut “patience”; di Amerika Utara nama “solitaire” menyebar pada abad ke-20.","Uraian tertua yang diketahui ada dalam edisi 1783 sebuah buku permainan Jerman, dengan nama “Patience”. Permainan ini kemungkinan lahir di Jerman atau Skandinavia, dan ada dugaan kaitannya dengan susunan kartu ramalan yang menyebar sedikit lebih awal. Dalam bahasa Denmark dan Norwegia disebut kabal.","Pada awal abad ke-19 permainan ini populer di Prancis, lalu sampai ke Inggris dan Amerika pada paruh kedua abad itu. Pada 1826 terbit di Rusia buku yang khusus membahasnya. Dalam bahasa Inggris, Illustrated Games of Patience karya Lady Adelaide Cadogan dari sekitar 1870 cukup terkenal.","Yang paling terkenal, Klondike, dimainkan dengan tujuh tumpukan. Catatan tertua aturannya ada dalam buku tahun 1907. Ada yang bilang namanya dari demam emas Kanada, tetapi tak ada bukti yang kuat.","Pada 1990 Klondike hadir bersama komputer pribadi sebagai permainan bawaan, dan orang di seluruh dunia mulai memainkannya. FreeCell, yang semua kartunya terbuka, diciptakan pada 1978 oleh Paul Alfille, mahasiswa kedokteran, di komputer universitas."],"quiz":[["Di Inggris, solitaire disebut apa?","Patience (kesabaran)","Kabal","Klondike","FreeCell"],["Di mana catatan tertua solitaire?","Buku Jerman edisi 1783","Buku Prancis sekitar 1650","Buku Amerika tahun 1907","Komputer tahun 1990"],["Dari susunan 1–32.000 FreeCell bawaan komputer, berapa yang tak terpecahkan?","Hanya satu, nomor 11982","Tepat setengahnya","Satu dari setiap seratus","Tidak ada"]],"kf":["Susun kartu sendirian dan bangun tiap jenis dari As sampai Raja untuk menang. Di Inggris disebut “patience”","Catatan tertua: buku Jerman edisi 1783. Kemungkinan lahir di Jerman atau Skandinavia","Aturan tertua Klondike ada di buku tahun 1907; sejak 1990 komputer menyebarkannya ke seluruh dunia"],"more":[{"h":"Susunan Klondike","p":["Dua puluh delapan kartu dibagikan ke tujuh tumpukan dan 24 sisanya menjadi tumpukan sisa. Di tumpukan, kartu disusun menurun selang-seling merah dan hitam. Tempat kosong hanya boleh diisi Raja.","Seberapa sering Klondike bisa dimenangkan dengan bermain baik masih belum diketahui. Bahkan jika semua kartu tertutup diketahui, menurut perhitungan paling banyak sedikit di atas delapan dari sepuluh permainan bisa dimenangkan."],"cap":["Susunan Klondike. Kiri atas: tumpukan sisa dan kartu yang dibuka; kanan atas: empat fondasi menurut jenis. Bawah: tujuh tumpukan berisi satu sampai tujuh kartu, hanya yang teratas terbuka"]},{"h":"FreeCell, hampir selalu terpecahkan","p":["Dalam FreeCell, kartu yang semuanya terbuka disusun ulang dengan bantuan empat sel bebas yang masing-masing memuat satu kartu. Ini permainan perhitungan, bukan keberuntungan, dan hampir semua susunan bisa dipecahkan.","Dari susunan 1–32.000 permainan bawaan komputer, hanya nomor 11982 yang tak bisa dipecahkan. Penelitian tahun 2018 atas 8,6 miliar susunan juga menemukan sekitar satu yang tak terpecahkan dari setiap 84.000."],"cap":["Susunan FreeCell. Kiri atas: empat sel bebas; kanan atas: empat fondasi; bawah: delapan kolom yang semuanya terbuka. Pita di bawah mewakili susunan 1–32.000 permainan bawaan komputer: hanya nomor 11982 yang tak terpecahkan"]},{"h":"Patience dari masa ke masa","p":["FreeCell berasal dari “Baker’s Game” yang dibahas Martin Gardner di sebuah majalah pada 1968. Di akhir abad ke-19, Mary Whitmore Jones dari Inggris mengumpulkan sekitar 250 permainan dalam buku-bukunya.","Di tempat lain, “solitaire” juga bisa berarti permainan papan untuk satu orang seperti solitaire pasak. Sejarawan permainan David Parlett lebih suka nama “patience”, yang hanya merujuk pada permainan kartu."],"cap":["Patience dari masa ke masa: buku Jerman 1783, buku Inggris sekitar 1870, aturan Klondike 1907, FreeCell 1978, dan komputer 1990"]},{"h":"Cobalah","p":["Solitaire adalah permainan untuk saat-saat tenang yang menata pikiran. Tumpukan mana yang dibongkar dulu, kartu mana yang disimpan? Makin jauh kamu berpikir ke depan, makin sering kamu menang.","Solitaire di Atlas ini menyediakan Klondike, Spider, dan FreeCell, juga susunan harian. Sesuai namanya, kesabaran, susunlah dengan tenang."],"cap":[]}],"tl":[["1783","“Patience” muncul di buku Jerman (catatan tertua)"],["1826","Terbit di Rusia buku khusus tentang solitaire"],["sekitar 1870","Illustrated Games of Patience karya Lady Adelaide Cadogan"],["1907","Aturan Klondike muncul di sebuah buku"],["1990","Menyebar ke dunia lewat permainan bawaan komputer"]],"figL":{"time":[["1783","Patience","catatan tertua, buku Jerman"],["± 1870","Buku berbahasa Inggris","Lady Adelaide Cadogan"],["1907","Klondike","aturan tertua"],["1978","FreeCell","lahir di komputer universitas"],["1990","Ke komputer","permainan bawaan"]]}},"sudoku":{"title":"Angka harus sendiri","lead":"Sudoku: mengisi angka 1 sampai 9 di kisi 9×9. Lahir di majalah Amerika, mendapat nama di Jepang, dan menyebar ke dunia lewat koran Inggris. Tak perlu berhitung — cukup logika.","s":["Sudoku hanya punya satu aturan: isi kisi 9×9 sehingga setiap baris, setiap kolom, dan setiap kotak 3×3 bergaris tebal memuat setiap angka 1 sampai 9 tepat sekali. Tak perlu menjumlah atau mengurangi. Teka-teki yang baik punya tepat satu jawaban.","Sudoku yang selesai adalah sejenis yang oleh matematikawan disebut persegi Latin. Matematikawan abad ke-18 Leonhard Euler dikenal karena menelitinya, tetapi tak ada hubungan langsung dengan teka-tekinya. Pada 1892 dan 1895 koran Prancis memuat persegi ajaib yang diisi angka, tetapi perlu berhitung atau tak punya kotak 3×3, jadi belum sudoku seperti sekarang.","Sudoku modern pertama kali muncul pada 1979 di sebuah majalah teka-teki Amerika dengan nama “Number Place”. Pembuatnya diduga Howard Garns, seorang arsitek pensiunan.","Pada 1984 sebuah majalah teka-teki Jepang (Nikoli) memperkenalkannya dengan nama “angka harus lajang”, dan pada 1986 presiden perusahaan itu, Maki Kaji, menyingkatnya menjadi “sudoku”. Di Jepang nama itu merek dagang terdaftar perusahaan tersebut, dan penerbit lain menyebutnya “nanpure” dan sebagainya.","Wayne Gould, yang menemukan buku sudoku di Tokyo pada 1997, bertahun-tahun menulis program pembuat soal, dan pada November 2004 sudoku muncul di koran Inggris The Times. Pada 2005 sudoku sudah menjadi demam di koran seluruh dunia, dan sejak 2006 diadakan kejuaraan dunia."],"quiz":[["Dalam sudoku, apa yang harus memuat angka 1 sampai 9 tepat sekali?","Setiap baris, kolom, dan kotak 3×3","Hanya kolom","Hanya diagonal","Hanya tepi"],["Berapa petunjuk paling sedikit pada sudoku berjawaban tunggal?","17","9","25","30"],["Di mana dan kapan sudoku modern pertama muncul di majalah?","AS, 1979","Jepang, 1984","Prancis, 1892","Inggris, 2004"]],"kf":["Setiap baris, kolom, dan kotak 3×3 berisi 1–9 sekali. Tanpa berhitung","Minimal 17 petunjuk: pencarian menyeluruh 2012 menunjukkan tak ada sudoku 16 petunjuk berjawaban tunggal","“Number Place” di AS, 1979 → diberi nama di Jepang, 1984 → ke dunia dari Inggris, 2004"],"more":[{"h":"Baris, kolom, dan kotak","p":["Gagasan paling dasar dalam menyelesaikan sudoku adalah menemukan “angka ini hanya bisa di sini”. Setelah satu angka diletakkan, tak ada sel lain di baris, kolom, atau kotaknya yang boleh berisi angka sama.","Seperti pada gambar, angka 5 di tempat lain menutup baris dan kolom kotak kiri atas sampai tinggal satu sel untuk angka 5-nya. Teka-teki yang baik bisa diselesaikan sampai akhir hanya dengan langkah kecil seperti itu, tanpa menebak."],"cap":["Batasan. Kita mencari angka 5 untuk kotak kiri atas (bingkai hijau). Empat angka 5 lainnya menutup baris dan kolomnya (pita merah), sehingga hanya sel hijau yang tersisa untuk angka 5-nya"]},{"h":"Mulai dari tujuh belas petunjuk","p":["Jika petunjuk dikurangi satu per satu, pada titik tertentu jawabannya tak lagi tunggal. Pada 2012 Gary McGuire dari Irlandia dan rekan-rekannya menunjukkan lewat pencarian menyeluruh komputer yang panjang bahwa tak ada sudoku 16 petunjuk yang berjawaban tunggal: minimalnya 17.","Pada 2005 juga dihitung bahwa ada sekitar 6,67 × 10²¹ kisi sudoku yang lengkap. Lebih banyak petunjuk tak selalu berarti lebih mudah: tingkat kesulitan tergantung letak petunjuknya."],"cap":["Sudoku dengan hanya 17 petunjuk; tetap punya satu jawaban. Tak ada sudoku 16 petunjuk yang berjawaban tunggal"]},{"h":"Sudoku dari masa ke masa","p":["Nama “sudoku” menyingkat “angka harus lajang” — satu angka di setiap sel. Dalam bahasa Indonesia pun disebut sudoku.","Banyak kerabatnya dengan aturan sedikit diubah: “killer”, yang petunjuknya jumlah tiap kurungan; “jigsaw”, dengan wilayah tak beraturan; dan teka-teki raksasa dari lima kisi yang bertumpuk."],"cap":["Sudoku dari masa ke masa: persegi Latin Euler, teka-teki koran Prancis, “Number Place” Amerika, penamaan di Jepang, dan demam dunia yang dimulai di Inggris"]},{"h":"Cobalah","p":["Dengan pensil, kertas, dan sedikit ilham, sudoku bisa dimainkan di mana saja. Jika buntu, pilih satu angka dan telusuri seluruh kisi.","Atlas ini punya sudoku dengan soal baru setiap hari dalam tiga tingkat, dan sudoku cepat, adu kecepatan di kisi kecil 4×4."],"cap":[]}],"tl":[["1782","Euler meneliti persegi Latin (akar matematisnya)"],["1892","Teka-teki angka di koran Prancis"],["1979","“Number Place” di majalah Amerika"],["1984","Diperkenalkan di Jepang; 1986 dinamai “sudoku”"],["2004","Demam dunia dimulai dari koran Inggris"]],"figL":{"time":[["1782","Persegi Latin","penelitian Euler"],["1892","Koran Prancis","teka-teki isi angka"],["1979","Number Place","majalah Amerika"],["1984","“Sudoku”","nama dari majalah Jepang"],["2004","Demam dunia","dari koran Inggris"]]}},"shanghai":{"title":"Ubin bertumpuk, dua demi dua","lead":"Solitaire mahjong, yang di Jepang disebut “Shanghai”, adalah mengambil pasangan ubin yang sama dari tumpukan ubin mahjong. Ubinnya lahir di Tiongkok abad ke-19, tetapi cara bermain ini lahir pada 1981 di komputer universitas Amerika.","s":["Solitaire mahjong adalah permainan untuk satu orang: 144 ubin mahjong ditumpuk beberapa lapis, lalu ubin bergambar sama diambil dua demi dua. Yang boleh diambil hanya ubin yang tidak tertindih dan sisi kiri atau kanannya kosong. Menang jika ke-72 pasangan habis diambil.","Ubinnya sendiri adalah ubin mahjong yang lahir di Tiongkok abad ke-19. Tetapi menumpuk lalu mengambilnya sendirian dimulai pada 1981 dengan “Mah-Jongg”, buatan Brodie Lockard dari Amerika di PLATO, sistem komputer pendidikan yang dipakai di universitas.","Pada 1986 permainan ini dijual untuk komputer rumah dengan nama “Shanghai” dan laris. Di Jepang, nama itu menjadi sebutan untuk cara bermain ini sendiri.","Saat dirilis, permainan ini diiklankan berasal dari “Kura-kura”, permainan yang konon dimainkan di Tiongkok sejak berabad-abad. Namun Lockard sendiri tak pernah berkata begitu, dan tak ada bukti kuat — anggap saja legenda.","Sekitar 1989 muncul kerabatnya di pusat permainan, Shisen-sho, tempat pasangan ubin dihubungkan dengan garis. Sejak 1990 permainan ini juga banyak dimainkan sebagai permainan bawaan komputer pribadi."],"quiz":[["Ubin mana yang boleh diambil dalam solitaire mahjong?","Yang tidak tertindih dan sisi kiri atau kanannya kosong","Yang di lapis paling bawah","Yang terkepung di semua sisi","Hanya yang di tengah"],["Di mana cara bermain ini pertama dibuat?","Di komputer universitas Amerika, 1981","Di Tiongkok abad ke-19","Di Shanghai tahun 1920-an","Di Jepang tahun 1990"],["Bagaimana dengan cerita bahwa ia berasal dari permainan kuno Tiongkok, “Kura-kura”?","Itu iklan, tanpa bukti kuat","Penciptanya menuliskannya","Ada di buku kuno Tiongkok","Berasal dari pola tempurung"]],"kf":["Ambil pasangan sama dari tumpukan 144 ubin; hanya ubin yang tak tertindih dan satu sisinya kosong yang bebas","Dimulai pada 1981 dengan “Mah-Jongg” karya Lockard di PLATO","Menyebar sebagai “Shanghai” pada 1986; legenda Kura-kura hanyalah iklan tanpa bukti"],"more":[{"h":"Ubin bebas dan ubin terkunci","p":["Dua syarat menentukan apakah ubin bebas: tidak ada yang menindihnya, dan tak ada ubin di kiri atau kanannya. Bunga (plum, anggrek, krisan, bambu) dan musim (semi, panas, gugur, dingin) berpasangan di dalam kelompoknya meski gambarnya berbeda.","Urutan sangat penting. Jika pasangan pertama yang terlihat langsung diambil, ubin yang sama bisa terkunci di bawah ubin lain dan membuatmu buntu di akhir."],"cap":["Ubin yang boleh diambil (✓) dan yang tidak (×). Atas: dua ubin di ujung dan 發 yang menindih bebas; ubin yang tertindih atau terjepit di kedua sisi tidak. Bawah: 東 di tengah terjepit di kedua sisi"]},{"h":"Kura-kura yang terkenal","p":["Kura-kura adalah tumpukan memanjang dengan ubin menonjol di kedua ujung seperti kepala dan ekor. Penelitian atas sepuluh juta susunan ini mendapati sekitar 3% tak bisa dihabiskan bagaimanapun dimainkan.","Banyak susunan lain telah dibuat — piramida, naga, kastel, dan lainnya. Setiap bentuk mengubah di mana ubin mudah diambil dan di mana mudah macet."],"cap":["Susunan paling terkenal, Kura-kura, dilihat dari atas: 87 ubin di lapis bawah, lalu 36, 16, 4, dan satu di puncak — lima lapis, 144 ubin (makin gelap = makin tinggi)"]},{"h":"Solitaire mahjong dari masa ke masa","p":["Dalam Shisen-sho, dua ubin sama boleh diambil jika bisa dihubungkan dengan garis berbelok paling banyak dua kali yang tak menyentuh ubin lain. Ubin dijajarkan datar, tidak ditumpuk.","PLATO adalah sistem komputer pendidikan yang lahir di Universitas Illinois, dikenal juga karena banyak permainan dibuat di sana sejak awal."],"cap":["Solitaire mahjong dari masa ke masa: legenda Kura-kura, “Mah-Jongg” di PLATO 1981, “Shanghai” 1986, Shisen-sho sekitar 1989, dan komputer pribadi sejak 1990"]},{"h":"Cobalah","p":["Cari dulu semua pasangan yang bisa diambil, lalu putuskan mana yang diambil lebih dulu. Saat terlihat tiga atau empat ubin bergambar sama, di situlah keterampilan tampak.","Solitaire mahjong di Atlas ini khusus 3D, dengan Kura-kura dan banyak susunan lain. Setiap susunan dibuat agar bisa dihabiskan seluruhnya."],"cap":[]}],"tl":[["1981","Lockard membuat “Mah-Jongg” di PLATO"],["1986","Dijual untuk komputer rumah sebagai “Shanghai”"],["1986","Diiklankan berasal dari “Kura-kura” Tiongkok (tanpa bukti)"],["1989","Shisen-sho, yang menghubungkan ubin dengan garis, hadir di pusat permainan"],["1990","Juga dimainkan sebagai permainan bawaan komputer"]],"figL":{"time":[["?","Legenda Kura-kura","permainan kuno Tiongkok? (iklan)"],["1981","Mah-Jongg","di sistem PLATO"],["1986","“Shanghai”","di komputer rumah"],["1989","Shisen-sho","kerabat bergaris"],["1990","Di PC","permainan bawaan"]]}},"samegame":{"title":"Warna sama, semuanya sekaligus","lead":"Dalam SameGame, ubin bertetangga yang sewarna dihapus berkelompok. Lahir di komputer pribadi Jepang pada 1985, permainan ini menyebar ke dunia dengan nama-nama baru sebagai cikal bakal teka-teki “kosongkan papan”.","s":["SameGame adalah teka-teki untuk satu orang di papan penuh ubin berwarna. Jika dua ubin atau lebih yang sewarna bersentuhan mendatar atau tegak, seluruh kelompok itu bisa dihapus sekaligus. Ubin di atas jatuh ke celah, dan kolom yang kosong bergeser ke kiri. Permainan selesai jika tak ada kelompok lagi.","Semuanya bermula pada 1985 dengan “Chain Shot!”, buatan Kuniaki Moribe untuk komputer pribadi Jepang masa itu. Permainan ini disebarkan lewat majalah komputer; papannya 20×10 dengan empat warna.","Pada 1992 Eiji Fukumoto memindahkannya ke komputer Unix sebagai “SameGame” dan menambah warnanya menjadi lima. Dari situlah nama itu menyebar. “Same” adalah kata Inggris untuk “sama”.","Lalu muncul banyak versi dan olahan di komputer, perangkat genggam, dan konsol. Sebagian, seperti “Clickomania!” pada 1998, membolehkan ukuran papan dan jumlah warna diubah.","Tampaknya sederhana, tetapi teka-teki ini dalam. Penelitian tahun 2001 menunjukkan bahwa menentukan apakah papan bisa dikosongkan sepenuhnya bisa menjadi masalah “NP-lengkap”, istilah ilmuwan komputer untuk masalah yang sulit."],"quiz":[["Apa yang bisa dihapus dalam SameGame?","Kelompok dua ubin atau lebih yang sewarna dan bertetangga","Satu ubin saja","Ubin yang bersentuhan diagonal","Hanya baris teratas"],["Dengan skor umum (n−2)², berapa nilai kelompok 10 ubin?","64","10","20","100"],["Apa arti “same” dalam SameGame?","Kata Inggris “sama”","Sejenis ikan","“Dingin” dalam bahasa Jepang","Nama pembuatnya"]],"kf":["Dua ubin sewarna atau lebih yang bertetangga bisa dihapus. Yang di atas jatuh; kolom kosong bergeser ke kiri","Bermula dengan “Chain Shot!” pada 1985; namanya menyebar lewat “SameGame” pada 1992","Di banyak versi kelompok bernilai (n−2)²: besarkan kelompok lalu hapus sekaligus"],"more":[{"h":"Hapus, jatuh, bergeser","p":["Setiap kelompok yang dihapus mengubah seluruh bentuk papan. Ubin yang jatuh bisa membentuk kelompok baru — atau memecah warna yang sedang kamu simpan.","Ubin yang tinggal sendirian tak bisa dihapus. Berapa ubin yang tersisa di akhir — bisakah kamu mengosongkan semuanya? Di situlah keterampilan terlihat."],"cap":["Di papan kiri, kelompok lima ubin biru bertanda putih dihapus (papan kanan): ubin di atasnya jatuh (panah merah), dan kolom yang kosong hilang karena kolom di kanannya bergeser ke kiri"]},{"h":"Makin besar, makin untung","p":["Di banyak versi, kelompok berisi n ubin bernilai (n−2)² poin. Pasangan tak berpoin, lima bernilai 9, sepuluh bernilai 64: makin besar kelompoknya, makin cepat poinnya naik.","Jadi rencana dasarnya: hapus dulu kelompok kecil yang mengganggu, kumpulkan satu warna, lalu hapus sekaligus. Banyak versi juga memberi bonus besar jika papan kosong sepenuhnya."],"cap":["Ukuran kelompok n dan skor (n−2)²: dua ubin bernilai 0, lima bernilai 9, sepuluh bernilai 64. Menghapus sepuluh sekaligus jauh lebih berharga daripada dua kelompok lima"]},{"h":"SameGame dari masa ke masa","p":["Pada 1994 muncul versi Macintosh, dan versi berbasis itu kemudian dimasukkan ke lingkungan desktop bebas sehingga dimainkan orang di seluruh dunia.","Pencipta aslinya, Kuniaki Moribe, kemudian juga membuat versi ulang sendiri. Teka-teki mengosongkan papan terus lahir hingga kini."],"cap":["SameGame dari masa ke masa: “Chain Shot!” 1985, “SameGame” 1992, “Clickomania!” 1998, bukti kesulitan 2001, dan “SameGame POP!” di Atlas ini"]},{"h":"Cobalah","p":["Coba simpan warna terbanyak sampai akhir dan hapus warna lain lebih dulu. Merasakan kelompok besar tumbuh adalah keseruan SameGame.","“SameGame POP!” di Atlas ini adalah permainan orisinal berdasarkan aturan ini. Mainkan babak dengan blok khusus seperti es dan prisma, atau soal harian."],"cap":[]}],"tl":[["1985","Kuniaki Moribe membuat “Chain Shot!” (20×10, empat warna)"],["1992","“SameGame” Unix karya Eiji Fukumoto: lima warna, namanya menyebar"],["1994","Versi Macintosh, dasar banyak versi berikutnya"],["1998","“Clickomania!” dengan papan dan warna yang bisa diatur"],["2001","Terbukti: menentukan bisa-tidaknya papan dikosongkan adalah NP-lengkap"]],"figL":{"time":[["1985","Chain Shot!","Moribe · PC Jepang"],["1992","SameGame","Fukumoto · Unix · 5 warna"],["1998","Clickomania!","papan dan warna bebas"],["2001","Bukti kesulitan","mengosongkan NP-lengkap"],["kini","SameGame POP!","orisinal Atlas ini"]]}},"cards":{"title":"Perjalanan panjang empat tanda","lead":"Hati, wajik, keriting, dan sekop. Tanda pada kartu remi yang dimainkan dunia hari ini bermula dari kartu kertas di Tiongkok, lalu melintasi Mesir zaman Mamluk dan seluruh Eropa, berubah bentuk dari tangan ke tangan.","s":["Kartu kertas diduga lahir di Tiongkok. Kartu diperkirakan sudah ada sekitar abad ke-9 pada masa Dinasti Tang, ketika cetak balok kayu menyebar, dan sebuah teks mencatat seorang putri Tang memainkan “permainan daun” pada tahun 868 (apakah itu benar-benar permainan kartu masih diperdebatkan). Sarjana Dinasti Song, Ouyang Xiu, menulis bahwa permainan daun sudah ada sejak pertengahan Dinasti Tang. Kemudian, pada masa Ming, dipakai “kartu uang” bergambar koin dan untaian koin.","Di Asia barat ditemukan potongan kartu dari abad ke-12 dan ke-13. Pada tahun 1939 sarjana L. A. Mayer menemukan satu set kartu Mamluk abad ke-15 yang hampir lengkap di Istana Topkapı, Istanbul. Set itu semula berisi 52 kartu dalam empat jenis — cawan, koin, pedang, dan tongkat polo — dan setiap jenis punya tiga kartu berpangkat: raja, wakil raja, dan wakil kedua.","Kartu diduga sampai ke Eropa dari dunia Islam ini. Catatan tertua adalah kamus rima berbahasa Katala tahun 1371. Pada 1377 Firenze melarang permainan kartu, dan pada tahun yang sama biarawan Jerman Johannes dari Rheinfelden menulis risalah tentang kartu. Kata Spanyol untuk kartu, naipes, diduga berasal dari kata Arab nā’ib, “wakil”.","Di Eropa, tongkat polo yang asing berubah menjadi tongkat pentung, sehingga lahirlah jenis “Latin”: cawan, koin, pedang, dan pentung. Di negeri berbahasa Jerman abad ke-15 muncul jenis “Jerman” — hati, lonceng, daun, dan biji ek — dan sekitar tahun 1480 para pembuat kartu Prancis menyederhanakannya menjadi hati, wajik, keriting, dan sekop. Mudah diwarnai dengan stensil, bentuk-bentuk ini kemudian menjadi standar dunia.","Pedagang Portugis membawa kartu ke Jepang pada pertengahan abad ke-16. Kata Jepang karuta berasal dari bahasa Portugis carta, “kartu”. Pada era Tenshō (1573–92), di Miike, Chikugo, dibuat “Tenshō karuta” berisi 48 kartu yang meniru kartu Portugis. Setelah dilarang keshogunan pada 1633, para pembuat mengubah gambarnya, dan lama-kelamaan lahirlah hanafuda dan uta-garuta yang memakai puisi."],"quiz":[["Jenis apa yang ada pada kartu Mamluk?","Tongkat polo","Biji ek","Lonceng","Wajik"],["Dari mana asal kata “karuta”?","Dari bahasa Portugis carta","Dari “permainan daun” Tiongkok","Dari bahasa Belanda kaart","Dari kata Jepang kuno"],["Di mana dan kapan hati, wajik, keriting, dan sekop muncul?","Di Prancis, sekitar 1480","Di Tiongkok masa Tang","Di Mesir masa Mamluk","Di Amerika abad ke-19"]],"kf":["Kartu kertas diduga lahir di Tiongkok (Tang) sekitar abad ke-9","Cawan, koin, pedang, dan tongkat polo Mamluk menjadi akar jenis kartu Eropa","♥♦♣♠ lahir di Prancis sekitar 1480; kata Jepang “karuta” berasal dari bahasa Portugis carta"],"more":[{"h":"Bagaimana tanda-tandanya berubah","p":["Gambar jenis kartu berubah menyesuaikan kehidupan di setiap negeri yang dicapainya. Di Eropa, yang tidak mengenal polo, tongkatnya dianggap pentung. Di negeri berbahasa Jerman, cawan diduga menjadi hati, koin menjadi lonceng, pedang menjadi daun, dan pentung menjadi biji ek.","Hingga kini Italia dan Spanyol masih memakai kartu berjenis Latin, sedangkan Jerman selatan dan Austria memakai kartu berjenis Jerman, bersama permainan daerahnya. Dalam bahasa Prancis, ♣ disebut trèfle, “semanggi”, dan ♠ disebut pique, “tombak”."],"cap":["Jenis kartu dari masa ke masa (tiap kolom kira-kira saling berpadanan). Cawan, koin, pedang, dan tongkat polo Mamluk menjadi cawan, koin, pedang, dan pentung Latin, lalu hati, lonceng, daun, dan biji ek Jerman, kemudian ♥ ♦ ♠ ♣ Prancis"]},{"h":"Dari timur ke barat, lalu ke Jepang","p":["Perjalanan kartu juga merupakan perjalanan kertas dan percetakan. Kartu lukisan tangan yang mahal menjadi murah setelah dicetak dengan balok kayu dan diwarnai dengan stensil, dan pada akhir abad ke-14 kartu sudah menyebar ke kota-kota di Eropa. Pada paruh pertama abad ke-15 ada catatan tentang kartu yang dicetak di Ulm dan Nürnberg.","Secepat kartu menyebar, secepat itu pula muncul dekret yang khawatir orang terlalu banyak bermain. Ironisnya, larangan-larangan itu kini menjadi bukti paling pasti tentang kapan dan di mana kartu ada."],"cap":["Perjalanan kartu: dari kartu kertas Tiongkok ke kartu Mamluk di Asia barat, Eropa abad ke-14, Prancis sekitar 1480, dan Jepang abad ke-16"]},{"h":"Lima puluh dua kartu dan joker","p":["Empat jenis masing-masing tiga belas, seluruhnya lima puluh dua kartu: sama dengan jumlah kartu Mamluk. Di Eropa kartu berpangkat mengambil rupa raja, kesatria, dan pelayan, dan kartu Prancis akhirnya memakai raja, ratu, dan jack.","Angka dan tanda kecil di sudut — “indeks” — dikenal dari contoh awal tahun 1693; berkat itu kartu dapat dipegang terbuka seperti kipas. Joker diduga ditambahkan di Amerika Serikat pada pertengahan abad ke-19 (sekitar 1860-an) sebagai truf tertinggi dalam permainan euchre."],"cap":["Lima puluh dua kartu: empat jenis × 13. J, Q, dan K adalah 12 kartu bergambar (emas). Joker ditambahkan di AS pada pertengahan abad ke-19"]},{"h":"Coba mainkan","p":["Dengan lima puluh dua kartu yang sama, kita bisa memainkan permainan yang sangat berbeda: solitaire yang disusun sendirian, poker dengan kombinasinya, dan blackjack yang mengincar angka 21. Satu set kartu adalah kotak perkakas berisi ratusan permainan.","Poker dan blackjack di Atlas ini dibuat untuk mempelajari aturan dan cara berpikir tanpa memakai uang sama sekali. Bersama solitaire, cobalah permainan kartu yang tumbuh dari sejarah panjang ini."],"cap":[]}],"tl":[["868","Teks mencatat seorang putri Tang memainkan “permainan daun”"],["abad 12–13","Potongan kartu dari Asia barat (yang tertua yang tersisa)"],["1377","Larangan di Firenze; risalah Johannes dari Rheinfelden"],["± 1480","Jenis ♥ ♦ ♣ ♠ muncul di Prancis"],["1573–92","Era Tenshō: “Tenshō karuta” dibuat di Miike"]],"figL":{"suits":[["Mamluk","abad 15"],["Latin","sejak abad 14"],["Jerman","abad 15"],["Prancis","± 1480"]],"route":[["± abad 9","Tiongkok","kartu daun dan uang"],["abad 12–15","Mamluk","cawan, koin, pedang, polo"],["1370-an","Eropa","ke Spanyol dan Italia"],["± 1480","Prancis","♥ ♦ ♣ ♠"],["akhir abad 16","Jepang","Tenshō karuta"]],"court":["Kartu angka","Kartu gambar","Joker","pertengahan abad 19, AS"]}},"machines":{"title":"Mesin yang belajar bermain","lead":"Dari tipuan sebuah boneka mekanis, ke mesin hitung yang membaca langkah ke depan, hingga program yang makin kuat dengan melawan dirinya sendiri: selama 250 tahun, permainan papan menjadi ajang uji “mesin yang berpikir”.","s":["Pada 1770, di Istana Schönbrunn, Wina, Wolfgang von Kempelen memamerkan boneka yang bermain catur, “si Turki”. Boneka itu berkeliling Eropa dan Amerika dan membuat penonton takjub; konon Napoleon pun pernah melawannya. Namun itu tipuan: seorang manusia yang bersembunyi di dalam lemari yang menjalankan langkahnya. Si Turki hangus dalam kebakaran di Philadelphia pada 1854.","Mesin pertama yang benar-benar bermain sendiri dibuat oleh insinyur Spanyol Leonardo Torres Quevedo. Selesai pada 1912, “El Ajedrecista” (“si pecatur”) memakai rangkaian listrik untuk memainkan satu akhir permainan saja: raja dan benteng putih melawan raja hitam. Ia tidak selalu menemukan jalan terpendek, tetapi konon selalu berhasil men-skakmat.","Pada 1950, Claude Shannon dari Amerika menunjukkan, dalam makalah tentang cara memprogram komputer untuk bermain catur, cara memberi nilai pada posisi, melihat beberapa langkah ke depan, dan memilih langkah terbaik. Di Inggris, Alan Turing menulis program catur di atas kertas sebelum ada komputer yang bisa menjalankannya, dan konon memainkannya dengan menghitung langkah-langkahnya sendiri dengan tangan.","Pada 1950-an, Arthur Samuel membuat komputer bermain dam dan menyuruhnya melawan dirinya sendiri berulang kali agar sedikit demi sedikit makin kuat. Ia dianggap mempopulerkan istilah “pembelajaran mesin” (machine learning), yang dipakai dalam judul makalahnya tahun 1959. Kemudian program Kanada, Chinook, meraih gelar juara dunia manusia lawan mesin pada 1994, dan pada 2007 dam (Inggris) akhirnya “terpecahkan”: jika kedua pihak bermain sempurna, hasilnya remis.","Pada 1997, Deep Blue buatan IBM mengalahkan juara dunia Garry Kasparov 3½–2½ (setahun sebelumnya Kasparov menang 4–2). Bahkan dalam go, yang dianggap terlalu sulit karena banyaknya langkah yang mungkin, AlphaGo buatan DeepMind mengalahkan Lee Sedol 4–1 pada 2016. Pada 2017, AlphaZero, yang hanya diberi aturan, mempelajari catur, shogi, dan go sendiri hanya dengan melawan dirinya sendiri."],"quiz":[["Apa rahasia “si Turki” yang dipamerkan pada 1770?","Manusia yang bersembunyi di dalam yang bermain","Hanya roda gigi yang berpikir","Bekerja dengan listrik","Diberi perintah lewat surat dari jauh"],["Apa yang ditunjukkan oleh pemecahan dam pada 2007?","Dengan permainan sempurna hasilnya remis","Pemain pertama selalu menang","Pemain kedua selalu menang","Belum diketahui apa-apa"],["Program go apa yang mengalahkan Lee Sedol pada 2016?","AlphaGo","Deep Blue","Chinook","El Ajedrecista"]],"kf":["“Si Turki” tahun 1770 adalah tipuan dengan manusia di dalamnya; mesin pertama yang benar-benar bermain sendiri adalah mesin akhir permainan tahun 1912","Makalah Shannon tahun 1950 memulai gagasan “beri nilai dan baca ke depan”; dam terpecahkan pada 2007: remis","Mesin mengalahkan manusia terbaik dalam catur pada 1997 dan dalam go pada 2016"],"more":[{"h":"Manusia lawan mesin dari masa ke masa","p":["Lama sekali, kemampuan mesin bermain permainan papan dianggap sebagai ukuran daya pikir. Sejarah yang dimulai dari boneka tipuan berlanjut ke alat listrik, program di atas kertas, dan akhirnya komputer sungguhan.","Uniknya, setiap zaman punya permainan yang “tak mungkin dimainkan dengan baik oleh mesin”. Dam, lalu catur, lalu go: garis itu terus bergeser maju."],"cap":["Manusia lawan mesin: “si Turki” tahun 1770 (tipuan), mesin akhir permainan 1912, makalah 1950, Samuel pada 1959, Chinook pada 1994, Deep Blue pada 1997, AlphaGo pada 2016, dan AlphaZero pada 2017"]},{"h":"Cara membaca ke depan","p":["Banyak program membentangkan masa depan suatu posisi seperti cabang-cabang pohon. Pada gilirannya sendiri ia menganggap langkah terbaik (maksimum), pada giliran lawan langkah terburuk baginya (minimum), lalu membawa nilai daun naik sampai ke akar. Ini disebut “minimax”.","Tidak semua cabang perlu dibaca. Cabang yang sudah diketahui lebih buruk daripada langkah lain dapat dipangkas tanpa dibaca lebih jauh (pemangkasan alfa-beta). Berkat pemangkasan ini, program dapat membaca jauh lebih dalam dalam waktu yang sama."],"cap":["Minimax dan pemangkasan. ▲ adalah mesin (memilih yang terbesar), ▼ lawan (memilih yang terkecil). Cabang kiri menjamin 3, jadi begitu cabang tengah menunjukkan 2, ia diketahui lebih buruk, dan dua daun lainnya (?) tidak perlu dibaca (✂). Jawaban di akar adalah 3"]},{"h":"Permainan yang terpecahkan dan yang belum","p":["“Memecahkan” suatu permainan berarti memastikan apa yang terjadi bila kedua pihak bermain sempurna. Tic-tac-toe berakhir remis; pada 1988 terbukti bahwa dalam empat sebaris pemain pertama menang, dan pada 2007 bahwa dam berakhir remis. Reversi (Othello) diumumkan remis pada 2023, meski hasil itu masih diperdebatkan.","Jumlah posisi yang mungkin sekitar 10 pangkat 44 pada catur dan lebih dari 10 pangkat 170 pada go — jauh lebih banyak daripada atom di alam semesta (konon sekitar 10 pangkat 80). Catur dan go belum terpecahkan."],"cap":["Posisi yang mungkin (pangkat sepuluh, skala logaritma). Tic-tac-toe, empat sebaris, dam, dan reversi sudah terpecahkan (✓); catur dan go belum (?)"]},{"h":"Coba mainkan","p":["Dalam catur, dam, go, dan empat sebaris di Atlas ini, kamu bisa bermain melawan komputer. Mulailah dengan lawan yang lunak, lalu naikkan levelnya sedikit demi sedikit.","AI permainan di Atlas berjalan dengan mesin berpikir bersama yang bernama Praline. Membayangkan mesin membaca langkah ke depan sambil bermain memberi keseruan yang berbeda."],"cap":[]}],"tl":[["1770","“Si Turki” dipamerkan (tipuan dengan pemain tersembunyi)"],["1912","Mesin akhir permainan catur karya Torres Quevedo"],["1950","Makalah Shannon tentang membaca ke depan dalam catur"],["1997","Deep Blue mengalahkan Kasparov"],["2016","AlphaGo mengalahkan Lee Sedol 4–1"]],"figL":{"time":[["1770","Si Turki","tipuan: ada manusia di dalam"],["1912","El Ajedrecista","main R+B lawan R sendiri"],["1950","Shannon, Turing","membaca ke depan di catur"],["1959","Samuel","belajar mesin lewat dam"],["1994","Chinook","dam; terpecahkan 2007"],["1997","Deep Blue","mengalahkan Kasparov"],["2016","AlphaGo","menang 4–1 atas Lee Sedol"],["2017","AlphaZero","belajar dari aturan saja"]],"tree":["Mesin: pilih yang terbesar","Lawan: pilih yang terkecil","Cabang tak dibaca"],"solved":[["Tic-tac-toe","remis"],["Empat sebaris","pertama menang, 1988"],["Dam","remis, 2007"],["Reversi","remis, 2023"],["Catur","belum"],["Go","belum"]]}},"graffiti":{"title":"Papan yang digores di batu","lead":"Anak tangga sebuah forum, atap kuil, bangku serambi katedral. Di mana pun orang menunggu, berkumpul, atau mengisi waktu, seseorang menggores papan permainan di batu. Inilah sejarah bermain yang diceritakan coretan orang-orang tanpa nama.","s":["Basilika Julia di Forum Romawi adalah gedung besar tempat, antara lain, pengadilan bersidang. Anak tangga depan dan lantainya masih menyimpan banyak papan permainan yang digores warga — diduga untuk mengisi waktu sambil menunggu giliran.","Sebagian papan Romawi membentuk petaknya dari huruf. Di forum Timgad, Afrika Utara, ada papan dari enam kata berhuruf enam yang berbunyi: “Berburu, mandi, bermain, tertawa — itulah hidup.” Papan itu sekaligus semboyan hidup kecil.","Papan morris yang digores di batu atap kuil Kurna di Mesir sering disebut contoh tertua, sekitar 1400 SM. Namun peneliti Friedrich Berger mencatat bahwa di antara gambar yang sama ada salib Koptik, lalu menyimpulkan bahwa gambar itu “tidak dapat ditentukan umurnya”. Batu yang tua belum tentu garisnya juga tua.","Di Inggris, papan morris dari deretan lubang digores di bangku batu serambi katedral Canterbury, Gloucester, Norwich, dan Salisbury serta Westminster Abbey. Survei gereja di Essex yang dipaparkan pada 2019 menemukan papan morris di 28 dari 43 gereja; yang paling umum adalah three men’s morris yang kecil.","Beberapa papan digores di permukaan tegak seperti dinding, tempat tak seorang pun bisa bermain. Mungkin batunya ditandai untuk bermain sebelum dipasang di dinding. Ada yang menafsirkannya sebagai tanda pelindung atau gambar kota surgawi, tetapi para peneliti mengingatkan agar berhati-hati."],"quiz":[["Mengapa papan diduga digores di anak tangga Basilika Julia?","Untuk mengisi waktu sambil menunggu","Untuk upacara keagamaan","Sebagai denah gedung","Sebagai penunjuk jalan"],["Apa arti huruf di papan Timgad?","Berburu, mandi, bermain, tertawa — itulah hidup","Kejayaan bagi pemenang","Dilarang bermain di sini","Hidup kaisar"],["Apa yang dicatat seorang peneliti tentang papan di Kurna?","Umurnya tidak dapat ditentukan","Terbuat dari emas","Digores seorang kaisar Romawi","Berasal dari Tiongkok"]],"kf":["Papan digores di tempat orang menunggu atau berkumpul: tangga forum, kuil, serambi katedral","Papan Timgad tersusun dari huruf: “Berburu, mandi, bermain, tertawa — itulah hidup”","Batu tua belum tentu garis tua: menentukan umur papan yang digores itu sulit"],"more":[{"h":"Di mana papan-papan itu","p":["Papan yang digores muncul di tempat orang menghabiskan waktu lama: forum, kuil, gereja, bahkan kapal. Papan kayu yang dibawa-bawa jarang bertahan, tetapi garis yang dipahat di batu bertahan ratusan bahkan ribuan tahun.","Lubang congklak (mancala) yang dipahat di batu juga ditemukan di situs abad ke-6–7 di Etiopia dan Eritrea. Konon bersama kapal Gokstad di Norwegia (abad ke-9) ditemukan sebilah papan bergores papan morris."],"cap":["Tempat terkenal dengan papan yang digores: Basilika Julia di Roma, forum Timgad, kuil Kurna (umurnya tak diketahui), lubang di batu dari masa Aksum, kapal Gokstad, dan serambi katedral Inggris"]},{"h":"Tiga bentuk yang digores berulang kali","p":["Yang paling umum adalah papan morris: tiga persegi yang dihubungkan garis. Karena hanya garis lurus, mudah digores bahkan di batu. Pada masa Romawi sering digores papan tiga baris berisi dua belas petak, kadang petaknya berupa huruf.","Congklak memakai lubang bundar, bukan garis. Cukup gali sederet cekungan di tanah atau batu, dan permainan bisa langsung dimulai di mana saja."],"cap":["Tiga papan yang sering digores di batu: kiri atas papan morris (24 titik), kanan atas dua baris lubang congklak, bawah papan huruf dari Timgad (3 baris × 12: VENARI LAVARI…)"]},{"h":"Kapan digoresnya?","p":["Menentukan umur papan yang digores adalah soal sulit. Yang bisa ditentukan umurnya hanyalah batu atau bangunannya; garisnya sendiri bisa digores kapan saja sesudahnya.","Sebaliknya, bila batu berpapan diambil dari bangunan yang lebih tua lalu dipakai lagi di dinding, papannya bisa lebih tua daripada dindingnya. Para peneliti mempersempit umurnya sedikit demi sedikit, berbekal coretan lain dan cara batu itu dipakai."],"cap":["Mengapa menentukan umur itu sulit. Di Kurna atap kuil berasal dari sekitar 1400 SM, tetapi di batu yang sama ada salib Koptik, sehingga kapan papan digores tidak diketahui (?). Di bawah, batu tua berpapan yang dipasang miring di dinding: papannya mungkin lebih tua daripada dinding"]},{"h":"Coba mainkan","p":["Di Atlas ini kamu bisa memainkan nine men’s morris, congklak (mancala), dan latrunculi Romawi — semuanya papan yang diwariskan lewat goresan di batu.","Jika dalam perjalanan kamu menemukan tiga persegi bersarang di anak tangga tua atau bangku serambi, mungkin itu tempat bermain seseorang ratusan tahun lalu."],"cap":[]}],"tl":[["1400 SM?","Atap kuil Kurna (umur papan tak dapat ditentukan)"],["Masa Romawi","Papan digores di tangga dan lantai forum"],["abad 6–7","Lubang congklak di batu pada masa Aksum"],["abad 9","Papan morris pada papan kayu kapal Gokstad (konon)"],["Abad Pertengahan","Papan di bangku serambi katedral Inggris"]],"figL":{"map":[["Basilika Julia","Roma: tangga Forum"],["Timgad","Afrika Utara: papan huruf"],["Kuil Kurna","Mesir: umur tak diketahui"],["Matara, Yeha","Masa Aksum: lubang batu"],["Kapal Gokstad","Norwegia, abad ke-9"],["Serambi katedral","Canterbury dan lainnya"]],"boards":[["Morris","24 titik"],["Papan Romawi","3 × 12, Timgad"],["Congklak","dua baris lubang"]],"dating":[["± 1400 SM","batu atap kuil"],["Masehi","salib Koptik di batu yang sama"],["Kini","kapan papan digores?"],["Batu tua di dinding:","papannya bisa lebih tua"]]}},"bans":{"title":"Permainan yang dilarang penguasa","lead":"Seorang maharani Jepang, raja Prancis, kota Firenze, para biarawan Spanyol, wali kota New York. Penguasa di segala zaman dan tempat pernah melarang permainan — tetapi kebanyakan sebenarnya tidak membidik permainannya, melainkan judinya.","s":["Salah satu contoh awal yang tercatat berasal dari Jepang. Menurut Nihon Shoki, pada 689 Maharani Jitō melarang sugoroku, yang sejak lama terkait dengan judi. Larangan itu diulang berkali-kali, dan Keshogunan Kamakura juga melarang judi sugoroku, tetapi permainan papan itu tetap dimainkan hingga zaman Edo.","Di Eropa, Raja Louis IX dari Prancis mengeluarkan maklumat melawan judi pada 1254. Maklumat itu sulit ditegakkan, dan konon pertandingan catur tetap berlangsung di istana. Pada 1377 Firenze melarang permainan kartu — larangan yang kini menjadi salah satu catatan tertua bahwa kartu sudah ada di Eropa.","Patolli di Meksiko bernasib sebaliknya. Para biarawan Spanyol, yang tak menyukai judinya maupun doa kepada dewa-dewa lama, melarangnya, menghancurkan papannya, dan membakar kacangnya. Hampir tak ada perlengkapan yang tersisa; permainannya hanya bisa direkonstruksi dari catatan abad ke-16 dan papan yang dipahat di batu.","Di Jepang pada 1633, keshogunan melarang Tenshō karuta, kartu tiruan kartu Portugis. Para pembuat menjawab dengan kartu bergambar baru, dan kejar-kejaran antara larangan dan kartu baru berlanjut sampai muncul hanafuda. Otoritas agama pun ada yang menentang permainan: di Iran setelah revolusi 1979 catur dilarang, tetapi pada 1988 dinyatakan boleh “asal dimainkan tanpa judi”.","Bukan permainan papan, tetapi menarik: sejak awal 1940-an New York melarang pinball sebagai mesin judi. Pada 1976, di depan anggota dewan kota, seorang penggemar menyebutkan tembakannya lebih dulu — “jalur tengah” — dan berhasil, membuktikan bahwa ini permainan keterampilan, bukan keberuntungan. Peragaan itu membantu mengakhiri larangan."],"quiz":[["Siapa yang melarang sugoroku pada 689?","Maharani Jitō","Kaisar Shōmu","Tokugawa Ieyasu","Mantan Kaisar Shirakawa"],["Apa sebenarnya sasaran kebanyakan larangan?","Judi","Bentuk papan","Bahan bidak","Jam bermain"],["Apa yang membantu mengakhiri larangan pinball di New York pada 1976?","Tembakan yang disebutkan lebih dulu, bukti keterampilan","Kenaikan pajak","Wali kota suka pinball","Semua mesin rusak"]],"kf":["Dari larangan sugoroku oleh Jitō pada 689 hingga larangan pinball di New York, permainan dilarang berulang kali","Kebanyakan larangan membidik judi, bukan permainannya; bermain tanpa taruhan sering kali dibolehkan","Sugoroku tetap dimainkan dan kartu terus menyebar, tetapi patolli hampir lenyap"],"more":[{"h":"Larangan dari masa ke masa","p":["Ironisnya, larangan adalah bukti kuat bahwa suatu permainan ada pada waktu dan tempat tertentu. Sejarah sugoroku di Jepang dan kartu di Eropa nyaris dimulai dari tanggal larangannya.","Dan pihak yang melarang kadang berubah pikiran: catur di Iran dan pinball di New York diizinkan lagi setelah beberapa dasawarsa."],"cap":["Larangan dari masa ke masa: larangan sugoroku oleh Jitō pada 689, maklumat Louis IX pada 1254, larangan kartu di Firenze pada 1377, patolli pada abad ke-16, Tenshō karuta pada 1633, pinball pada 1940-an. ✓ menandai larangan yang dicabut (pinball di New York 1976, catur di Iran 1988)"]},{"h":"Mengapa melarang permainan?","p":["Alasan paling umum adalah judi: penguasa khawatir orang kehilangan hartanya atau berkelahi. Ada pula larangan yang memperingatkan agar tidak melalaikan pekerjaan atau kewajiban.","Ada juga alasan agama, serta kewaspadaan terhadap kerumunan yang berkumpul dan membuat keributan. Namun apa pun alasannya, sedikit larangan yang mempersoalkan permainan yang sama tanpa taruhan."],"cap":["Alasan larangan. Yang paling umum adalah judi (sugoroku, kartu, pinball); lainnya melalaikan pekerjaan atau kewajiban (kitab Yōrō untuk biksu dan biksuni), agama (patolli, catur di Iran), dan ketertiban"]},{"h":"Apakah larangan berhasil?","p":["Kebanyakan tidak mampu menghentikan permainan. Sugoroku dimainkan lebih dari seribu tahun setelah larangan pertama, dan kartu lolos dari setiap dekret hingga menyebar ke seluruh dunia.","Hanya patolli, yang perlengkapannya dihancurkan, hilang dari kehidupan sehari-hari bersama doa yang menyertainya. Mungkin larangan baru benar-benar berhasil ketika seluruh budaya bermain ditekan."],"cap":["Setelah larangan: sugoroku terus dimainkan (garis berlanjut), patolli hampir lenyap (×), kartu lolos dari larangan dan menyebar (garis bercabang)"]},{"h":"Coba mainkan","p":["Di Atlas ini kamu bisa memainkan backgammon, kerabat sugoroku, patolli dari Aztek, dan solitaire, permainan untuk satu orang yang sama sekali tak berhubungan dengan judi.","Semuanya dibuat untuk menikmati aturan dan taktik tanpa mempertaruhkan apa pun. Rasakan keseruan sejati permainan yang dulu pernah dilarang."],"cap":[]}],"tl":[["689","Maharani Jitō melarang sugoroku (Nihon Shoki)"],["1254","Maklumat Louis IX melawan judi"],["1377","Firenze melarang permainan kartu"],["1633","Keshogunan melarang Tenshō karuta"],["1976","New York mencabut larangan pinball"]],"figL":{"time":[["689","Sugoroku","Maharani Jitō, Jepang"],["1254","Judi","Louis IX, Prancis"],["1377","Kartu","Firenze"],["abad 16","Patolli","biarawan Spanyol, Meksiko"],["1633","Tenshō karuta","Keshogunan Tokugawa"],["± 1942","Pinball","New York"],["1976","✓ Pinball","New York: permainan keterampilan"],["1988","✓ Catur","Iran: boleh tanpa judi"]],"why":[["Judi","sugoroku, kartu","pinball"],["Lalai kerja dan kewajiban","kitab Yōrō: biksu",""],["Agama","patolli","catur di Iran"],["Ketertiban","kerumunan orang",""]],"out":[["Sugoroku","dimainkan 1000+ tahun"],["Patolli","hampir lenyap"],["Kartu","menyebar ke dunia"]]}}};
